--
-- Name: cairn_activate_partner_bank_profile(uuid, character varying, uuid, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: public; Owner: cairn_integration_migrator
--

CREATE FUNCTION public.cairn_activate_partner_bank_profile(p_event_id uuid, p_actor_client character varying, p_actor_user_id uuid, p_country_code character varying, p_expected_policy_revision character varying, p_expected_version integer, p_evidence_code character varying) RETURNS character varying
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_profile public.partner_bank_country_profile%ROWTYPE;
  v_new_version integer;
BEGIN
  IF p_event_id IS NULL
    OR substring(p_event_id::text from 15 for 1) <> '4'
    OR substring(p_event_id::text from 20 for 1) NOT IN ('8', '9', 'a', 'b')
    OR p_actor_client IS NULL
    OR p_actor_client !~ '^[A-Za-z0-9]{2,4}$'
    OR p_actor_user_id IS NULL
    OR p_country_code IS NULL
    OR p_country_code !~ '^[A-Z]{2}$'
    OR p_expected_policy_revision IS NULL
    OR p_expected_policy_revision !~ '^D-[0-9]{3}$'
    OR p_expected_version IS NULL
    OR p_expected_version < 1
  THEN
    RETURN 'INPUT_INVALID';
  END IF;

  IF p_evidence_code IS DISTINCT FROM 'PROFILE_VALIDATION_ACCEPTED' THEN
    RETURN 'EVIDENCE_INVALID';
  END IF;

  -- Serialize concurrent attempts for this country before checking status/version.
  SELECT p.*
    INTO v_profile
    FROM public.partner_bank_country_profile AS p
   WHERE p.country_code = p_country_code
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN 'PROFILE_UNAVAILABLE';
  END IF;

  IF v_profile.policy_revision IS DISTINCT FROM p_expected_policy_revision THEN
    RETURN 'POLICY_REVISION_MISMATCH';
  END IF;

  IF v_profile.readiness_status = 'READY' THEN
    RETURN 'PROFILE_ALREADY_READY';
  END IF;

  IF v_profile.version <> p_expected_version THEN
    RETURN 'VERSION_MISMATCH';
  END IF;

  IF v_profile.version = 2147483647 THEN
    RETURN 'VERSION_EXHAUSTED';
  END IF;

  -- Repeat the guards in the UPDATE as a second line of defence. If anything
  -- unexpected prevents exactly one row changing, do not emit an audit event.
  UPDATE public.partner_bank_country_profile AS p
     SET readiness_status = 'READY',
         version = v_profile.version + 1,
         changed_by = p_actor_client || ':' || p_actor_user_id::text,
         changed_at = clock_timestamp()
   WHERE p.country_code = p_country_code
     AND p.policy_revision = p_expected_policy_revision
     AND p.readiness_status = 'NOT_READY'
     AND p.version = p_expected_version
  RETURNING p.version INTO v_new_version;

  IF NOT FOUND THEN
    RETURN 'UPDATE_CONFLICT';
  END IF;

  -- Any insert failure aborts this function call's transaction, rolling back the
  -- readiness update as well; successful activation and its evidence commit together.
  INSERT INTO public.partner_bank_profile_activation_audit (
    event_id,
    actor_client,
    actor_user_id,
    country_code,
    policy_revision,
    previous_status,
    new_status,
    previous_version,
    new_version,
    evidence_code
  ) VALUES (
    p_event_id,
    p_actor_client,
    p_actor_user_id,
    p_country_code,
    v_profile.policy_revision,
    v_profile.readiness_status,
    'READY',
    v_profile.version,
    v_new_version,
    p_evidence_code
  );

  RETURN 'ACTIVATED';
END;
$_$;


ALTER FUNCTION public.cairn_activate_partner_bank_profile(p_event_id uuid, p_actor_client character varying, p_actor_user_id uuid, p_country_code character varying, p_expected_policy_revision character varying, p_expected_version integer, p_evidence_code character varying) OWNER TO cairn_integration_migrator;

--
-- Name: cairn_assert_company_code_refs(); Type: FUNCTION; Schema: public; Owner: cairn_integration_migrator
--

CREATE FUNCTION public.cairn_assert_company_code_refs() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.chart_of_accounts IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM chart_of_accounts
    WHERE client = NEW.client AND chart_of_accounts = NEW.chart_of_accounts
  ) THEN
    RAISE EXCEPTION
      'CAIRN_CONFIG_MISSING: chart of accounts % is not defined for this tenant.',
      NEW.chart_of_accounts
      USING ERRCODE = 'foreign_key_violation',
            HINT = 'Define the chart of accounts first (CFG.FIN.COA.DEFINE), then assign it.';
  END IF;

  IF NEW.fiscal_year_variant IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM fiscal_year_variant
    WHERE client = NEW.client AND variant = NEW.fiscal_year_variant
  ) THEN
    RAISE EXCEPTION
      'CAIRN_CONFIG_MISSING: fiscal year variant % is not defined for this tenant.',
      NEW.fiscal_year_variant
      USING ERRCODE = 'foreign_key_violation',
            HINT = 'Define the fiscal year variant first (CFG.FIN.FYV.DEFINE), then assign it.';
  END IF;

  IF NEW.posting_period_variant IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM posting_period_variant
    WHERE client = NEW.client AND variant = NEW.posting_period_variant
  ) THEN
    RAISE EXCEPTION
      'CAIRN_CONFIG_MISSING: posting period variant % is not defined for this tenant.',
      NEW.posting_period_variant
      USING ERRCODE = 'foreign_key_violation',
            HINT = 'Define the posting period variant first (CFG.FIN.PPV.DEFINE), then assign it.';
  END IF;

  RETURN NEW;
END $$;


ALTER FUNCTION public.cairn_assert_company_code_refs() OWNER TO cairn_integration_migrator;

--
-- Name: cairn_assert_journal_balances(); Type: FUNCTION; Schema: public; Owner: cairn_integration_migrator
--

CREATE FUNCTION public.cairn_assert_journal_balances() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  rec          record;
  v_debit      numeric(23,4);
  v_credit     numeric(23,4);
BEGIN
  IF TG_OP = 'DELETE' THEN
    rec := OLD;
  ELSE
    rec := NEW;
  END IF;

  SELECT
    COALESCE(SUM(CASE WHEN debit_credit = 'S' THEN amount_local END), 0),
    COALESCE(SUM(CASE WHEN debit_credit = 'H' THEN amount_local END), 0)
  INTO v_debit, v_credit
  FROM journal_entry_line
  WHERE client          = rec.client
    AND document_number = rec.document_number
    AND fiscal_year     = rec.fiscal_year;

  IF v_debit <> v_credit THEN
    RAISE EXCEPTION
      'CAIRN_UNBALANCED: accounting document % (fiscal year %) does not balance — debits % vs credits %. Difference %.',
      rec.document_number, rec.fiscal_year, v_debit, v_credit, v_debit - v_credit
      USING ERRCODE = 'check_violation',
            HINT = 'Nothing was saved. Correct the amounts so total debits equal total credits.';
  END IF;

  RETURN NULL;
END $$;


ALTER FUNCTION public.cairn_assert_journal_balances() OWNER TO cairn_integration_migrator;

--
-- Name: cairn_config_readiness(character varying); Type: FUNCTION; Schema: public; Owner: cairn_integration_migrator
--

CREATE FUNCTION public.cairn_config_readiness(p_client character varying) RETURNS TABLE(total_activities bigint, completed_activities bigint, next_activity character varying, next_activity_title character varying, next_activity_route character varying)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH scoped AS (
    SELECT s.activity_code, s.status, a.sequence, a.title, a.route_path
    FROM config_activity_status s
    JOIN config_activity a ON a.code = s.activity_code
    WHERE s.client = p_client
  ),
  counts AS (
    SELECT count(*) AS total,
           count(*) FILTER (WHERE status = 'COMPLETED') AS completed
    FROM scoped
  ),
  nxt AS (
    SELECT activity_code, title, route_path
    FROM scoped
    WHERE status <> 'COMPLETED'
    ORDER BY sequence
    LIMIT 1
  )
  SELECT counts.total, counts.completed,
         nxt.activity_code, nxt.title, nxt.route_path
  FROM counts LEFT JOIN nxt ON true;
$$;


ALTER FUNCTION public.cairn_config_readiness(p_client character varying) OWNER TO cairn_integration_migrator;

