--
-- Name: coa_key_registry_exclusive(); Type: FUNCTION; Schema: public; Owner: cairn_integration_migrator
--

CREATE FUNCTION public.coa_key_registry_exclusive() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  tenant varchar(4);
  reserved_key varchar(4);
BEGIN
  IF tg_table_name = 'chart_of_accounts' THEN
    tenant := new.client;
    reserved_key := new.chart_of_accounts;
    IF EXISTS (
      SELECT 1 FROM group_chart_of_accounts registry
      WHERE registry.client = tenant
        AND registry.group_chart_of_accounts = reserved_key
    ) THEN
      RAISE EXCEPTION 'Chart of Accounts key % is reserved as a Group CoA in this tenant', reserved_key
        USING ERRCODE = 'unique_violation';
    END IF;
  ELSE
    tenant := new.client;
    reserved_key := new.group_chart_of_accounts;
    IF EXISTS (
      SELECT 1 FROM chart_of_accounts chart
      WHERE chart.client = tenant
        AND chart.chart_of_accounts = reserved_key
    ) THEN
      RAISE EXCEPTION 'Group CoA key % is reserved as an operational Chart of Accounts in this tenant', reserved_key
        USING ERRCODE = 'unique_violation';
    END IF;
  END IF;
  RETURN new;
END;
$$;


ALTER FUNCTION public.coa_key_registry_exclusive() OWNER TO cairn_integration_migrator;

--
-- Name: production_confirmation_reject_second_active_final(); Type: FUNCTION; Schema: public; Owner: cairn_integration_migrator
--

CREATE FUNCTION public.production_confirmation_reject_second_active_final() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.confirmation_type IS DISTINCT FROM 'FINAL' THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.client || '|CO13-FINAL|' || NEW.order_number, 0));

  IF TG_TABLE_NAME = 'production_confirmation' THEN
    IF NEW.confirmation_level = 'HEADER' THEN
      IF EXISTS (
        SELECT 1
          FROM production_confirmation c
         WHERE c.client = NEW.client
           AND c.order_number = NEW.order_number
           AND c.confirmation_level = 'HEADER'
           AND c.confirmation_type = 'FINAL'
           AND c.confirmation_number <> NEW.confirmation_number
           AND NOT EXISTS (
             SELECT 1 FROM production_confirmation_cancellation x
              WHERE x.client = c.client AND x.confirmation_number = c.confirmation_number
           )
      ) THEN
        RAISE EXCEPTION 'active final confirmation already stands'
          USING ERRCODE = 'unique_violation';
      END IF;
    ELSIF NEW.confirmation_level = 'OPERATION' THEN
      IF EXISTS (
        SELECT 1
          FROM production_confirmation c
         WHERE c.client = NEW.client
           AND c.order_number = NEW.order_number
           AND c.confirmation_level = 'OPERATION'
           AND c.operation_number = NEW.operation_number
           AND c.confirmation_type = 'FINAL'
           AND c.confirmation_number <> NEW.confirmation_number
           AND NOT EXISTS (
             SELECT 1 FROM production_confirmation_cancellation x
              WHERE x.client = c.client AND x.confirmation_number = c.confirmation_number
           )
      ) OR EXISTS (
        SELECT 1
          FROM production_confirmation_operation e
         WHERE e.client = NEW.client
           AND e.order_number = NEW.order_number
           AND e.operation_number = NEW.operation_number
           AND e.confirmation_type = 'FINAL'
           AND NOT EXISTS (
             SELECT 1 FROM production_confirmation_cancellation x
              WHERE x.client = e.client AND x.confirmation_number = e.confirmation_number
           )
      ) THEN
        RAISE EXCEPTION 'active final confirmation already stands'
          USING ERRCODE = 'unique_violation';
      END IF;
    END IF;
  ELSIF TG_TABLE_NAME = 'production_confirmation_operation' THEN
    IF EXISTS (
      SELECT 1
        FROM production_confirmation_operation e
       WHERE e.client = NEW.client
         AND e.order_number = NEW.order_number
         AND e.operation_number = NEW.operation_number
         AND e.confirmation_type = 'FINAL'
         AND e.confirmation_number <> NEW.confirmation_number
         AND NOT EXISTS (
           SELECT 1 FROM production_confirmation_cancellation x
            WHERE x.client = e.client AND x.confirmation_number = e.confirmation_number
         )
    ) OR EXISTS (
      SELECT 1
        FROM production_confirmation c
       WHERE c.client = NEW.client
         AND c.order_number = NEW.order_number
         AND c.confirmation_level = 'OPERATION'
         AND c.operation_number = NEW.operation_number
         AND c.confirmation_type = 'FINAL'
         AND NOT EXISTS (
           SELECT 1 FROM production_confirmation_cancellation x
            WHERE x.client = c.client AND x.confirmation_number = c.confirmation_number
         )
    ) THEN
      RAISE EXCEPTION 'active final confirmation already stands'
        USING ERRCODE = 'unique_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.production_confirmation_reject_second_active_final() OWNER TO cairn_integration_migrator;

--
-- Name: production_gm_attempt_protect_revision(); Type: FUNCTION; Schema: public; Owner: cairn_integration_migrator
--

CREATE FUNCTION public.production_gm_attempt_protect_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(NEW.client, NEW.id, NEW.failure_id, NEW.attempt_number, NEW.payload_revision,
         NEW.lease_token, NEW.attempted_by, NEW.started_at)
     IS DISTINCT FROM
     ROW(OLD.client, OLD.id, OLD.failure_id, OLD.attempt_number, OLD.payload_revision,
         OLD.lease_token, OLD.attempted_by, OLD.started_at) THEN
    RAISE EXCEPTION 'Goods-movement attempt identity and payload revision are immutable.'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.production_gm_attempt_protect_revision() OWNER TO cairn_integration_migrator;

--
-- Name: production_gm_failure_protect_source(); Type: FUNCTION; Schema: public; Owner: cairn_integration_migrator
--

CREATE FUNCTION public.production_gm_failure_protect_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status = 'DISCARDED' THEN
    RAISE EXCEPTION 'A discarded goods-movement failure is a terminal retained record.'
      USING ERRCODE = '23514';
  END IF;
  IF ROW(
    NEW.client, NEW.id, NEW.source_transaction, NEW.source_document_class,
    NEW.source_document_number, NEW.confirmation_number, NEW.confirmation_request_key,
    NEW.order_number, NEW.operation_number, NEW.plant, NEW.movement_kind,
    NEW.movement_type, NEW.posting_date, NEW.document_date, NEW.header_text,
    NEW.original_request_key, NEW.idempotency_fingerprint, NEW.original_payload
  ) IS DISTINCT FROM ROW(
    OLD.client, OLD.id, OLD.source_transaction, OLD.source_document_class,
    OLD.source_document_number, OLD.confirmation_number, OLD.confirmation_request_key,
    OLD.order_number, OLD.operation_number, OLD.plant, OLD.movement_kind,
    OLD.movement_type, OLD.posting_date, OLD.document_date, OLD.header_text,
    OLD.original_request_key, OLD.idempotency_fingerprint, OLD.original_payload
  ) THEN
    RAISE EXCEPTION 'CO11N source intent is immutable; create a COGI correction revision instead.'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.production_gm_failure_protect_source() OWNER TO cairn_integration_migrator;

--
-- Name: production_order_availability_append_only(); Type: FUNCTION; Schema: public; Owner: cairn_integration_migrator
--

CREATE FUNCTION public.production_order_availability_append_only() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- A complete tenant teardown is the one allowed removal boundary. Normal
  -- deletes (including component removal) stay blocked while the client exists.
  -- FK cascades run at nested trigger depth only after the client row is gone.
  IF TG_OP = 'DELETE'
     AND pg_trigger_depth() > 1
     AND NOT EXISTS (SELECT 1 FROM public.client c WHERE c.client = OLD.client) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'CO09 availability runs and commitment events are append-only.'
    USING ERRCODE = '23514';
END;
$$;


ALTER FUNCTION public.production_order_availability_append_only() OWNER TO cairn_integration_migrator;

--
-- Name: purchase_order_assignment_category_object(); Type: FUNCTION; Schema: public; Owner: cairn_integration_migrator
--

CREATE FUNCTION public.purchase_order_assignment_category_object() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_category varchar(20);
begin
  select i.account_assignment_category
    into v_category
    from public.purchase_order_item i
   where i.client = new.client
     and i.order_number = new.order_number
     and i.item_number = new.item_number;

  if v_category is null then
    raise exception
      'Item % of order % carries no account assignment category, so this row has no object to name.',
      new.item_number, new.order_number
      using errcode = '23514';
  end if;

  if v_category = 'COST_CENTER' and (new.cost_center is null or new.internal_order is not null or new.asset_number is not null) then
    raise exception
      'Item % of order % is assigned to a cost centre (K), so this row must name a cost centre and no other object.',
      new.item_number, new.order_number
      using errcode = '23514';
  elsif v_category = 'ORDER' and (new.internal_order is null or new.cost_center is not null or new.asset_number is not null) then
    raise exception
      'Item % of order % is assigned to an internal order (F), so this row must name an internal order and no other object.',
      new.item_number, new.order_number
      using errcode = '23514';
  elsif v_category = 'ASSET' and (new.asset_number is null or new.cost_center is not null or new.internal_order is not null) then
    raise exception
      'Item % of order % is assigned to an asset (A), so this row must name an asset and no other object.',
      new.item_number, new.order_number
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.purchase_order_assignment_category_object() OWNER TO cairn_integration_migrator;

--
-- Name: purchase_order_item_category_recheck(); Type: FUNCTION; Schema: public; Owner: cairn_integration_migrator
--

CREATE FUNCTION public.purchase_order_item_category_recheck() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.account_assignment_category is not distinct from old.account_assignment_category then
    return new;
  end if;
  -- The row-level trigger performs the judgement; this only asks it to run.
  update public.purchase_order_assignment a
     set changed_at = a.changed_at
   where a.client = new.client
     and a.order_number = new.order_number
     and a.item_number = new.item_number;
  return new;
end;
$$;


ALTER FUNCTION public.purchase_order_item_category_recheck() OWNER TO cairn_integration_migrator;

