--
-- Name: account_determination; Type: TABLE; Schema: public; Owner: cairn_integration_migrator
--

CREATE TABLE public.account_determination (
    client character varying(4) NOT NULL,
    chart_of_accounts character varying(4) NOT NULL,
    event character varying(24) NOT NULL,
    valuation_class character varying(20) DEFAULT ''::character varying NOT NULL,
    general_modifier character varying(4) DEFAULT ''::character varying NOT NULL,
    gl_account character varying(10) NOT NULL,
    created_by character varying(60) DEFAULT 'SYSTEM'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
