    delivery_number character varying(20),
    sales_org character varying(4) NOT NULL,
    distribution_channel character varying(2) NOT NULL,
    division character varying(2) NOT NULL,
    customer_number character varying(40) NOT NULL,
    company_code character varying(10) NOT NULL,
    currency character(3) NOT NULL,
    billing_date date NOT NULL,
    posting_date date,
    status character varying(16) DEFAULT 'OPEN'::character varying NOT NULL,
    net_value numeric(23,4) DEFAULT 0 NOT NULL,
    tax_value numeric(23,4) DEFAULT 0 NOT NULL,
    gross_value numeric(23,4) DEFAULT 0 NOT NULL,
    customer_invoice_number character varying(20),
    journal_document_number character varying(20),
    reference_document_text character varying(100),
    version integer DEFAULT 1 NOT NULL,
    request_key character varying(64),
    created_by character varying(60) DEFAULT 'SYSTEM'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by character varying(60),
    changed_at timestamp with time zone,
    credit_of character varying(20),
    cancellation_of character varying(20),
    down_payment_clearing_number character varying(20),
    down_payment_cleared_amount numeric(23,4) DEFAULT '0'::numeric NOT NULL,
    invoice_list_type character varying(4),
    invoice_list_date date,
    invoice_list_status character varying(12) DEFAULT 'NOT_RELEVANT'::character varying NOT NULL,
    invoice_list_number character varying(20),
    CONSTRAINT billing_document_cleared_amount_ck CHECK ((down_payment_cleared_amount >= (0)::numeric)),
    CONSTRAINT billing_document_credit_reference_ck CHECK ((((document_type)::text = 'G2'::text) = (credit_of IS NOT NULL))),
    CONSTRAINT billing_document_date_ck CHECK (((posting_date IS NULL) OR (posting_date >= billing_date))),
    CONSTRAINT billing_document_invoice_list_relevance_ck CHECK (((invoice_list_type IS NULL) = (invoice_list_date IS NULL))),
    CONSTRAINT billing_document_invoice_list_status_ck CHECK (((invoice_list_status)::text = ANY ((ARRAY['NOT_RELEVANT'::character varying, 'DUE'::character varying, 'LISTED'::character varying])::text[]))),
    CONSTRAINT billing_document_invoice_listed_ck CHECK ((((invoice_list_status)::text <> 'LISTED'::text) OR (invoice_list_number IS NOT NULL))),
    CONSTRAINT billing_document_posted_needs_invoice_ck CHECK ((((status)::text <> 'POSTED'::text) OR ((document_type)::text = 'DP'::text) OR (invoice_list_number IS NOT NULL) OR ((customer_invoice_number IS NOT NULL) AND (journal_document_number IS NOT NULL)))),
    CONSTRAINT billing_document_status_ck CHECK (((status)::text = ANY ((ARRAY['OPEN'::character varying, 'POSTED'::character varying, 'CANCELLED'::character varying])::text[]))),
    CONSTRAINT billing_document_type_ck CHECK (((document_type)::text ~ '^[A-Z0-9]{2}$'::text)),
    CONSTRAINT billing_document_value_ck CHECK ((((cancellation_of IS NULL) AND (credit_of IS NULL) AND (net_value >= (0)::numeric) AND (tax_value >= (0)::numeric) AND (gross_value >= (0)::numeric)) OR ((cancellation_of IS NOT NULL) AND (net_value <= (0)::numeric) AND (tax_value <= (0)::numeric) AND (gross_value <= (0)::numeric)) OR ((credit_of IS NOT NULL) AND (net_value <= (0)::numeric) AND (tax_value <= (0)::numeric) AND (gross_value <= (0)::numeric)))),
    CONSTRAINT billing_document_version_ck CHECK ((version > 0))
);

