    invoice_list_schedule character varying(12) DEFAULT 'NONE'::character varying NOT NULL,
    CONSTRAINT customer_sales_account_group CHECK (((account_assignment_group IS NULL) OR ((account_assignment_group)::text ~ '^[A-Z0-9]{1,4}$'::text))),
    CONSTRAINT customer_sales_area_sales_org_key_format_ck CHECK (((sales_org)::text ~ '^[A-Z0-9]{4}$'::text)),
    CONSTRAINT customer_sales_district CHECK (((sales_district IS NULL) OR ((sales_district)::text ~ '^[A-Z0-9]{1,6}$'::text))),
    CONSTRAINT customer_sales_invoice_list_ck CHECK (((invoice_list_schedule)::text = ANY ((ARRAY['NONE'::character varying, 'WEEKLY'::character varying, 'MONTHLY'::character varying])::text[]))),
    CONSTRAINT customer_sales_max_partial_ck CHECK (((max_partial_deliveries >= 0) AND (max_partial_deliveries <= 9))),
    CONSTRAINT customer_sales_partial_delivery_ck CHECK (((partial_delivery_indicator)::text = ANY ((ARRAY[''::character varying, 'C'::character varying])::text[]))),
    CONSTRAINT customer_sales_pricing_procedure CHECK (((pricing_procedure IS NULL) OR ((pricing_procedure)::text ~ '^[A-Z0-9]{1,6}$'::text))),
    CONSTRAINT customer_sales_role CHECK (((role_code)::text = 'CUSTOMER'::text)),
    CONSTRAINT customer_sales_status CHECK (((sales_status)::text = ANY ((ARRAY['INCOMPLETE'::character varying, 'CREATED'::character varying, 'MAINTAINED'::character varying])::text[]))),
    CONSTRAINT customer_sales_version CHECK ((version > 0))
);

