    changed_at timestamp with time zone,
    CONSTRAINT customer_sales_partner_area_ck CHECK (((((sales_org)::text = ''::text) OR ((sales_org)::text ~ '^[A-Z0-9]{1,4}$'::text)) AND (((distribution_channel)::text = ''::text) OR ((distribution_channel)::text ~ '^[A-Z0-9]{1,4}$'::text)) AND (((division)::text = ''::text) OR ((division)::text ~ '^[A-Z0-9]{1,4}$'::text)))),
    CONSTRAINT customer_sales_partner_function_ck CHECK (((function_code)::text <> 'SP'::text)),
    CONSTRAINT customer_sales_partner_role_ck CHECK ((((partner_role_code)::text = 'CUSTOMER'::text) AND ((assigned_role_code)::text = 'CUSTOMER'::text))),
    CONSTRAINT customer_sales_partner_version_ck CHECK ((version > 0))
);


ALTER TABLE public.customer_sales_partner OWNER TO cairn_integration_migrator;

--
-- Name: TABLE customer_sales_partner; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON TABLE public.customer_sales_partner IS 'Who plays each partner function for a customer (SAP KNVP), maintained for one sales area or for all of them. The most specific row that fits answers; a function nobody maintains falls back to the one above it — the payer to the bill-to, and the ship-to and the bill-to to the sold-to.';


--
