--

CREATE TABLE public.delivery (
    client character varying(4) NOT NULL,
    delivery_number character varying(20) NOT NULL,
    document_type character varying(4) DEFAULT 'LF'::character varying NOT NULL,
    order_number character varying(20) NOT NULL,
    sales_org character varying(4) NOT NULL,
