    CONSTRAINT delivery_date_ck CHECK (((goods_movement_date IS NULL) OR (goods_movement_date >= delivery_date))),
    CONSTRAINT delivery_goods_issue_stands_ck CHECK (((NOT goods_issue_stands) OR (material_document_number IS NOT NULL))),
    CONSTRAINT delivery_issued_issue_stands_ck CHECK ((((status)::text <> 'GOODS_ISSUED'::text) OR goods_issue_stands)),
    CONSTRAINT delivery_issued_needs_document_ck CHECK ((((status)::text <> 'GOODS_ISSUED'::text) OR ((material_document_number IS NOT NULL) AND (material_document_year IS NOT NULL)))),
    CONSTRAINT delivery_received_needs_document_ck CHECK ((((status)::text <> 'RECEIVED'::text) OR ((material_document_number IS NOT NULL) AND (material_document_year IS NOT NULL)))),
    CONSTRAINT delivery_returns_reference_ck CHECK ((((document_type)::text = 'LR'::text) = (reference_delivery_number IS NOT NULL))),
    CONSTRAINT delivery_status_ck CHECK (((status)::text = ANY ((ARRAY['OPEN'::character varying, 'PICKED'::character varying, 'GOODS_ISSUED'::character varying, 'CANCELLED'::character varying, 'RECEIVED'::character varying])::text[]))),
    CONSTRAINT delivery_type_ck CHECK (((document_type)::text ~ '^[A-Z0-9]{2}$'::text)),
    CONSTRAINT delivery_version_ck CHECK ((version > 0))
);

ALTER TABLE ONLY public.delivery FORCE ROW LEVEL SECURITY;


ALTER TABLE public.delivery OWNER TO cairn_integration_migrator;

--
-- Name: TABLE delivery; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON TABLE public.delivery IS 'Outbound delivery header — LIKP. CAIRN.md §14.7 and the delivery row of §20. Created from open order quantities, priced nowhere, posting nothing until its goods issue names a material document; check points of the credit ladder stand at its creation (D-029).';


--
-- Name: COLUMN delivery.reference_delivery_number; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON COLUMN public.delivery.reference_delivery_number IS 'Set only on a returns delivery (LR): the delivery the goods went out on and are coming back against. Every quantity that has come back is answerable from this document and from the returned_quantity on the lines it names.';


--
-- Name: COLUMN delivery.goods_issue_stands; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON COLUMN public.delivery.goods_issue_stands IS 'Whether the goods issue this delivery posted still stands: true from the moment the movement posts, false when that movement is reversed. A delivery that stands GOODS_ISSUED is a delivery whose goods are out, so undoing the issue undoes the status with it.';


--
-- Name: COLUMN delivery.shipping_point; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON COLUMN public.delivery.shipping_point IS 'The dock this delivery loads from, determined when it was created from the ship-to''s shipping condition, the material''s loading group and the delivering plant. Null on a delivery raised before the determination stood.';


--
-- Name: COLUMN delivery.ship_to_name; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON COLUMN public.delivery.ship_to_name IS 'Where the goods went. A delivery carries the address it was raised with, not the one that customer''s master carries now: remaking a customer next month must not rewrite where last month''s goods were delivered.';


--
-- Name: delivery_line; Type: TABLE; Schema: public; Owner: cairn_integration_migrator
--

CREATE TABLE public.delivery_line (
    client character varying(4) NOT NULL,
    delivery_number character varying(20) NOT NULL,
    line_number integer NOT NULL,
    order_number character varying(20) NOT NULL,
    order_line_number integer NOT NULL,
    material_number character varying(40) NOT NULL,
    plant character varying(10) NOT NULL,
    quantity_unit character(6) NOT NULL,
    ordered_quantity numeric(13,3) NOT NULL,
    delivered_before numeric(13,3) DEFAULT 0 NOT NULL,
    delivery_quantity numeric(13,3) NOT NULL,
    remaining_quantity numeric(13,3) NOT NULL,
    picked_quantity numeric(13,3) DEFAULT 0 NOT NULL,
    goods_issue_quantity numeric(13,3) DEFAULT 0 NOT NULL,
    status character varying(16) DEFAULT 'OPEN'::character varying NOT NULL,
    created_by character varying(60) DEFAULT 'SYSTEM'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by character varying(60),
    changed_at timestamp with time zone,
    returned_quantity numeric(13,3) DEFAULT 0 NOT NULL,
    confirmed_quantity numeric(13,3),
    CONSTRAINT delivery_line_confirmed_ck CHECK (((confirmed_quantity IS NULL) OR ((confirmed_quantity >= (0)::numeric) AND (confirmed_quantity <= ordered_quantity)))),
    CONSTRAINT delivery_line_issue_completeness_ck CHECK ((((status)::text <> 'GOODS_ISSUED'::text) OR ((picked_quantity = delivery_quantity) AND (goods_issue_quantity = delivery_quantity)))),
    CONSTRAINT delivery_line_issued_ck CHECK (((goods_issue_quantity >= (0)::numeric) AND (goods_issue_quantity <= picked_quantity))),
    CONSTRAINT delivery_line_number_ck CHECK (((line_number > 0) AND (order_line_number > 0))),
    CONSTRAINT delivery_line_picked_ck CHECK (((picked_quantity >= (0)::numeric) AND (picked_quantity <= delivery_quantity))),
    CONSTRAINT delivery_line_quantity_ck CHECK (((ordered_quantity > (0)::numeric) AND (delivery_quantity > (0)::numeric) AND (delivered_before >= (0)::numeric))),
    CONSTRAINT delivery_line_remaining_ck CHECK (((remaining_quantity = ((ordered_quantity - delivered_before) - delivery_quantity)) AND (remaining_quantity >= (0)::numeric))),
    CONSTRAINT delivery_line_returned_ck CHECK (((returned_quantity >= (0)::numeric) AND (returned_quantity <= goods_issue_quantity))),
    CONSTRAINT delivery_line_status_ck CHECK (((status)::text = ANY ((ARRAY['OPEN'::character varying, 'PICKED'::character varying, 'GOODS_ISSUED'::character varying, 'RECEIVED'::character varying])::text[])))
);

ALTER TABLE ONLY public.delivery_line FORCE ROW LEVEL SECURITY;


ALTER TABLE public.delivery_line OWNER TO cairn_integration_migrator;

--
-- Name: TABLE delivery_line; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON TABLE public.delivery_line IS 'One item of an outbound delivery — LIPS. Ordered, already-delivered and remaining quantities are carried on the line so the over-delivery refusal is visible in the row, and picked and issued quantities move only with the confirmation and the posting that caused them.';


--
-- Name: COLUMN delivery_line.returned_quantity; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON COLUMN public.delivery_line.returned_quantity IS 'How much of the goods-issued quantity has been received back from the customer (movement 651). Returns stock is not valuated, so this quantity carries no value: it becomes stock again only when a transfer takes it out of returns stock into valuated stock.';


--
-- Name: COLUMN delivery_line.confirmed_quantity; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON COLUMN public.delivery_line.confirmed_quantity IS 'What the availability check had confirmed on the order line when this delivery was created (SAP: the confirmed quantity of the schedule line it was made from). Null on a delivery raised before a check stood. It is not re-derived: it says what the plant had promised on the day.';


--
-- Name: delivery_picking; Type: TABLE; Schema: public; Owner: cairn_integration_migrator
--

CREATE TABLE public.delivery_picking (
    client character varying(4) NOT NULL,
    delivery_number character varying(20) NOT NULL,
    line_number integer NOT NULL,
    pick_number integer NOT NULL,
    quantity_delta numeric(13,3) NOT NULL,
    storage_location character varying(10) NOT NULL,
    batch_number character varying(40) DEFAULT ''::character varying NOT NULL,
    reason character varying(60),
    request_key character varying(64),
    created_by character varying(60) DEFAULT 'SYSTEM'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT delivery_picking_delta_ck CHECK ((quantity_delta <> (0)::numeric)),
    CONSTRAINT delivery_picking_number_ck CHECK ((pick_number > 0))
);

ALTER TABLE ONLY public.delivery_picking FORCE ROW LEVEL SECURITY;


ALTER TABLE public.delivery_picking OWNER TO cairn_integration_migrator;

--
-- Name: TABLE delivery_picking; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON TABLE public.delivery_picking IS 'A picking confirmation against one delivery item — the VBPB/LIPS picking history. Append-only by design: a mistaken confirmation is answered by a correcting row of the opposite sign, which is what keeps the pick auditable and what stops a pick from silently rewriting the past.';


