    created_by character varying(60) DEFAULT 'SYSTEM'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by character varying(60),
    changed_at timestamp with time zone
);


ALTER TABLE public.delivery_picking_serial OWNER TO cairn_integration_migrator;

--
-- Name: TABLE delivery_picking_serial; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON TABLE public.delivery_picking_serial IS 'Which unit went out on which pick row (§5.5b). Append-only, like the picking history it belongs to: a correction is a row of the opposite sign, not an edit of this one. The serial itself carries the delivery it went on, so this table is the pick''s side of the record — the answer to "what did we actually hand over" that a picking quantity cannot give.';


