    CONSTRAINT partner_bank_local_account_envelope CHECK (((local_account_number_ciphertext IS NULL) OR (((local_account_number_ciphertext)::text ~ '^cbd1[.][A-Za-z0-9_-]{1,32}[.][A-Za-z0-9_-]{16}[.][A-Za-z0-9_-]+[.][A-Za-z0-9_-]{22}$'::text) AND (char_length((local_account_number_ciphertext)::text) <= 5540)))),
    CONSTRAINT partner_bank_one_account_identifier CHECK ((((iban_ciphertext IS NOT NULL) AND (local_account_number_ciphertext IS NULL)) OR ((iban_ciphertext IS NULL) AND (local_account_number_ciphertext IS NOT NULL)))),
