    CONSTRAINT production_checking_control_no_check_ck CHECK (((no_check)::text = ANY ((ARRAY['X'::character varying, ' '::character varying])::text[]))),
    CONSTRAINT production_checking_control_plant_ck CHECK (((char_length((plant)::text) >= 1) AND (char_length((plant)::text) <= 10))),
    CONSTRAINT production_checking_control_rule_ck CHECK (((checking_rule IS NULL) OR ((checking_rule)::text ~ '^[A-Z0-9]{2}$'::text))),
    CONSTRAINT production_checking_control_save_ck CHECK (((check_on_save)::text = ANY ((ARRAY['X'::character varying, ' '::character varying])::text[]))),
    CONSTRAINT production_checking_control_type_ck CHECK (((order_type)::text ~ '^[A-Z0-9]{4}$'::text)),
    CONSTRAINT production_checking_control_version_ck CHECK ((version > 0))
);

ALTER TABLE ONLY public.production_checking_control FORCE ROW LEVEL SECURITY;


ALTER TABLE public.production_checking_control OWNER TO cairn_integration_migrator;

--
-- Name: TABLE production_checking_control; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON TABLE public.production_checking_control IS 'OPJK checking control. Key is plant, order type, and business function. A missing row is unconfigured. No check runs.';


--
-- Name: COLUMN production_checking_control.business_function; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON COLUMN public.production_checking_control.business_function IS 'TCO11-VORGANG / CO_VFVG. 1 is creation. 2 is release. No other value is stored.';


--
-- Name: COLUMN production_checking_control.no_check; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON COLUMN public.production_checking_control.no_check IS 'TCO11-PRUEFKZ. X means no automatic material availability check. Blank means the indicator is not set. Neither value runs a check.';


--
-- Name: COLUMN production_checking_control.checking_rule; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON COLUMN public.production_checking_control.checking_rule IS 'TCO11-PRREG. Optional. A named rule must stand. Null is not a default rule and is not a no-check.';


--
-- Name: COLUMN production_checking_control.check_on_save; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON COLUMN public.production_checking_control.check_on_save IS 'TCO11-ATPSAVEKZ. X means the check-on-save indicator is set. Blank means it is not set. Neither value runs a check.';


