    CONSTRAINT production_confirmation_note_ck CHECK (((note IS NULL) OR ((char_length(btrim((note)::text)) >= 1) AND (char_length(btrim((note)::text)) <= 200)))),
    CONSTRAINT production_confirmation_operation_ck CHECK (((operation_number)::text ~ '^[A-Z0-9]{4}$'::text)),
