    CONSTRAINT production_confirmation_operation_qty_ck CHECK (((yield_quantity >= (0)::numeric) AND (scrap_quantity >= (0)::numeric) AND (rework_quantity >= (0)::numeric))),
    CONSTRAINT production_confirmation_operation_type_ck CHECK (((confirmation_type)::text = ANY ((ARRAY['PARTIAL'::character varying, 'FINAL'::character varying])::text[])))
);

