--
-- Name: production_goods_movement_failure; Type: TABLE; Schema: public; Owner: cairn_integration_migrator
--

CREATE TABLE public.production_goods_movement_failure (
    id character varying(36) NOT NULL,
    client character varying(4) NOT NULL,
    source_transaction character varying(8) DEFAULT 'CO11N'::character varying NOT NULL,
    source_document_class character varying(48) DEFAULT 'production_confirmation'::character varying NOT NULL,
    source_document_number character varying(12) NOT NULL,
    confirmation_number character varying(12) NOT NULL,
    confirmation_request_key character varying(64) NOT NULL,
    order_number character varying(12) NOT NULL,
    operation_number character varying(4) NOT NULL,
    plant character varying(10) NOT NULL,
    movement_kind character varying(8) NOT NULL,
    movement_type character varying(20) NOT NULL,
    posting_date date NOT NULL,
    document_date date NOT NULL,
    header_text character varying(25) NOT NULL,
    original_request_key character varying(64) NOT NULL,
    idempotency_fingerprint character varying(64) NOT NULL,
    original_payload jsonb NOT NULL,
    status character varying(16) DEFAULT 'PENDING'::character varying NOT NULL,
    failure_code character varying(64),
    error_text text,
    attempt_count integer DEFAULT 0 NOT NULL,
    last_attempt_at timestamp with time zone,
    next_retry_at timestamp with time zone,
    processing_token character varying(36),
    processing_lease_expires_at timestamp with time zone,
    material_document_number character varying(20),
    document_year integer,
    created_by character varying(60) DEFAULT 'SYSTEM'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by character varying(60),
    changed_at timestamp with time zone,
    discarded_at timestamp with time zone,
    discarded_by character varying(60),
    disposition_reason character varying(200),
    CONSTRAINT production_gm_failure_attempt_count_ck CHECK (((attempt_count >= 0) AND (((status)::text <> 'PROCESSING'::text) OR (attempt_count > 0)))),
    CONSTRAINT production_gm_failure_disposition_ck CHECK (((((status)::text = 'DISCARDED'::text) AND (discarded_at IS NOT NULL) AND (discarded_by IS NOT NULL) AND ((char_length(btrim((disposition_reason)::text)) >= 1) AND (char_length(btrim((disposition_reason)::text)) <= 200))) OR (((status)::text <> 'DISCARDED'::text) AND (discarded_at IS NULL) AND (discarded_by IS NULL) AND (disposition_reason IS NULL)))),
    CONSTRAINT production_gm_failure_error_ck CHECK ((((status)::text <> ALL ((ARRAY['FAILED'::character varying, 'BLOCKED'::character varying])::text[])) OR ((failure_code IS NOT NULL) AND (error_text IS NOT NULL)))),
    CONSTRAINT production_gm_failure_fingerprint_ck CHECK (((idempotency_fingerprint)::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT production_gm_failure_lease_ck CHECK (((((status)::text = 'PROCESSING'::text) AND (processing_token IS NOT NULL) AND (processing_lease_expires_at IS NOT NULL)) OR (((status)::text <> 'PROCESSING'::text) AND (processing_token IS NULL) AND (processing_lease_expires_at IS NULL)))),
    CONSTRAINT production_gm_failure_movement_ck CHECK (((((movement_kind)::text = 'ISSUE'::text) AND ((movement_type)::text = 'PROD_ISSUE_ORDER'::text)) OR (((movement_kind)::text = 'RECEIPT'::text) AND ((movement_type)::text = 'PROD_RECEIPT_ORDER'::text)))),
    CONSTRAINT production_gm_failure_operation_ck CHECK (((operation_number)::text ~ '^[A-Z0-9]{4}$'::text)),
    CONSTRAINT production_gm_failure_payload_ck CHECK ((jsonb_typeof(original_payload) = 'object'::text)),
    CONSTRAINT production_gm_failure_posted_ck CHECK (((((status)::text = 'POSTED'::text) AND (material_document_number IS NOT NULL) AND (document_year IS NOT NULL)) OR (((status)::text <> 'POSTED'::text) AND (material_document_number IS NULL) AND (document_year IS NULL)))),
    CONSTRAINT production_gm_failure_source_ck CHECK ((((source_transaction)::text = 'CO11N'::text) AND ((source_document_class)::text = 'production_confirmation'::text))),
    CONSTRAINT production_gm_failure_source_key_ck CHECK (((source_document_number)::text = (confirmation_number)::text)),
    CONSTRAINT production_gm_failure_status_ck CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'PROCESSING'::character varying, 'FAILED'::character varying, 'BLOCKED'::character varying, 'POSTED'::character varying, 'DISCARDED'::character varying])::text[])))
);

