CREATE TABLE public.production_goods_movement_failure_attempt (
    id character varying(36) NOT NULL,
    client character varying(4) NOT NULL,
    failure_id character varying(36) NOT NULL,
    attempt_number integer NOT NULL,
    lease_token character varying(36) NOT NULL,
    attempted_by character varying(60) NOT NULL,
    status character varying(16) DEFAULT 'PROCESSING'::character varying NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    failure_code character varying(64),
    error_text text,
    material_document_number character varying(20),
    document_year integer,
    created_by character varying(60) DEFAULT 'SYSTEM'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by character varying(60),
    changed_at timestamp with time zone,
    payload_revision integer DEFAULT 0 NOT NULL,
    CONSTRAINT production_gm_failure_attempt_document_ck CHECK (((((status)::text = 'SUCCEEDED'::text) AND (material_document_number IS NOT NULL) AND (document_year IS NOT NULL)) OR (((status)::text <> 'SUCCEEDED'::text) AND (material_document_number IS NULL) AND (document_year IS NULL)))),
    CONSTRAINT production_gm_failure_attempt_error_ck CHECK ((((status)::text <> ALL ((ARRAY['FAILED'::character varying, 'BLOCKED'::character varying, 'ABANDONED'::character varying])::text[])) OR ((failure_code IS NOT NULL) AND (error_text IS NOT NULL)))),
    CONSTRAINT production_gm_failure_attempt_finish_ck CHECK (((((status)::text = 'PROCESSING'::text) AND (finished_at IS NULL)) OR (((status)::text <> 'PROCESSING'::text) AND (finished_at IS NOT NULL)))),
    CONSTRAINT production_gm_failure_attempt_number_ck CHECK ((attempt_number > 0)),
    CONSTRAINT production_gm_failure_attempt_revision_ck CHECK ((payload_revision >= 0)),
    CONSTRAINT production_gm_failure_attempt_status_ck CHECK (((status)::text = ANY ((ARRAY['PROCESSING'::character varying, 'FAILED'::character varying, 'BLOCKED'::character varying, 'SUCCEEDED'::character varying, 'ABANDONED'::character varying])::text[])))
);

