--

CREATE TABLE public.production_order (
    client character varying(4) NOT NULL,
    order_number character varying(12) NOT NULL,
    material_number character varying(40) NOT NULL,
    plant character varying(10) NOT NULL,
    order_quantity numeric(23,3) NOT NULL,
    unit_of_measure character varying(10) NOT NULL,
    scheduled_start character varying(10) NOT NULL,
    scheduled_finish character varying(10) NOT NULL,
    status character varying(32) DEFAULT 'CREATED'::character varying NOT NULL,
    request_key character varying(64),
    released_by character varying(64),
    released_at timestamp with time zone,
    created_by character varying(64) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by character varying(60),
    changed_at timestamp with time zone,
    batch_number character varying(40) DEFAULT ''::character varying NOT NULL,
    scheduling_profile character varying(6) DEFAULT ''::character varying NOT NULL,
    release_on_create character(1) DEFAULT ' '::bpchar NOT NULL,
    batch_creation character(1) DEFAULT ' '::bpchar NOT NULL,
    planned_order_number character varying(12),
    version integer DEFAULT 1 NOT NULL,
    technically_completed_by character varying(64),
    technically_completed_at timestamp with time zone,
    production_version character varying(4),
    bom_usage character(1),
    bom_alternative character varying(2),
    order_type character varying(4),
    controlling_area character varying(4),
    company_code character varying(4),
    currency character(3),
    CONSTRAINT production_order_batch_creation_ck CHECK ((batch_creation = ANY (ARRAY[' '::bpchar, '1'::bpchar, '2'::bpchar]))),
    CONSTRAINT production_order_bom_identity_ck CHECK ((((production_version IS NULL) AND (bom_usage IS NULL) AND (bom_alternative IS NULL)) OR ((production_version IS NOT NULL) AND (bom_usage IS NOT NULL) AND (bom_alternative IS NOT NULL) AND ((production_version)::text ~ '^[A-Z0-9]{1,4}$'::text) AND (bom_usage ~ '^[A-Z0-9]$'::text) AND ((bom_alternative)::text ~ '^[A-Z0-9]{1,2}$'::text)))),
    CONSTRAINT production_order_dates_ck CHECK (((scheduled_finish)::text >= (scheduled_start)::text)),
    CONSTRAINT production_order_quantity_ck CHECK ((order_quantity > (0)::numeric)),
    CONSTRAINT production_order_release_on_create_ck CHECK ((release_on_create = ANY (ARRAY['X'::bpchar, ' '::bpchar]))),
    CONSTRAINT production_order_status_ck CHECK (((status)::text = ANY ((ARRAY['CREATED'::character varying, 'RELEASED'::character varying, 'TECHNICALLY_COMPLETED'::character varying])::text[]))),
    CONSTRAINT production_order_technical_completion_ck CHECK (((((status)::text = 'TECHNICALLY_COMPLETED'::text) AND (technically_completed_by IS NOT NULL) AND (technically_completed_at IS NOT NULL)) OR (((status)::text <> 'TECHNICALLY_COMPLETED'::text) AND (technically_completed_by IS NULL) AND (technically_completed_at IS NULL)))),
    CONSTRAINT production_order_type_ck CHECK (((order_type IS NULL) OR ((order_type)::text ~ '^[A-Z0-9]{4}$'::text))),
    CONSTRAINT production_order_version_ck CHECK ((version > 0))
);

