--
-- Name: COLUMN production_order.order_type; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON COLUMN public.production_order.order_type IS 'Production order type. Null means not assigned. It is not filled from a scheduling profile, a material, or the first standing type.';


--
-- Name: production_order_actual_posting_v; Type: VIEW; Schema: public; Owner: cairn_integration_migrator
--

CREATE VIEW public.production_order_actual_posting_v WITH (security_invoker='true') AS
 SELECT l.client,
    l.production_order AS order_number,
    j.company_code,
    j.document_number,
    j.display_number,
    j.fiscal_year,
    j.document_type,
    j.document_date,
    j.posting_date,
    j.posting_period,
    j.document_currency,
    j.local_currency,
    j.status AS document_status,
    j.reversal_of,
    j.reversed_by,
    j.origin_class,
    j.origin_key,
    l.line_number,
    l.gl_account,
    l.debit_credit,
    l.amount_document,
    l.amount_local,
    l.currency AS line_currency,
    l.material,
    l.plant,
    l.line_text
   FROM (public.journal_entry_line l
     JOIN public.journal_entry j ON ((((j.client)::text = (l.client)::text) AND ((j.document_number)::text = (l.document_number)::text) AND (j.fiscal_year = l.fiscal_year))))
  WHERE ((l.production_order IS NOT NULL) AND ((j.status)::text = ANY ((ARRAY['POSTED'::character varying, 'REVERSED'::character varying])::text[])));


ALTER VIEW public.production_order_actual_posting_v OWNER TO cairn_integration_migrator;

--
-- Name: VIEW production_order_actual_posting_v; Type: COMMENT; Schema: public; Owner: cairn_integration_migrator
--

COMMENT ON VIEW public.production_order_actual_posting_v IS 'Read-only ledger lines assigned to production orders. Amounts are journal actuals, not activity-rate estimates; read through a security-invoker view so base-table tenant RLS applies.';


