    CONSTRAINT production_order_component_commitment_event_quantity_ck CHECK (((((event_kind)::text = 'COMMITTED'::text) AND (committed_quantity > (0)::numeric) AND (requirement_date IS NOT NULL)) OR (((event_kind)::text = ANY ((ARRAY['RELEASED'::character varying, 'RESET'::character varying])::text[])) AND (committed_quantity = (0)::numeric)))),
    CONSTRAINT production_order_component_commitment_event_reason_ck CHECK (((reason IS NULL) OR ((char_length(btrim((reason)::text)) >= 1) AND (char_length(btrim((reason)::text)) <= 200)))),
    CONSTRAINT production_order_component_commitment_event_reset_reason_ck CHECK ((((event_kind)::text <> 'RESET'::text) OR ((char_length(btrim((reason)::text)) >= 1) AND (char_length(btrim((reason)::text)) <= 200)))),
