    created_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by character varying(60),
    changed_at timestamp with time zone,
    CONSTRAINT sales_order_schedule_confirmed_ck CHECK (((confirmed_quantity >= (0)::numeric) AND (confirmed_quantity <= requested_quantity))),
    CONSTRAINT sales_order_schedule_number_ck CHECK ((schedule_number > 0)),
    CONSTRAINT sales_order_schedule_quantity_ck CHECK ((requested_quantity > (0)::numeric))
);


