    CONSTRAINT settlement_distribution_rule_share_ck CHECK ((num_nonnulls(percentage, equivalence, amount) = 1)),
    CONSTRAINT settlement_distribution_rule_type_ck CHECK (((settlement_type)::text = ANY ((ARRAY['PER'::character varying, 'FUL'::character varying])::text[])))
);

