INSERT INTO public.capability VALUES ('PROC.RFQ.CREATE', 'PROC', 'Create or change a request for quotation. The capability does not grant the purchase order, and it does not post a goods movement or a journal', 'CREATE', false, '2026-11-10 08:54:14.023148+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.RFQ.QUOTATION', 'PROC', 'Maintain a supplier quotation against one standing request. The capability does not grant the purchase order, and it does not compare, award, or post a goods movement or a journal', 'CREATE', false, '2026-11-10 08:54:14.024328+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.RFQ.QUOTATION.DISPLAY', 'PROC', 'Display a standing supplier quotation. The capability does not grant maintenance, the purchase order, a comparison, or an award, and it posts no goods movement and no journal', 'DISPLAY', false, '2026-11-10 08:54:14.025222+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.RFQ.COMPARISON', 'PROC', 'Compare the quotations that stand for one event. The event number is the key. A collective number is a label. The compared price is the net price per one unit of the unit that was asked, calculated and not stored. The capability does not grant maintenance, the purchase order, or an award, and it posts no goods movement and no journal', 'DISPLAY', false, '2026-11-10 08:54:14.026207+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.PO.RELEASE', 'PROC', 'Release a purchase order', 'APPROVE', false, '2026-11-10 08:54:14.027421+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROD.MRP.STOCKREQ', 'PROD', 'Display the stock/requirements list for one material and plant: stock on hand, open purchase requisitions and open purchase orders in one chronological list with a running projected balance, safety stock as the opening requirement, and shortage, safety-breach and past-due exceptions', 'DISPLAY', false, '2026-11-10 08:54:14.028568+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROD.PLANNEDORDER.CHANGE', 'PROD', 'Change a planned order. MD12 is a search alias. The number, material, and plant stay fixed. A change of quantity or dates firms the order. Change does not convert the order and posts nothing', 'CHANGE', false, '2026-11-10 08:54:11.761147+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROD.MRP.REGENERATE', 'PROD', 'Confirm a regenerative planning run. The capability does not grant a net-change run, and it posts no goods movement and no journal', 'CREATE', false, '2026-11-10 08:54:14.036988+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.PO.ACCOUNTASSIGN', 'PROC', 'Display purchase orders by account assignment: every assignment line with its cost centre, G/L account and share of the item net value, grouped by assigned object, with the delivered and invoiced scope of selection and drills to the order and the cost centre', 'DISPLAY', false, '2026-11-10 08:54:14.037953+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.PO.LIST', 'PROC', 'Display purchase orders as a list from four perspectives (vendor, material, purchase order, material group): ranges on vendor, organisation, group, plant, material, material group and document number with document dates, and a scope of selection derived from posted goods receipts and supplier invoices', 'DISPLAY', false, '2026-11-10 08:54:14.039215+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.PR.RELEASE', 'PROC', 'Release a purchase requisition', 'APPROVE', false, '2026-11-10 08:54:14.040414+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.INV.RECORD', 'PROC', 'Record a supplier invoice', 'CREATE', true, '2026-11-10 08:54:14.04153+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.INV.PARK', 'PROC', 'Park a supplier invoice without posting a journal or consuming the purchase order or the goods receipt', 'CREATE', false, '2026-11-10 08:54:14.042465+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.INV.OVERVIEW', 'PROC', 'List logistics invoices that stand, parked and posted, without posting, releasing, clearing, or exporting', 'DISPLAY', false, '2026-11-10 08:54:14.043561+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.INV.BLOCK', 'PROC', 'Place a manual payment hold on a posted unpaid supplier invoice without posting a journal', 'CREATE', false, '2026-11-10 08:54:14.044757+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.INV.BLOCK.RELEASE', 'PROC', 'Release a manual payment hold on a posted unpaid supplier invoice without posting, clearing, or changing the invoice amount', 'CHANGE', false, '2026-11-10 08:54:14.045911+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.GRIR.MAINTAIN', 'PROC', 'List a GR/IR residual on a purchase-order item and check it without posting', 'DISPLAY', false, '2026-11-10 08:54:14.046954+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.GRIR.MAINTAIN.POST', 'PROC', 'Clear a posted GR/IR residual with one balanced journal, without a material movement and without changing stock', 'POST', true, '2026-11-10 08:54:14.047875+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.GRIR.MAINTAIN.REVERSE', 'PROC', 'Reverse a GR/IR clearing by a compensating journal. The original document is not deleted', 'REVERSE', true, '2026-11-10 08:54:14.048961+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROC.GRIR.RECONCILE', 'PROC', 'List the GR/IR balances that no longer explain themselves, without clearing, adjusting, reversing or reclassifying any of them', 'DISPLAY', false, '2026-11-10 08:54:14.049814+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.TRANSFER.POST', 'INV', 'Post a stock transfer between storage locations and plants', 'POST', true, '2026-11-10 08:54:14.050724+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.REVERSE', 'INV', 'Reverse a material document, in whole or by line', 'REVERSE', true, '2026-11-10 08:54:14.051702+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.RESERVATION.CREATE', 'INV', 'Create a reservation: a planned withdrawal of a material from a plant on a required date, charged to the cost centre its movement type names', 'CREATE', false, '2026-11-10 08:54:14.052703+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.GR.POST', 'INV', 'Post a goods receipt', 'POST', true, '2026-11-10 08:54:14.053715+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.MATERIALDOC.RECEIVEPRINT', 'INV', 'Determine and dispatch the output slips of material documents: a goods receipt slip for a document that receipts, a goods issue slip for one that issues, with the queue, its statuses, its send counts and its failures', 'OUTPUT', false, '2026-11-10 08:54:14.055778+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.DISPLAY', 'INV', 'Display one material document as the ledger recorded it: header with poster and entry time, every line with its movement, material, batch, quantities, value and references, and the company code derived from its plants', 'DISPLAY', false, '2026-11-10 08:54:14.056821+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.MATERIALDOC.LIST', 'INV', 'Display material documents as a list: ranges on material, plant, storage location, movement type and purchase order with a required posting-date range, judging the canon movement type and showing every line including reversed documents', 'DISPLAY', false, '2026-11-10 08:54:14.057807+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.RETURN.POST', 'INV', 'Post a return delivery of goods received against a purchase order: the returnable quantity is derived from posted returns net of their reversals, the movement is read from configuration, stock is judged on the exact dimension under lock, the receipt keeps standing while the received position falls, and GR/IR is reopened without touching a vendor liability', 'POST', true, '2026-11-10 08:54:11.241943+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.STOCK.POSTINGDATE', 'INV', 'Display stocks on posting date: opening, receipts, issues and closing quantity and value per material, plant, storage location and stock type across a required reporting window, read from the immutable ledger with the stock master as a control', 'DISPLAY', false, '2026-11-10 08:54:14.061108+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.STOCK.WAREHOUSE', 'INV', 'Display warehouse stocks on hand: the current stock master by material, plant and storage location pivoted into unrestricted, quality inspection, blocked and special stock with the plant valuation price and the total inventory value, read-only', 'DISPLAY', false, '2026-11-10 08:54:14.062294+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.GI.POST', 'INV', 'Post a goods issue', 'POST', true, '2026-11-10 08:54:14.054615+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.STOCK.VIEW', 'INV', 'Display the stock overview for one material as a three-level tree: plant, storage location and stock type, with every parent total folded from the children it shows, zero nodes suppressed unless asked for, and each node drilling into the material documents, the posting-date rollforward and the warehouse stock list. A named batch is shown under the stock type and does not create a batch', 'DISPLAY', false, '2026-11-10 08:54:14.064569+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROD.MRP.RUN', 'PROD', 'Run material requirements planning', 'CREATE', false, '2026-11-10 08:54:14.029728+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROD.ORDER.CREATE', 'PROD', 'Create a production order. CO01 is a search alias. The screen selects a production version and stores a component snapshot from that bill of material. A typed component list or BOM alternative is not accepted on this screen. A caller that already resolved a snapshot, including planned-order conversion, may still pass that snapshot. Creating an order posts nothing and moves no stock. Release stays a separate capability.', 'CREATE', false, '2026-11-10 08:54:14.078037+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROD.ORDER.AVAILABILITY.COMMIT', 'PROD', 'Commit fully covered production-order component requirements through CO09. Each component is all-or-nothing; this writes no goods movement, journal, reservation, or order status. Exact grant only.', 'EXECUTE', false, '2026-11-10 08:54:12.047142+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROD.ORDER.RELEASE', 'PROD', 'Release a production order', 'RELEASE', false, '2026-11-10 08:54:14.083666+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROD.ORDER.GI', 'PROD', 'Issue components to a production order', 'POST', true, '2026-11-10 08:54:14.08469+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.MIGO.POST', 'INV', 'Post a goods movement from the action/reference matrix', 'POST', true, '2026-11-10 08:54:14.085781+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('PROD.ORDER.GR', 'PROD', 'Receive finished goods from a production order', 'POST', true, '2026-11-10 08:54:14.087019+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.PHYINV.CREATE', 'INV', 'Create a physical inventory document: name the plant, storage location, planned count date and the materials to be counted, with an optional posting block that refuses stock movements for those materials until the count is done', 'CREATE', false, '2026-11-10 08:54:14.089506+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.PHYINV.CANCEL', 'INV', 'Cancel a physical inventory document before anything is counted, releasing any posting block it holds', 'CANCEL', false, '2026-11-10 08:54:14.090515+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.PHYINV.COUNT', 'INV', 'Enter physical inventory counts against a document created by MI01: a positive quantity, an explicit zero, or a correction, with the provisional difference calculated against the book quantity the document was created with. A count posts nothing', 'COUNT', false, '2026-11-10 08:54:14.091669+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.PHYINV.COUNT.CORRECT', 'INV', 'Clear a physical inventory count back to uncounted, with a reason kept in the history, while the differences have not been posted', 'CORRECT', false, '2026-11-10 08:54:14.09266+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.PHYINV.DIFF.LIST', 'INV', 'Display physical inventory differences: counted quantity against the book quantity frozen on the document, shortage and surplus named, and a monetary difference only where a plant valuation record stands. The list posts nothing and changes no count', 'DISPLAY', false, '2026-11-10 08:54:14.09362+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.PHYINV.DIFF.POST', 'INV', 'Post physical inventory differences: the whole remaining difference of each selected item, through the material document and, when the movement values, one journal. The amount is the plant valuation. The capability does not grant counting, listing, or reversal', 'POST', true, '2026-11-10 08:54:14.094559+00') on conflict do nothing;
INSERT INTO public.capability VALUES ('INV.PHYINV.RECOUNT', 'INV', 'Create a recount document for selected counted items. The original count stays and is not added to the recount. The capability does not grant count entry, difference review, difference posting, ordinary cancellation, or reversal', 'CREATE', false, '2026-11-10 08:54:14.095824+00') on conflict do nothing;
