INSERT INTO public.term_registry VALUES ('74772d6f-0def-4c0d-896f-35df323bfd7b', 'PROC.CONTRACT.LIST', NULL, 'Outline agreements', 'TRANSACTION', 'PROC', 'List contracts with target, called-off, and remaining quantity or value. ME3N is a search alias. The list does not post.', 'TIER_1_BUILT', '/purchasing/contracts', 'B', NULL, true, 'MIGRATION_9147', '2026-11-10 08:54:11.576686+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('6ca3d12f-8fb4-4260-9959-a384de12cd83', 'PROC.SCHEDAGREE.MAINTAIN', 'scheduling_agreement', 'Scheduling agreement', 'TRANSACTION', 'PROC', 'Create or change a scheduling agreement. ME31L and ME32L are search aliases. Saving does not create a delivery schedule, a purchase order, a goods receipt, or accounting.', 'TIER_1_BUILT', '/purchasing/scheduling-agreements', 'B', NULL, true, 'MIGRATION_9150', '2026-11-10 08:54:11.597282+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('9b17326e-b3c1-4d4d-8cdd-d8fad80f8106', 'PROC.SCHEDAGREE.DISPLAY', NULL, 'Display scheduling agreement', 'TRANSACTION', 'PROC', 'Display a scheduling agreement. ME33L is a search alias. Display writes nothing.', 'TIER_1_BUILT', '/purchasing/scheduling-agreement-display', 'B', NULL, true, 'MIGRATION_9150', '2026-11-10 08:54:11.597282+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('19e2b183-1617-41a3-82ab-1ad6de500500', 'PROC.SCHEDAGREE.RELEASE', NULL, 'Release scheduling agreement', 'TRANSACTION', 'PROC', 'Release a scheduling agreement when a strategy claims it. ME35L is a search alias. No strategy means no release is required.', 'TIER_1_BUILT', '/purchasing/scheduling-agreements', 'B', NULL, true, 'MIGRATION_9150', '2026-11-10 08:54:11.597282+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('6513cd1d-6ac6-4b13-8cd9-869b16249e2a', 'PROC.SCHEDAGREE.LIST', NULL, 'Scheduling agreements', 'TRANSACTION', 'PROC', 'List scheduling agreements. ME3L is a search alias. The list does not post.', 'TIER_1_BUILT', '/purchasing/scheduling-agreements', 'B', NULL, true, 'MIGRATION_9150', '2026-11-10 08:54:11.597282+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('f4dffd32-ce3e-4714-b8a2-dddc6c618b27', 'PROC.SCHEDLINE.MAINTAIN', 'scheduling_agreement_schedule_line', 'Delivery schedule', 'TRANSACTION', 'PROC', 'Maintain delivery schedule lines for a scheduling agreement. ME38 is a search alias. Saving does not create an agreement, a purchase order, a goods receipt, or a supplier release.', 'TIER_1_BUILT', '/purchasing/delivery-schedule', 'B', NULL, true, 'MIGRATION_9151', '2026-11-10 08:54:11.610223+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('bc70b847-3004-407b-9bcf-45bd119fb2b3', 'PROC.SCHEDLINE.DISPLAY', NULL, 'Display delivery schedule', 'TRANSACTION', 'PROC', 'Display delivery schedule lines. ME39 is a search alias. Display writes nothing.', 'TIER_1_BUILT', '/purchasing/delivery-schedule-display', 'B', NULL, true, 'MIGRATION_9151', '2026-11-10 08:54:11.610223+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('c1f17a88-cf6a-40fe-9e14-b4b8630611a4', 'CO.ORDER.MAINTAIN', 'internal_order', 'Internal order', 'TRANSACTION', 'CO', 'Create or change an internal order. KO01 and KO02 are search aliases. Saving does not post, budget, or settle.', 'TIER_1_BUILT', '/controlling/internal-orders', 'B', NULL, true, 'MIGRATION_9152', '2026-11-10 08:54:11.612938+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('0790bcec-8d30-4d50-9c22-97cfb4133255', 'INV.STOCK.RECONCILE', NULL, 'Stock reconciliation', 'TRANSACTION', 'INV', 'Compare the stock projection with the material document ledger: the ledger is the documents themselves, each line naming its document with the direction as its sign, so the sum per material, plant, storage location and stock type is the balance the documents justify. Only the dimensions that disagree are listed, with ledger quantity, projected quantity and the difference, and a projection row with no documents behind it stands as drift of its full quantity. A drifted dimension can be rebuilt from the ledger, which posts, values and journals nothing and deletes a dimension the ledger no longer knows; the rebuild refuses while a physical inventory count holds the dimension open, because that count is about to compare against the same number.', 'TIER_1_BUILT', '/inventory/stock-reconcile', 'B', NULL, true, 'SCR144_MIGRATION', '2026-11-10 08:54:11.231999+00', 'SEED', '2026-11-10 08:54:14.397813+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('796a4abc-774d-4855-b754-77c176711bdf', 'CFG.FIN.GLACCOUNT.CREATE', NULL, 'G/L account master create', 'CONFIG_ACTIVITY', 'FIN', 'Create a G/L account in an active, unblocked chart of accounts. The account number is validated against the chart length and the account group range, stays immutable for the life of the account, and every other field takes its status from the account group field status matrix.', 'TIER_2_CONFIGURED', '/config/gl-accounts/new', 'B', NULL, true, 'SCR028_MIGRATION', '2026-11-10 08:54:10.447949+00', 'SEED', '2026-11-10 08:54:14.547022+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('f46fbeb5-efa6-4149-a8d7-52b4ae68dd8d', 'CFG.FIN.GLACCOUNT.CHANGE', NULL, 'G/L account master change', 'CONFIG_ACTIVITY', 'FIN', 'Change a G/L account, its posting and creation blocks, the account group registry with its from/to ranges, and the per-field Suppress/Optional/Mandatory matrix. A reason is mandatory for a block change and for deletion, and deletion is refused while any balance, line item, open item or reconciliation assignment still uses the account.', 'TIER_2_CONFIGURED', '/config/gl-accounts/edit', 'B', NULL, true, 'SCR028_MIGRATION', '2026-11-10 08:54:10.447949+00', 'SEED', '2026-11-10 08:54:14.548906+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('fecc6b0b-59a3-4b8e-8958-56f5dfa48dd8', 'CFG.FIN.GLACCOUNT.DISPLAY', NULL, 'G/L account master display', 'CONFIG_ACTIVITY', 'FIN', 'Read G/L account master records, the account group registry and their change history. A blocked chart of accounts keeps its read-only display while refusing new accounts. Display mode itself is /config/gl-accounts/view; this hub route is the entry point that needs no selection.', 'TIER_2_CONFIGURED', '/config/gl-accounts', 'B', NULL, true, 'SCR028_MIGRATION', '2026-11-10 08:54:10.447949+00', 'SEED', '2026-11-10 08:54:14.550436+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('f7722805-3526-4796-ad72-e35b3d17c5f3', 'CFG.PROC.PURORG.ASSIGN_PLANT', NULL, 'Assign purchasing organisation to plant', 'CONFIG_ACTIVITY', 'PROC', 'Assign an active purchasing organisation to an active plant. The company code is read from the plant and is not stored on the assignment. One organisation may buy for several plants of its company, and a plant may be served by several organisations. A pair a procurement document already cites is not removed, and the document is not rewritten. OX17 is a search alias only.', 'TIER_2_CONFIGURED', '/config/purchasing-orgs/assign-plant', 'B', NULL, true, 'MIGRATION_9104', '2026-11-10 08:54:11.382391+00', 'SEED', '2026-11-10 08:54:14.680154+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('17760c2c-e9c6-44ff-9173-13ffca29b70b', 'PLT.LOCK.DISPLAY', NULL, 'Lock monitor', 'TRANSACTION', 'PLT', 'The dialog enqueue. One session holds a document or a configuration row in change. Every other session may open it and cannot change it.', 'TIER_1_BUILT', '/platform/locks', 'B', NULL, true, 'MIGRATION_9105', '2026-11-10 08:54:11.386216+00', 'SEED', '2026-11-10 08:54:14.684713+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('91080000-0000-4000-8000-000000000001', 'CFG.ORG.PLANT.ASSIGN_COMPANY', NULL, 'Assign plant to company code', 'CONFIG_ACTIVITY', 'FND', 'Assign an unassigned plant to a company code. The assignment is maintained on the plant screen, not on a second page.', 'TIER_2_CONFIGURED', '/config/plants', 'B', NULL, true, 'MIGRATION_9108', '2026-11-10 08:54:11.400895+00', 'SEED', '2026-11-10 08:54:14.655591+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('85c69615-5f5a-49f7-9318-b16e0c93928c', 'CO.ORDER.DISPLAY', NULL, 'Display internal order', 'TRANSACTION', 'CO', 'Display an internal order. KO03 is a search alias. Display writes nothing.', 'TIER_1_BUILT', '/controlling/internal-order-display', 'B', NULL, true, 'MIGRATION_9152', '2026-11-10 08:54:11.612938+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('91080000-0000-4000-8000-000000000003', 'CFG.COST.CONTROLLINGAREA.DEFINE', NULL, 'Define controlling area', 'CONFIG_ACTIVITY', 'COST', 'Define a controlling area. Company-code assignment is the separate screen. OKKP is a search alias only.', 'TIER_2_CONFIGURED', '/config/controlling-area', 'B', NULL, true, 'MIGRATION_9108', '2026-11-10 08:54:11.400895+00', 'SEED', '2026-11-10 08:54:14.584555+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('91080000-0000-4000-8000-000000000004', 'CFG.COST.CONTROLLINGAREA.ASSIGN_COMPANY', NULL, 'Assign controlling area to company code', 'CONFIG_ACTIVITY', 'COST', 'Assign a company code to a controlling area. OX19 is a search alias only. The assignment is not part of the area definition screen.', 'TIER_2_CONFIGURED', '/config/controlling-area/assign-company-code', 'B', NULL, true, 'MIGRATION_9108', '2026-11-10 08:54:11.400895+00', 'SEED', '2026-11-10 08:54:14.586012+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('91080000-0000-4000-8000-000000000002', 'CFG.PROC.PURGROUP.DEFINE', NULL, 'Define purchasing groups', 'CONFIG_ACTIVITY', 'PROC', 'Define purchasing groups: a three-character key and the buyer contact. A group is not assigned to a purchasing organisation, a company code or a plant.', 'TIER_2_CONFIGURED', '/config/purchasing-groups', 'B', NULL, true, 'MIGRATION_9108', '2026-11-10 08:54:11.400895+00', 'SEED', '2026-11-10 08:54:14.677794+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('91080000-0000-4000-8000-000000000005', 'CFG.FIN.CREDIT.DEFINE', NULL, 'Customer credit management', 'CONFIG_ACTIVITY', 'FIN', 'Maintain customer credit for a credit control area. The area itself is delivered with the standard structure; this screen does not create one. FD32 remains the transaction alias on the same screen.', 'TIER_1_BUILT', '/finance/credit', 'B', NULL, true, 'MIGRATION_9108', '2026-11-10 08:54:11.400895+00', 'SEED', '2026-11-10 08:54:14.748336+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('ecd605a8-8401-47a0-a650-a99655ca1928', 'CFG.INV.BATCHLEVEL.DEFINE', NULL, 'Define batch level', 'CONFIG_ACTIVITY', 'INV', 'Define the batch level for the client. OMCE is a search alias only. One row stands per client. The stored code is the character 0, 1, or 2, never a number and never a label: 0 is unique for a material in a plant, 1 is unique for a material in the client, and 2 is unique once in the client. The description is derived. An initial level is saved only when no batch stands. A later change sends the opened version. If a batch stands, the row is not edited and a conversion is not presented as a save. Live conversion is refused by name. Stock and material documents carry a batch and are not rewritten. Setting the level does not activate batch status, internal numbering, classification, or a batch requirement on a movement. A closed posting period does not block this screen. A transport, an approval, and a company code are refused by name. The change document is the history. The lock is the configuration row.', 'TIER_2_CONFIGURED', '/config/batch-level', 'B', NULL, true, 'MIGRATION_9110', '2026-11-10 08:54:11.4129+00', 'SEED', '2026-11-10 08:54:14.789269+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('189b9bca-025b-4c59-a81c-a2e96b527e28', 'CFG.INV.BATCHSTATUS.DEFINE', NULL, 'Activate batch status management', 'CONFIG_ACTIVITY', 'INV', 'Activate batch status management for the client. OMCS is a search alias only. The stored code is the character 1 when active, and blank when not active. It is not a batch level and not a plant list. The batch level is read from OMCE. At material or client level, an active indicator applies in every plant. At plant level it applies in a plant only after OMCU selects that plant; this screen does not select a plant. A batch that already stands blocks a change, because the conversion and movements 341 and 342 are not available. Setting the indicator does not create a batch, set an initial status, classify a batch, or make a movement require a batch. A closed posting period does not block this screen. A transport, an approval, and a company code are refused by name. The change document is the history. The lock is the configuration row.', 'TIER_2_CONFIGURED', '/config/batch-status', 'B', NULL, true, 'MIGRATION_9111', '2026-11-10 08:54:11.423743+00', 'SEED', '2026-11-10 08:54:14.791205+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('73a55082-5400-4462-8883-e71879c96b91', 'INV.BATCH.CREATE', 'batch', 'Create batch', 'TRANSACTION', 'INV', 'Create a batch master. MSC1N is a search alias only. The material must exist and be batch-managed. The batch level is read from OMCE. A plant is part of the identity only at plant level. A typed batch number is kept and does not consume interval 01. It is judged against external interval 02 only when that interval stands. A blank number draws BATCH_CLT interval 01 only when OMCZ is active. OMAD maintains the interval and is not this screen, and activating OMCZ does not create the interval. The status indicator is X for restricted and blank for unrestricted, and only when OMCS is effective. At plant level it is effective only in a plant OMCU has selected. It is not stored as 1 or 2. A batch does not create stock. MSC2N and MSC3N are not this screen.', 'TIER_1_BUILT', '/inventory/batches/new', 'B', NULL, true, 'MIGRATION_9112', '2026-11-10 08:54:11.428432+00', 'SEED', '2026-11-10 08:54:14.816411+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('50990619-77f0-48f7-b461-1c4a854805ae', 'INV.BATCH.CHANGE', NULL, 'Change batch', 'TRANSACTION', 'INV', 'Change a batch master. MSC2N is a search alias only. The batch must already stand. The batch level is read from OMCE. A plant is part of the identity only at plant level. The material, plant, and batch number cannot be changed, and the number is not regenerated. Dates, the vendor batch, and the country of origin can be changed. The restricted-use indicator is X or blank, and only when OMCS is effective. It is not 1 or 2. Changing it does not post movements 341 or 342. Those movements are not posted on this screen. A batch is not deleted here. MSC1N and MSC3N are not this screen.', 'TIER_1_BUILT', '/inventory/batches/change', 'B', NULL, true, 'MIGRATION_9113', '2026-11-10 08:54:11.433685+00', 'SEED', '2026-11-10 08:54:14.828271+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('37a620a5-5925-457e-88e8-8fe4c1f091e2', 'CFG.INV.BATCHRANGE.DEFINE', NULL, 'Number ranges for batch numbers', 'CONFIG_ACTIVITY', 'INV', 'Number ranges for batch numbers. OMAD is a search alias only. The object is BATCH_CLT, client level, not a plant and not a material type. Interval 01 is internal. Interval 02, when it stands and is external, checks a typed number and does not allocate. Opening this screen does not create an interval, a batch, or a stock receipt. From, to, and the current number are shown with leading zeros. The current number is the last issued number. The next number is not reserved by being shown. It is not moved backwards. A number is not reissued. Exhaustion does not wrap. Gaps are acceptable. Buffering is refused. Delete is allowed only when nothing has been issued and no standing batch falls in the interval. A closed posting period does not block this screen. A transport, a company code, and a fiscal year are refused by name. The change document is the history. The lock is the interval.', 'TIER_2_CONFIGURED', '/config/batch-number-ranges', 'B', NULL, true, 'MIGRATION_9125', '2026-11-10 08:54:11.469582+00', 'SEED', '2026-11-10 08:54:14.814547+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('01ee143f-9eae-47ab-8c5d-22c4f73fff0b', 'CFG.INV.BATCHIMG.DISPLAY', NULL, 'Batch management index', 'TRANSACTION', 'INV', 'OCHA is a search alias only. It opens the batch management configuration index. It does not define a characteristic, assign a class, or store a batch value. It does not create a batch, post a movement, or select a plant. Opening this screen writes nothing.', 'TIER_1_BUILT', '/config/batch-management', 'B', NULL, true, 'MIGRATION_9127', '2026-11-10 08:54:11.479802+00', 'SEED', '2026-11-10 08:54:14.78542+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('beabacab-5832-4ad6-9efb-c636ec7e7293', 'INV.BATCH.DISPLAY', NULL, 'Display batch', 'TRANSACTION', 'INV', 'Display a batch master. MSC3N is a search alias only. The batch must already stand. The batch level is read from OMCE. A plant is part of the identity only at plant level. The screen reads the same row MSC1N creates. The restricted-use indicator is X or blank, and only when it was stored. It is not 1 or 2. The date of manufacture is HSDAT, not HERDT. The vendor batch is separate from the batch number. Deletion, classification, and inspection lots are not stored. This screen does not show stock. The pick-up list is MB5C. Display writes nothing.', 'TIER_1_BUILT', '/inventory/batches/display', 'B', NULL, true, 'MIGRATION_9114', '2026-11-10 08:54:11.436682+00', 'SEED', '2026-11-10 08:54:14.830314+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('451af823-39b5-4897-8a5c-189d7c2f94e3', 'PROC.CONTRACT.MAINTAIN', 'purchase_contract', 'Purchase contract', 'TRANSACTION', 'PROC', 'Create or change a quantity or value contract. ME31K and ME32K are search aliases. Saving does not post stock, a goods receipt, or accounting.', 'TIER_1_BUILT', '/purchasing/contracts', 'B', NULL, true, 'MIGRATION_9147', '2026-11-10 08:54:11.576686+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('22114b0a-a210-421f-b629-855a78df153e', 'CFG.INV.BATCHSTATUSPLANT.DEFINE', NULL, 'Batch status management in plant', 'CONFIG_ACTIVITY', 'INV', 'Batch status management in plant. OMCU is a search alias only. The stored code is T001W-CHAZV, character X when selected and blank when not selected. It is not the OMCS character 1 and not a boolean. The plant name is read from the plant master and is not stored here. The selection applies only when the batch level is plant. At material or client level it is refused, and OMCS is not changed. Opening this screen does not select a plant. A change is refused when a batch, batched stock, or a material document already stands in the plant, because movements 341 and 342 are not available. Stock is not rewritten. Restricted use is not blocked stock and not inspection stock. A closed posting period does not block this screen. A transport, a company code, an initial status, and a plant name are refused by name. The change document is the history. The lock is the plant.', 'TIER_2_CONFIGURED', '/config/batch-status-plants', 'B', NULL, true, 'MIGRATION_9126', '2026-11-10 08:54:11.472658+00', 'SEED', '2026-11-10 08:54:14.810761+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('db1bba05-5e4f-44db-8769-34f68f19f8ce', 'CFG.INV.BATCHNUMBER.DEFINE', NULL, 'Activate internal batch number assignment', 'CONFIG_ACTIVITY', 'INV', 'Activate internal batch number assignment. OMCZ is a search alias only. The client flag is X when active and blank when not active. It is not a plant and not a material type. A separate plant flag permits an internal number only for an account-assigned goods receipt. That receipt is not posted here. The number range is BATCH_CLT interval 01, maintained in OMAD. This screen does not create the interval, a batch, or a stock receipt. A closed posting period does not block this screen. A transport is refused by name. The change document is the history. The lock is the configuration row.', 'TIER_2_CONFIGURED', '/config/batch-number-assignment', 'B', NULL, true, 'MIGRATION_9123', '2026-11-10 08:54:11.459385+00', 'SEED', '2026-11-10 08:54:14.812642+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('c20af140-0bf3-422a-b12a-52388e6d763f', 'INV.BATCH.PICKUP', NULL, 'Pick-up list for batch where-used', 'TRANSACTION', 'INV', 'Pick-up list for batches that already stand and already appear on a material document. MB5C is a search alias only. Naming a batch lists those document lines. A batch that has never been posted is not listed. A blank batch is not listed. The list does not create a batch and does not post. A sales order, a delivery, a billing document, and a scheduling agreement are refused by name, because those documents are not on the material document.', 'TIER_1_BUILT', '/inventory/batch-pickup', 'B', NULL, true, 'MIGRATION_9119', '2026-11-10 08:54:11.450407+00', 'SEED', '2026-11-10 08:54:14.832416+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('2c121010-9172-4445-87d0-3577d67c04a6', 'PROC.CONTRACT.DISPLAY', NULL, 'Display purchase contract', 'TRANSACTION', 'PROC', 'Display a purchase contract. This route writes nothing.', 'TIER_1_BUILT', '/purchasing/contract-display', 'B', NULL, true, 'MIGRATION_9147', '2026-11-10 08:54:11.576686+00', 'MIGRATION_9149', '2026-11-10 08:54:11.59519+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('c612de9b-bd74-457b-8eab-2394f84c69eb', 'CFG.PROD.SCHEDPROFILE.DEFINE', NULL, 'Production scheduling profile', 'CONFIG_ACTIVITY', 'PROD', 'Production scheduling profile. OPKP is a search alias only. The key is the plant and a profile of at most six characters, stored as typed. Release at creation is the character X or blank. Batch creation in the order is blank, 1, or 2. A material plant assignment is stored on the plant view. An existing order keeps the profile it was created with. This screen does not print, schedule, check availability, check capacity, post a goods receipt, classify a batch, or create an order type. T399X is not this profile. Opening this screen writes nothing.', 'TIER_2_CONFIGURED', '/config/scheduling-profiles', 'B', NULL, true, 'MIGRATION_9130', '2026-11-10 08:54:11.486659+00', 'SEED', '2026-11-10 08:54:14.429207+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('26185730-7aa3-4f45-9610-92f82ffd369d', 'CFG.INV.BATCHINITIAL.DEFINE', NULL, 'Initial status of a new batch', 'CONFIG_ACTIVITY', 'INV', 'Initial status of a new batch. OMAB is a search alias only. The flag is the material type, not a plant. Checked is stored as restricted for a new batch. Blank is unrestricted. An existing batch is not rewritten. This screen does not create a material type, post stock, or change the client status indicator. Restricted use is not blocked stock and not inspection stock. A transport is refused. Opening this screen writes nothing.', 'TIER_2_CONFIGURED', '/config/batch-initial-status', 'B', NULL, true, 'MIGRATION_9131', '2026-11-10 08:54:11.493813+00', 'SEED', '2026-11-10 08:54:14.798884+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('068b3d73-0b3f-4064-abaf-021b9186a336', 'CFG.INV.BATCHSTRATEGY.DEFINE', NULL, 'Inventory Management strategy types', 'CONFIG_ACTIVITY', 'INV', 'Inventory Management strategy types. OMCW is a search alias only. The view is VV_T685H_ME. Usage is H and application is ME. The key is the condition type, one to four uppercase letters or digits. The description is at most twenty characters. An access sequence is optional and must already stand on OMCX. Naming it does not run an access. Selection classes, sort rules, quantity-proposal exits, and batch splits are not stored. Class type 023 is not active. A strategy type does not select a batch. Production and sales strategy types are not this screen. A transport and a plant are refused. Opening this screen writes nothing.', 'TIER_2_CONFIGURED', '/config/batch-strategy-types', 'B', NULL, true, 'MIGRATION_9133', '2026-11-10 08:54:11.500195+00', 'SEED', '2026-11-10 08:54:14.802226+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('fb2ee1cc-331e-4151-a9c8-8bd35ffb281b', 'CFG.INV.BATCHACCESS.DEFINE', NULL, 'Inventory Management access sequences', 'CONFIG_ACTIVITY', 'INV', 'Inventory Management access sequences. OMCX is a search alias only. The view is VV_T682_ME. Usage is H and application is ME. The key is four uppercase letters or digits. The description is at most thirty characters. An access names a condition table that already stands on OMA1. The access number is two digits and need not be gap-free. Naming a table does not search it. An exclusive indicator, a requirement, and a field mapping are not stored. A strategy type may name a standing sequence, and that name does not run an access or select a batch. Production and sales access sequences are not this screen. A transport and a plant are refused. Opening this screen writes nothing.', 'TIER_2_CONFIGURED', '/config/batch-access-sequences', 'B', NULL, true, 'MIGRATION_9134', '2026-11-10 08:54:11.505254+00', 'SEED', '2026-11-10 08:54:14.803933+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('2cda9bea-1242-4a9e-ba41-98053bedfd97', 'CFG.INV.BATCHCONDTABLE.DEFINE', NULL, 'Inventory Management condition tables', 'CONFIG_ACTIVITY', 'INV', 'Inventory Management condition tables. OMA1 is a search alias only. Change and display are the same screen. Usage is H and application is ME. The number is three digits from 501 to 999. The SAP key area, 001 to 500, is refused and is not seeded. The key fields are the Inventory Management list: movement type, customer, storage location, supplier, material group, material, material type, special stock, and plant. A field outside that list is refused. No physical table is generated. No condition record is stored. An access sequence does not search this table, and a goods movement is not changed. Production and sales condition tables are not this screen. A transport and a plant value are refused. Opening this screen writes nothing.', 'TIER_2_CONFIGURED', '/config/batch-condition-tables', 'B', NULL, true, 'MIGRATION_9135', '2026-11-10 08:54:11.510823+00', 'SEED', '2026-11-10 08:54:14.805568+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('927a3ac5-b367-4ba1-b40b-f459cf018da3', 'PROC.CONTRACT.RELEASE', NULL, 'Release purchase contract', 'TRANSACTION', 'PROC', 'Release a contract when a strategy claims it. ME35K is a search alias. No strategy means no release is required.', 'TIER_1_BUILT', '/purchasing/contracts', 'B', NULL, true, 'MIGRATION_9147', '2026-11-10 08:54:11.576686+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('700c5ba9-f35f-4433-807f-74cd7233d05f', 'CFG.INV.BATCHDOCMGMT.DEFINE', NULL, 'Activate document management for batches', 'CONFIG_ACTIVITY', 'INV', 'Activate document management for batches. ODOC is a search alias only. The stored code is X when active, and blank when not active. A missing row is not active. Activation makes the documents tab visible on the batch master. Deactivation hides that tab. A batch, a document, and a link are not deleted. No document info record is created, and no file is stored. CV01N, MB56, MB57, and MB5C are not this screen. A goods movement does not create an attachment because this indicator is on. A closed posting period does not block this screen. Opening this screen writes nothing.', 'TIER_2_CONFIGURED', '/config/batch-document-management', 'B', NULL, true, 'MIGRATION_9144', '2026-11-10 08:54:11.562222+00', 'SEED', '2026-11-10 08:54:14.795052+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('8880d740-a95d-4dcd-b587-fd93a9699fb3', 'CFG.PROD.WIPBATCH.DEFINE', NULL, 'Activate WIP batch', 'CONFIG_ACTIVITY', 'PP', 'Activate WIP batch. OMCWB is a search alias only. The stored code is X when active, and blank when not active. A missing row is not active. Activation requires a batch level and an explicit confirmation. Once X is saved it cannot be revoked. The save does not create a WIP batch, a production order, a confirmation, or a material document. Business function LOG_PP_WIP_BATCH, original-batch reference material, a confirmation profile, and a control key are not this screen. A closed posting period does not block it. Opening this screen writes nothing.', 'TIER_2_CONFIGURED', '/config/wip-batch', 'B', NULL, true, 'MIGRATION_9145', '2026-11-10 08:54:11.567229+00', 'SEED', '2026-11-10 08:54:14.797118+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('7bce415d-a227-40e1-9810-3f413ec545a7', 'CFG.INV.BATCHSEARCH.DEFINE', NULL, 'Inventory Management search procedures', 'CONFIG_ACTIVITY', 'INV', 'Inventory Management search procedures. OMCY is a search alias only. Usage is H and application is ME. The key is one to six uppercase letters or digits. The description is at most thirty characters. A step names a strategy type that already stands on OMCW. The step number is three digits and the counter is two digits. Neither need be gap-free. Naming a strategy type does not select a batch. A requirement, a manual indicator, and a movement-type allocation are not stored. Production and sales search procedures are not this screen. A transport and a plant are refused. Opening this screen writes nothing.', 'TIER_2_CONFIGURED', '/config/batch-search-procedures', 'B', NULL, true, 'MIGRATION_9137', '2026-11-10 08:54:11.522359+00', 'SEED', '2026-11-10 08:54:14.807203+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('ae101400-d2d0-491b-bfb6-08d697e26df1', 'INV.BATCHSTRATEGY.MAINTAIN', NULL, 'Batch search strategy', 'TRANSACTION', 'INV', 'Inventory Management batch search strategy. MBC1 creates it, MBC2 changes the validity period, and MBC3 displays it. Usage is H and application is ME. The strategy type must already stand on OMCW and name an access sequence. The key combination is a condition table named by that sequence. The key fields are that table''s fields, not a hard-coded plant or material. Validity from must not be later than validity to, and the same key must not overlap. A selection class, a sort rule, and a quantity proposal are not stored. Class type 023 is not active. Saving does not select a batch or post stock. Production and sales strategies are not this screen. Opening this screen writes nothing.', 'TIER_1_BUILT', '/inventory/batch-search-strategies', 'B', NULL, true, 'MIGRATION_9140', '2026-11-10 08:54:11.53924+00', 'SEED', '2026-11-10 08:54:14.819749+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('a91800e9-e09c-433e-bc5d-d80c3e3ceca6', 'INV.BATCHCLASS.MAINTAIN', NULL, 'Batch class', 'TRANSACTION', 'INV', 'Batch class. BMC1 creates it, BMC2 changes its description and characteristic assignments, and BMC3 displays it. This is not CL01. The class is stored in the standing class tables. The class type is derived from the batch level: 022 at plant level, 023 at material or client level. It is not hard-coded, and it is not the house word BATCH. The class name is at most 18 characters. Characteristics must already stand and are not created here. A blocked characteristic is refused. One description is stored. A released or locked status is not invented. The class is not assigned to a material or a batch. Characteristic values are not stored. Saving does not select a batch or post stock. A goods movement is not changed. Opening this screen writes nothing.', 'TIER_1_BUILT', '/inventory/batch-classes', 'B', NULL, true, 'MIGRATION_9141', '2026-11-10 08:54:11.546806+00', 'SEED', '2026-11-10 08:54:14.82244+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d9d3c1fe-41c3-4b1b-adcc-87ff638c527f', 'INV.BATCHSORT.MAINTAIN', NULL, 'Batch sort sequence', 'TRANSACTION', 'INV', 'Batch sort sequence. CU70 creates it, CU71 changes it, and CU72 displays it. The name is at most 18 characters. The description is at most 40 characters, in one language. Status is 0 in preparation, 1 released, or 2 locked. Each criterion names a standing characteristic, or the stock exceptions LOBM_LGORT and LOBM_MENGE, and sorts ascending or descending. Those two must not stand in a batch class. A weighting factor is not stored. The sequence is not assigned to a search strategy. It does not select a batch, read a characteristic value, or post. Production, sales, and warehouse determination are not this screen. Opening this screen writes nothing.', 'TIER_1_BUILT', '/inventory/batch-sort-sequences', 'B', NULL, true, 'MIGRATION_9142', '2026-11-10 08:54:11.549531+00', 'SEED', '2026-11-10 08:54:14.825324+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('8473ecb2-f55e-46ed-8a80-af2bdebdb690', 'INV.SLED.LIST', 'material', 'Material master', 'TRANSACTION', 'INV', 'Basic and organisational material master views.', 'REFERENCE', '/inventory/materials', 'B', NULL, true, 'MIGRATION_9146', '2026-11-10 08:54:11.572458+00', 'SEED', '2026-11-10 08:54:14.839406+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('bd6f44b1-9c50-4d07-8db0-b266dc57f7c5', 'PROC.SARELEASE.CREATE', 'scheduling_agreement_release', 'Scheduling agreement release', 'TRANSACTION', 'PROC', 'Create scheduling agreement releases from delivery schedule lines. ME84 is a search alias. Saving does not post, and it does not notify the supplier.', 'TIER_1_BUILT', '/purchasing/scheduling-agreement-releases', 'B', NULL, true, 'MIGRATION_9153', '2026-11-10 08:54:11.621451+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('b4c1b523-6a82-4fc2-bf5f-a0950251b998', 'CO.BUDGET.ORIGINAL.CHANGE', 'internal_order_original_budget', 'Original budget', 'TRANSACTION', 'CO', 'Change the original budget of an internal order. KO22 is a search alias. Saving does not post, supplement, return, or settle.', 'TIER_1_BUILT', '/controlling/original-budget', 'B', NULL, true, 'MIGRATION_9154', '2026-11-10 08:54:11.633993+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('eea6386c-6046-4203-9b3f-92016c2b0966', 'CO.BUDGET.ORIGINAL.DISPLAY', NULL, 'Display original budget', 'TRANSACTION', 'CO', 'Display the original budget of an internal order. KO23 is a search alias. Display writes nothing.', 'TIER_1_BUILT', '/controlling/original-budget-display', 'B', NULL, true, 'MIGRATION_9154', '2026-11-10 08:54:11.633993+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('81f49045-9526-45d2-b792-1e8d7d1be87b', 'CO.PLANREVAL.CREATE', 'plan_revaluation_order', 'Plan revaluation', 'TRANSACTION', 'CO', 'Create a plan-revaluation definition for internal orders. KOP1 is a search alias. Saving does not change plan amounts. KOPU is not this screen.', 'TIER_1_BUILT', '/controlling/plan-revaluation', 'B', NULL, true, 'MIGRATION_9155', '2026-11-10 08:54:11.645157+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('857032e1-66d6-4213-af2e-52ec0b26bf65', 'CO.SETTLE.RULE', 'settlement_distribution_rule', 'Settlement rule', 'TRANSACTION', 'CO', 'Store the settlement rule an order settlement reads. Saving does not post. This screen has no SAP transaction code. KO02 and KO8B are not this screen.', 'TIER_1_BUILT', '/controlling/settlement-rules', 'B', NULL, true, 'MIGRATION_9157', '2026-11-10 08:54:11.655223+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('9325625a-ec3e-4e04-a748-07301142c5f4', 'CO.SETTLE.ORDER', NULL, 'Actual settlement', 'TRANSACTION', 'CO', 'Settle one internal order. KO88 is a search alias. An update posts only when a distribution rule is stored. A receiver is not assumed.', 'TIER_1_BUILT', '/controlling/order-settlement', 'B', NULL, true, 'MIGRATION_9156', '2026-11-10 08:54:11.652834+00', 'MIGRATION_9157', '2026-11-10 08:54:11.655223+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('8c4e804e-0498-4a96-8b5b-b5f9155245b9', 'CO.SETTLE.COLLECTIVE', NULL, 'Collective actual settlement', 'TRANSACTION', 'CO', 'Settle a selection of internal orders. KO8G is a search alias. It calls the same settlement as KO88. A receiver is not assumed.', 'TIER_1_BUILT', '/controlling/order-settlement-collective', 'B', NULL, true, 'MIGRATION_9156', '2026-11-10 08:54:11.652834+00', 'MIGRATION_9157', '2026-11-10 08:54:11.655223+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('fa6607cb-df01-494f-8542-f969d28fbbda', 'PROD.WORKCENTER.CREATE', 'work_center', 'Create work center', 'TRANSACTION', 'PROD', 'Create a work center in a plant. CR01 is a search alias. A formula is stored and not calculated. No routing is created.', 'TIER_1_BUILT', '/production/work-centers', 'B', NULL, true, 'MIGRATION_9158', '2026-11-10 08:54:11.67092+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('889c179b-73c4-4fb8-916f-28345bcb4524', 'PROD.WORKCENTER.CHANGE', NULL, 'Change work center', 'TRANSACTION', 'PROD', 'Change a work center. CR02 is a search alias. The category cannot be changed. Historical orders are not rewritten.', 'TIER_1_BUILT', '/production/work-centers', 'B', NULL, true, 'MIGRATION_9158', '2026-11-10 08:54:11.67092+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('0d317187-e5d0-40d9-8b4e-ca3a78ed81f8', 'PROD.WORKCENTER.DISPLAY', NULL, 'Display work center', 'TRANSACTION', 'PROD', 'Display a work center. CR03 is a search alias. Display writes nothing.', 'TIER_1_BUILT', '/production/work-center-display', 'B', NULL, true, 'MIGRATION_9158', '2026-11-10 08:54:11.67092+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('e66a63b9-a846-4a41-b50b-162990e0f613', 'PROD.BOM.CHANGE', NULL, 'Change material BOM', 'TRANSACTION', 'PROD', 'Change a material BOM. CS02 is a search alias. The material, plant, usage, and alternative are fixed. Item numbers are kept. A saved production order is not rewritten.', 'TIER_1_BUILT', '/production/boms', 'B', NULL, true, 'MIGRATION_9159', '2026-11-10 08:54:11.684104+00', 'SEED', '2026-11-10 08:54:14.438852+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('c7c56883-bfe6-4c90-ad8d-e09b7cfdd797', 'PROD.BOM.DISPLAY', NULL, 'Display material BOM', 'TRANSACTION', 'PROD', 'Display a material BOM. CS03 is a search alias. Display writes nothing and takes no change lock.', 'TIER_1_BUILT', '/production/bom-display', 'B', NULL, true, 'MIGRATION_9159', '2026-11-10 08:54:11.684104+00', 'SEED', '2026-11-10 08:54:14.440717+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('67b9b494-5e58-49a3-a72e-baf81fb28bea', 'PROD.ROUTING.CREATE', 'routing', 'Create routing', 'TRANSACTION', 'PROD', 'Create a standard routing. CA01 is a search alias, not the chart of accounts. Only the standard sequence is stored. A formula is not calculated. A production order is not rewritten.', 'TIER_1_BUILT', '/production/routings', 'B', NULL, true, 'MIGRATION_9160', '2026-11-10 08:54:11.703336+00', 'SEED', '2026-11-10 08:54:14.442265+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d210dffa-718e-449c-acec-fe3c79aec561', 'PROD.ROUTING.CHANGE', NULL, 'Change routing', 'TRANSACTION', 'PROD', 'Change a standard routing. CA02 is a search alias. The task list type, group, counter, and plant are fixed. A saved production order is not rewritten.', 'TIER_1_BUILT', '/production/routings', 'B', NULL, true, 'MIGRATION_9160', '2026-11-10 08:54:11.703336+00', 'SEED', '2026-11-10 08:54:14.443956+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('6b2d6f96-c680-4f34-8466-23c8ca03d24f', 'PROD.ROUTING.DISPLAY', NULL, 'Display routing', 'TRANSACTION', 'PROD', 'Display a standard routing. CA03 is a search alias. Display writes nothing and takes no change lock.', 'TIER_1_BUILT', '/production/routing-display', 'B', NULL, true, 'MIGRATION_9160', '2026-11-10 08:54:11.703336+00', 'SEED', '2026-11-10 08:54:14.445263+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('4103b188-f5bb-44d2-9b50-2b60e246d2dc', 'PROD.VERSION.CREATE', 'production_version', 'Maintain production version', 'TRANSACTION', 'PROD', 'Maintain a production version. C223 is a search alias. The version names one BOM alternative and one standard routing. A change number is refused. A production order is not rewritten.', 'TIER_1_BUILT', '/production/production-versions', 'B', NULL, true, 'MIGRATION_9161', '2026-11-10 08:54:11.735626+00', 'SEED', '2026-11-10 08:54:14.447139+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('206c5e64-9d8d-4a05-9ff6-d7e956b257a7', 'PROD.VERSION.CHANGE', NULL, 'Change production version', 'TRANSACTION', 'PROD', 'Change a production version. The material, plant, and version are fixed. A saved production order is not rewritten.', 'TIER_1_BUILT', '/production/production-versions', 'B', NULL, true, 'MIGRATION_9161', '2026-11-10 08:54:11.735626+00', 'SEED', '2026-11-10 08:54:14.448765+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('7722c162-1ed3-4896-bd64-2ae7ffa7f022', 'PROD.VERSION.DISPLAY', NULL, 'Display production version', 'TRANSACTION', 'PROD', 'Display a production version. Display writes nothing and takes no change lock.', 'TIER_1_BUILT', '/production/production-version-display', 'B', NULL, true, 'MIGRATION_9161', '2026-11-10 08:54:11.735626+00', 'SEED', '2026-11-10 08:54:14.449782+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('50378b92-818c-4efb-979e-eb35105a7d61', 'PROD.MRP.SINGLE', NULL, 'Single-item planning', 'TRANSACTION', 'PROD', 'Plan one material and the components of its production version. MD02 is a search alias. The plant run is a different screen and does not explode a typed bill of material. A missing version is a diagnostic, not a guessed BOM. An MRP area, lead-time scheduling, and delete-and-recreate are refused. A check writes no proposal and no dependent requirement. The run posts nothing.', 'TIER_1_BUILT', '/production/single-item-planning', 'B', NULL, true, 'MIGRATION_9162', '2026-11-10 08:54:11.749055+00', 'SEED', '2026-11-10 08:54:14.46589+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('253dd08a-8a92-4030-b27e-944a3d3cde56', 'PROD.ORDER.INFO', NULL, 'Production order information', 'TRANSACTION', 'PROD', 'List production orders and planned orders. COOIS is a search alias. Order headers, components, confirmations, documented goods movements, and planned orders are read from the records that stand. Operations, sequences, capacities, automatic goods movements, and purchase documents are not this list. Execute writes nothing. Cost is not shown. CO03, CO02, CO11N, CO15, and MD13 are other screens.', 'TIER_1_BUILT', '/production/order-information', 'B', NULL, true, 'MIGRATION_9171', '2026-11-10 08:54:11.791914+00', 'SEED', '2026-11-10 08:54:14.458767+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('177c2bac-f1e8-41f1-b1ad-4a7157e9959b', 'PROD.CONFIRM.CANCEL', NULL, 'Cancel production order confirmation', 'TRANSACTION', 'PROD', 'Cancel one posted confirmation. CO13 is a search alias. Operation and header confirmations are both in scope. The original confirmation and its activities stay as posted. A cancellation record is linked to that confirmation and can be written once. A cancelled final no longer blocks a new confirmation. A material document the confirmation caused is not reversed here; while such a document stands, the cancellation is refused, and the goods-movement screen is named as the way to reverse it.', 'TIER_1_BUILT', '/production/confirmation-cancel', 'B', NULL, true, 'MIGRATION_9172', '2026-11-10 08:54:11.798576+00', 'MIGRATION_9188', '2026-11-10 08:54:11.869443+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('dc718fba-1c77-4291-bc97-bb451556b23c', 'PROD.ORDER.CHANGE', NULL, 'Change production order', 'TRANSACTION', 'PROD', 'Change a production order. CO02 is a search alias. The number, material, plant, unit, and status stay fixed. Quantity, dates, and components can change while no goods movement and no confirmation cite the order. A header quantity change does not rescale components. Operations are not stored. Change does not release the order, does not change a posted confirmation, and posts nothing.', 'TIER_1_BUILT', '/production/production-order-change', 'B', NULL, true, 'MIGRATION_9167', '2026-11-10 08:54:11.770338+00', 'SEED', '2026-11-10 08:54:14.453365+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('45c42e53-f2c6-4fa9-8563-0d935ab85402', 'FIN.CUSTOMER.COMPANY.MAINTAIN', NULL, 'Customer company accounting', 'TRANSACTION', 'FIN', 'Company-scoped AR reconciliation and payment terms; no billing or clearing.', 'TIER_1_BUILT', '/foundation/partners?view=CUSTOMER_COMPANY', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.261508+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('46487d8e-49b5-4afc-8ffe-6bb4d6305d16', 'SALES.CUSTOMER.SALESAREA.MAINTAIN', NULL, 'Customer sales area defaults', 'TRANSACTION', 'SALES', 'Sales-area pricing procedure, delivering plant and delivery defaults; no order or billing.', 'TIER_1_BUILT', '/foundation/partners?view=CUSTOMER_SALES', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.263502+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('c2f86958-775c-4431-8b59-aa63b7521b77', 'PROD.ORDER.DISPLAY', NULL, 'Display production order', 'TRANSACTION', 'PROD', 'Display a production order. CO03 and CO14 are search aliases. The number is the key. Quantity, dates, status, components, and a stored planned-order link are shown as stored. Issued and received quantities are read from material documents. An order type, operations, and sequences are not stored. Display writes nothing.', 'TIER_1_BUILT', '/production/production-order-display', 'B', NULL, true, 'MIGRATION_9167', '2026-11-10 08:54:11.770338+00', 'SEED', '2026-11-10 08:54:14.450808+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('3a81b153-56bd-49b9-b7d4-89c4eaffea94', 'PROD.MRP.SINGLELEVEL', NULL, 'Single-level planning', 'TRANSACTION', 'PROD', 'Plan one material in one plant and do not plan a lower-level component. MD03 is a search alias. Adapt existing does not explode. Re-explode writes dependent requirements and does not plan the component. Delete and recreate is refused. An MRP area, a scheduling-agreement schedule line, an MRP list, and a creation indicator are refused. A check writes nothing. The run posts nothing.', 'TIER_1_BUILT', '/production/single-level-planning', 'B', NULL, true, 'MIGRATION_9168', '2026-11-10 08:54:11.773235+00', 'SEED', '2026-11-10 08:54:14.467776+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('bc4b1e68-1e2c-43fb-af41-82a37397e146', 'PROD.PLANNEDORDER.CHANGE', NULL, 'Change planned order', 'TRANSACTION', 'PROD', 'Change a planned order. MD12 is a search alias. The number, material, plant, and origin stay fixed. Quantity, dates, and firming can change. A change of quantity or dates firms the order. An MRP area, a production version, a BOM, a routing, and a deletion flag are not stored. Change does not convert the order and posts nothing.', 'TIER_1_BUILT', '/production/planned-order-change', 'B', NULL, true, 'MIGRATION_9164', '2026-11-10 08:54:11.761147+00', 'SEED', '2026-11-10 08:54:14.471292+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('445b5c5f-10a5-4934-9ca9-92c986278b66', 'PROD.PLANNEDORDER.CREATE', NULL, 'Create planned order', 'TRANSACTION', 'PROD', 'Create a planned order by hand. MD11 is a search alias. The number is drawn from the planned-order range. The order is firmed and the origin is manual. A bought material is refused. A planned-order profile, an MRP area, and a production version are not stored. Create does not explode a bill of material, does not convert the order, and posts nothing.', 'TIER_1_BUILT', '/production/planned-order-create', 'B', NULL, true, 'MIGRATION_9165', '2026-11-10 08:54:11.763569+00', 'SEED', '2026-11-10 08:54:14.473145+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d07e6ab8-6732-403f-a024-949557de9bf9', 'PROD.PLANNEDORDER.CONVERT', NULL, 'Convert planned order', 'TRANSACTION', 'PROD', 'Convert one planned order into a production order. CO40 is a search alias. The existing order service creates the production order. The shared selector chooses the production version. The planned order is not deleted. A second conversion returns the existing order. External procurement and a partial quantity are refused. Operations are not stored on the production order. Availability is not checked. Conversion posts nothing.', 'TIER_1_BUILT', '/production/planned-order-conversion', 'B', NULL, true, 'MIGRATION_9166', '2026-11-10 08:54:11.766428+00', 'SEED', '2026-11-10 08:54:14.47464+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('fb219249-3d26-4a11-a1e1-bd0ff50fadbb', 'PROD.PLANNEDORDER.CONVERT.COLLECTIVE', NULL, 'Collective conversion', 'TRANSACTION', 'PROD', 'Convert a selected set of planned orders. CO41 is a search alias. Each order uses the same conversion service in its own transaction. Search writes nothing. An MRP area, an opening date, a sales order, a WBS element, and availability are refused as filters because they are not stored.', 'TIER_1_BUILT', '/production/planned-order-conversion-collective', 'B', NULL, true, 'MIGRATION_9166', '2026-11-10 08:54:11.766428+00', 'SEED', '2026-11-10 08:54:14.476238+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('5e7ecaf2-3ff5-4b77-8f36-3894fa876537', 'CFG.PROD.CHECKCTRL.DEFINE', NULL, 'Checking control', 'CONFIG_ACTIVITY', 'PROD', 'Checking control. OPJK is a search alias. The key is a standing plant, a standing production order type, and business function 1 or 2. Function 1 is check availability during order creation. Function 2 is check availability during order release. A missing record is not a check and not a no-check. The no-check indicator must be chosen. X means no automatic material availability check. Blank means the indicator is not set. Check on save must be chosen. X means that indicator is set. Blank means it is not set. Neither value runs a check. A checking rule is optional and must already stand. Blank is not a default rule. The category is production order only. Release, creation control, PRT, capacity, and a component-check type are not stored. CO01, release, conversion, and MRP do not read it. CO09 remains blocked. ATP is not calculated.', 'TIER_2_CONFIGURED', '/config/checking-control', 'B', NULL, true, 'MIGRATION_9180', '2026-11-10 08:54:11.838193+00', 'SEED', '2026-11-10 08:54:14.840683+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('f2eac71c-68ba-4b90-8e4f-e84ab5d6b411', 'SALES.ORDER.CREATE', 'sales_order', 'Sales order', 'TRANSACTION', 'SD', 'Sales order entry and change: the header, its items, and the price each item is read from. VA01, VA02 and VA03 are search aliases of this one screen; the order reserves nothing and posts nothing. Credit blocking and its release are at /finance/credit-release, the prices are maintained at /sales/conditions, and the outbound delivery, goods issue and billing are the next link of the chain.', 'TIER_1_LIVE', '/sales/orders', 'B', NULL, true, 'MIGRATION_9190', '2026-11-10 08:54:11.875794+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('2c1281d7-7b99-4ff8-88ac-1b390a56aa7a', 'CFG.SALES.CONDITION.MAINTAIN', 'sales_condition_record', 'Sales condition records', 'TRANSACTION', 'SD', 'The price a customer is charged for a material in a sales area, valid for a period. VK11, VK12 and VK13 are search aliases of this screen. A saved change closes the record that stood and inserts the new span, so an order priced earlier still reads the price it was priced at. Sales orders take their prices only from these records.', 'TIER_1_LIVE', '/sales/conditions', 'B', NULL, true, 'MIGRATION_9190', '2026-11-10 08:54:11.875794+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('25f54e4b-5377-415d-9520-078cf06a6bde', 'SALES.DELIVERY.CREATE', 'delivery', 'Outbound delivery', 'TRANSACTION', 'SD', 'The shipment the warehouse makes for an order: a delivery is created from the open quantity of an order line, picked, and then goods-issued through the inventory movement engine. VL01N, VL02N and VL10 are search aliases of this screen. A delivery on its own posts nothing and moves nothing; the credit check that blocks an order also refuses its delivery.', 'TIER_1_LIVE', '/sales/delivery', 'B', NULL, true, 'MIGRATION_9191', '2026-11-10 08:54:11.890006+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('524a405e-07b7-48a3-9aa6-12728d0dfc74', 'SALES.BILLING.CREATE', 'billing_document', 'Billing document', 'TRANSACTION', 'SD', 'The invoice a goods-issued delivery earns: the quantity is what left the plant, the price and the condition record are read from the order line, and the receivable is posted by the accounting-invoice service in the customer''s own company code. VF01, VF02, VF04 and VF11 are search aliases of this screen. A delivered line can be billed once.', 'TIER_1_LIVE', '/sales/billing', 'B', NULL, true, 'MIGRATION_9191', '2026-11-10 08:54:11.890006+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('f1380fad-d6a0-4add-b6a9-1ab466dcd0b6', 'CFG.PROD.AVCHECK.DEFINE', NULL, 'Availability check configuration', 'CONFIG_ACTIVITY', 'PROD', 'Availability-check configuration. OVZ2, OPJL, OVZ9, and OPJJ are search aliases only. A checking group is client customizing, assigned on the material plant view, and is not a checking rule. A missing assignment is not a default group. A checking rule names a business context and is not bound to order creation, conversion, MRP, or sales. A scope of check is the pair of one standing group and one standing rule. It stores inclusion controls only for sources this system can name. It does not calculate ATP, does not read MD04, and does not post. Replenishment lead time, sales orders, deliveries, stock in transfer, dependent reservations, and storage-location inspection are refused.', 'TIER_2_CONFIGURED', '/config/availability-check', 'B', NULL, true, 'MIGRATION_9177', '2026-11-10 08:54:11.817464+00', 'SEED', '2026-11-10 08:54:14.430924+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('735e89b6-5fec-411f-907d-e88bd743b479', 'CFG.PROD.ORDERTYPE.DEFINE', NULL, 'Production order type', 'CONFIG_ACTIVITY', 'PROD', 'Production order type. OPJH is a search alias. The key is four characters and is not a plant. The category is the production-order category only. A description is required. Number range, settlement, status profile, release, scheduling, costing, and checking control are not stored. Creating a type does not create an order and does not change numbering. CO01 and conversion do not read it.', 'TIER_2_CONFIGURED', '/config/production-order-types', 'B', NULL, true, 'MIGRATION_9178', '2026-11-10 08:54:11.827736+00', 'SEED', '2026-11-10 08:54:14.433865+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('e4b6916e-ea6f-461c-9b98-81b5fecf2ada', 'PROD.CONFIRM.ENTER', NULL, 'Enter time ticket', 'TRANSACTION', 'PROD', 'Enter a time ticket for one operation of a released production order. CO11N is a search alias. The operation is read from the production version and snapshotted on the confirmation. Partial leaves the operation open. Final blocks another confirmation of that operation and does not change the order status. A check writes nothing. Backflush, automatic goods receipt, a confirmation profile, personnel, and cancellation are refused. CO13, CO14, and CO15 are not this screen. The confirmation posts nothing.', 'TIER_1_BUILT', '/production/time-ticket', 'B', NULL, true, 'MIGRATION_9169', '2026-11-10 08:54:11.776348+00', 'SEED', '2026-11-10 08:54:14.455091+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('95b58a8d-eb63-4fa9-bad2-a12c30b024a8', 'CFG.COST.SETTLEMENT.DEFINE', 'settlement_profile', 'Settlement configuration', 'CONFIG_ACTIVITY', 'CO', 'Shared settlement configuration: the allocation structure with its account assignments, the settlement profile, and the settlement profile an internal order type reads. This screen has no SAP transaction code. It maintains rows every order of a type shares; the rule of one order is stored at /controlling/settlement-rules, and a settlement run reads what is stored here without changing it. A profile states its document type and its allowed distribution methods explicitly, none inferred from an order. An assignment an unsettled balance still reads, a profile an order type resolves to, and a method a rule of its orders uses are each refused rather than stranded. Opening this screen writes nothing.', 'TIER_2_CONFIGURED', '/config/settlement-configuration', 'B', NULL, true, 'MIGRATION_9189', '2026-11-10 08:54:11.87257+00', 'SEED', '2026-11-10 08:54:14.59468+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('328bc2a9-b5d3-4a65-b736-979721b43855', 'QM.LOT.CREATE', 'quality_lot', 'Inspection lot', 'TRANSACTION', 'QM', 'The record that a received quantity is under inspection: one lot per material-document line, read back with the movement, batch and segment of the goods it names. The lot posts nothing and decides nothing - results, tolerances, sampling and the usage decision that would restrict or release the goods are not built (D1 to D5, 2026-10-28), and quarantine at receipt is still open as DI-022.', 'TIER_2_CONFIGURED', '/quality/lots', 'C', NULL, true, 'MIGRATION_9192', '2026-11-10 08:54:11.909906+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('22d1d77e-e0cf-4af0-8ae1-42ec73681efb', 'CFG.PEOPLE.PAYCOMPONENT.DEFINE', 'pay_component', 'Define pay components', 'CONFIG_ACTIVITY', 'PEOPLE', 'Pay components and their mappings: what a tenant calls a kind of pay, which account of which chart it moves, and whether a cost centre carries it. A component is retired by validity and never deleted while a mapping cites it; the mapping is corrected in place, which is why no account is removed from under it. No amount is computed here — the payroll calculation rules are the tenant''s jurisdiction decisions (§15.3), and CAIRN.md refuses to ship guessed ones.', 'TIER_2_CONFIGURED', '/config/pay-components', 'B', NULL, true, 'MIGRATION_9195', '2026-11-10 08:54:11.945963+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('4ceb5e24-63e2-48ec-b40a-aca76c7e874c', 'PEOPLE.ORGUNIT.CREATE', 'org_unit', 'Organisational unit maintain', 'TRANSACTION', 'PEOPLE', 'The units an organisation is carved into, and the tree they stand in. A unit carries a name, a validity flag and a parent; it carries no company code and no cost centre, because no rule here assigns one.', 'TIER_1_BUILT', '/people/organization', 'B', NULL, true, 'MIGRATION_9194', '2026-11-10 08:54:11.930882+00', 'SEED', '2026-11-10 08:54:14.569654+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('3f4ac4df-881d-471e-8dca-b4dc857d5277', 'PEOPLE.TIME.ENTER', 'absence', 'Enter time and absence', 'TRANSACTION', 'PEOPLE', 'Record hours an employee worked on a day, and request, approve or reject an absence. Each type is defined by the tenant; an absence that reduces a quota lowers the balance the day it is approved. Nothing here posts to the general ledger.', 'TIER_1_BUILT', '/people/time-leave', 'B', NULL, true, 'MIGRATION_9197', '2026-11-10 08:54:11.957675+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('27bb1484-4ce0-4546-88bb-d352301e09b5', 'PEOPLE.LEAVE.VIEW', 'leave_quota', 'Leave quota and balance', 'TRANSACTION', 'PEOPLE', 'Show an employee''s leave entitlement, taken days and remaining balance for one type in one year, read back from the approved absences that produced it.', 'TIER_1_BUILT', '/people/time-leave', 'B', NULL, true, 'MIGRATION_9197', '2026-11-10 08:54:11.957675+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d399b11c-7d2b-4da1-bccd-28360c97857a', 'PROD.ORDER.SETTLE', NULL, 'Production order settlement', 'TRANSACTION', 'PROD', 'Settle one production order. PROD.ORDER.SETTLE is a search alias. No receiver or percentage is assumed. An update does not post while no settlement rule is configured. WIP calculation (DV-003) and variance categorization (DV-004) are deferred.', 'TIER_1_BUILT', '/production/order-settlement', 'B', NULL, true, 'MIGRATION_9201', '2026-11-10 08:54:11.980368+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('701b5bf2-b577-48e6-a586-28179e0bed1d', 'QM.INSPECTION.RECORD', 'inspection_result', 'Inspection result', 'TRANSACTION', 'QM', 'A measured or observed result against one characteristic on one inspection lot. Quantitative results carry a value, unit and tolerance check; qualitative results carry a result value. Partial recording is supported; a lot may have many results.', 'TIER_2_CONFIGURED', '/quality/inspection', 'C', NULL, true, 'MIGRATION_9203', '2026-11-10 08:54:11.991153+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('b6e76e85-c41d-435e-aeaf-a3442939cc0a', 'QM.USAGE.DECIDE', 'usage_decision', 'Usage decision', 'TRANSACTION', 'QM', 'The accept/reject/block/rework decision on one inspection lot. Validates that mandatory results are complete before the decision is recorded, prevents duplicate decisions, and gates whether the goods may leave quality inspection stock.', 'TIER_2_CONFIGURED', '/quality/inspection', 'C', NULL, true, 'MIGRATION_9203', '2026-11-10 08:54:11.991153+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('013f2567-5282-429a-b609-9932154d24f0', 'QM.STOCK.POST', NULL, 'Quality stock movement', 'TRANSACTION', 'QM', 'Moves stock between quality inspection, unrestricted-use and blocked stock categories following a usage decision. Accepted quality stock moves to unrestricted; rejected quality stock moves to blocked. Posted atomically with the usage decision so partial failure cannot leave inconsistent stock.', 'TIER_2_CONFIGURED', '/quality/inspection', 'C', NULL, true, 'MIGRATION_9203', '2026-11-10 08:54:11.991153+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('6f09fba3-777e-4196-8b7c-45f83ef1436d', 'PROD.GM.REPROCESS', NULL, 'Reprocess automatic production goods movements', 'TRANSACTION', 'PROD', 'COGI-style postprocessing for automatic goods movements produced by CO11N. Filter individual persisted failures, inspect attempt errors, correct supported line fields, retry the original movement, or retain an explicit audited discard. Source confirmation and original payload remain unchanged. Reservations are not adjusted by discard. Manual MIGO movements and CO15 header confirmations do not create these automatic movement failures in Cairn.', 'TIER_1_BUILT', '/production/cogi', 'B', NULL, true, 'MIGRATION_9213', '2026-11-10 08:54:12.038525+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('149b70c2-32f2-4152-97fe-d2da7b764239', 'PROD.ORDER.COST.DISPLAY', NULL, 'Production order cost report', 'TRANSACTION', 'PROD', 'Read posted journal debits, credits, and net balance assigned to a production order. Confirmed activity quantities are not monetarily valued; plan rates are not actuals. No WIP, variance categorization, or posting is performed.', 'TIER_1_BUILT', '/production/order-cost-report', 'B', NULL, true, 'MIGRATION_9215', '2026-11-10 08:54:12.058732+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('1851f3f5-1be2-4595-acb0-155b3cf918c6', 'CFG.PEOPLE.RECORDTYPE.DEFINE', 'record_type', 'Define employee record types', 'CONFIG_ACTIVITY', 'PEOPLE', 'What a record type is, and the fields it asks for, each with the kind of answer that fits it. A type is retired by validity and never deleted while a record cites it, and a field’s kind cannot be changed while records answer it in the kind it has now.', 'TIER_2_CONFIGURED', '/config/people-record-types', 'B', NULL, true, 'MIGRATION_9193', '2026-11-10 08:54:11.916755+00', 'SEED', '2026-11-10 08:54:14.56848+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('23784cfa-5718-41a8-a9f0-ae7e58eef30a', 'PEOPLE.POSITION.CREATE', 'position', 'Position maintain', 'TRANSACTION', 'PEOPLE', 'Positions and jobs: a position is one place someone can stand, a job is what is done there, and the reporting line joins one position to the position above it. Whether a position is filled is read from the assignments, never stored on it.', 'TIER_1_BUILT', '/people/organization', 'B', NULL, true, 'MIGRATION_9194', '2026-11-10 08:54:11.930882+00', 'SEED', '2026-11-10 08:54:14.574011+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('f66cdd2e-ffa3-4826-b5e3-a48a20f237bb', 'PEOPLE.ASSIGNMENT.MAINTAIN', 'position_assignment', 'Position/employee/cost centre assignment', 'TRANSACTION', 'PEOPLE', 'Putting a person in a position and a cost centre for a span of dates. A change is a new dated assignment that delimits the one it replaces; posting personnel cost to the cost centre named here is not built (§15.3, D-013).', 'TIER_1_BUILT', '/people/assignments', 'B', NULL, true, 'MIGRATION_9194', '2026-11-10 08:54:11.930882+00', 'SEED', '2026-11-10 08:54:14.577202+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('251abd75-1df6-41f8-876d-8f4ddbd4af46', 'FIN.AR.PAYMENT.ENTER', NULL, 'Post incoming payment', 'TRANSACTION', 'FIN', 'Incoming payment entry and allocation: a customer receipt settles the open receivables chosen for it — the bank or cash account debits at the receipt, the customer’s reconciliation account credits per allocation with the customer standing as partner, and every settled item clears in place under the payment document and the clearing date. The allocation must equal the receipt exactly; a difference is named, never silently resolved, and partial, residual and on-account outcomes stand apart as later acts. Document, posting and clearing dates are three distinct dates; the financial period judges on the posting date. A posted payment is history.', 'TIER_1_BUILT', '/finance/incoming-payment', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.267922+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('f551c22d-7d4a-4149-a2c3-4febf5e9fc52', 'FIN.AR.DOWNPAYMENT.POST', NULL, 'Post customer down payment', 'TRANSACTION', 'FIN', 'Customer down payment received: an advance against a special G/L indicator — the bank debits and the configured alternative customer reconciliation account credits, so the advance stands open outside ordinary receivables until cleared against invoices. Down-payment requests and clearing stand apart as later acts. A posted down payment is history.', 'TIER_1_BUILT', '/finance/customer-down-payment', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.270635+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('fadfb6e6-c0f8-41b2-8a5c-b460b7d7cd39', 'FIN.AP.DOWNPAYMENT.POST', NULL, 'Post vendor down payment', 'TRANSACTION', 'FIN', 'Vendor down payment: an advance paid against a special G/L indicator — the configured alternative reconciliation account debits and the bank credits, so the advance stands open outside ordinary payables until cleared against invoices. Down-payment requests and clearing stand apart as later acts. A posted down payment is history.', 'TIER_1_BUILT', '/finance/vendor-down-payment', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.273695+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('e620a55a-af84-4f64-b09f-38241354fcd8', 'FIN.AP.DOWNPAYMENT.CLEAR', NULL, 'Clear vendor down payment', 'TRANSACTION', 'FIN', 'Down-payment clearing: apply standing advances to open vendor invoices by a transfer posting — the ordinary reconciliation account debits per invoice settled, the alternative account credits per down payment applied, the applied totals required equal. Items applied in full clear in place; remainders stand open by the partial model. A posted clearing is history.', 'TIER_1_BUILT', '/finance/vendor-down-payment-clearing', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.276412+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('2e12ddc0-5aa7-48ec-b87b-69706433f968', 'FIN.AR.DOWNPAYMENT.CLEAR', NULL, 'Clear customer down payment', 'TRANSACTION', 'FIN', 'Customer down-payment clearing: apply standing advances to open customer invoices by a transfer posting — the alternative account debits per down payment applied, the ordinary reconciliation account credits per invoice settled, allocations pairwise across items with partial clearing standing open. Items applied in full clear in place; remainders stand open by the partial model. A posted clearing is history.', 'TIER_1_BUILT', '/finance/customer-down-payment-clearing', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.279043+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d24857c4-1bf7-4fd1-a078-5d638666c636', 'FIN.AR.DOWNPAYMENT.REQUEST', NULL, 'Post customer down payment request', 'TRANSACTION', 'FIN', 'Customer down-payment request: a noted item asking for an advance — no receivable, no receipt and no account movement. The request indicator stands configured with the actual indicator it expects; an F-29 receipt fulfills it by explicit allocation, fulfilled and remaining amounts deriving from the standing links. A posted request is history.', 'TIER_1_BUILT', '/finance/customer-down-payment-request', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.281719+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('20a40162-0b0e-4f9f-95c4-9d796be7a3f8', 'FIN.AP.DOWNPAYMENT.REQUEST', NULL, 'Post vendor down payment request', 'TRANSACTION', 'FIN', 'Vendor down-payment request: a noted item asking for an advance — no payable, no payment and no account movement. The request indicator stands configured with the actual indicator it expects; an F-48 payment fulfills it by explicit allocation, fulfilled and remaining amounts deriving from the standing links. A posted request is history.', 'TIER_1_BUILT', '/finance/vendor-down-payment-request', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.283876+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('bac90017-79da-4429-97a8-6b84cfced452', 'CFG.FIN.SPECIALGL.DEFINE', NULL, 'Define special G/L indicators', 'CONFIG_ACTIVITY', 'FIN', 'Special G/L indicators: the alternative reconciliation account each one-character indicator posts to, per account type (vendor/customer) and company scope, the tenant-wide scope standing as default; a request (noted) indicator instead names the actual indicator it expects at fulfillment.', 'TIER_2_CONFIGURED', '/config/special-gl', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.286+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('92f6c2f8-ea7e-48a4-89a2-c14ce757ac0f', 'FIN.AP.PAYMENT.POST', NULL, 'Post outgoing payment', 'TRANSACTION', 'FIN', 'Outgoing payment entry and allocation: a vendor payment settles the open payables chosen for it — the vendor’s reconciliation account debits per allocation with the vendor standing as partner, the bank account credits at the payment, and every settled item clears in place under the payment document and the clearing date. Credit items, the vendor side of credit memos, count against the payment, so the selected items net; the net allocation must equal the payment exactly and a difference is named, never silently resolved. Partial, residual, discount and on-account outcomes stand apart as later acts. Document, posting and clearing dates are three distinct dates; the financial period judges on the posting date. A posted payment is history.', 'TIER_1_BUILT', '/finance/outgoing-payment', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.289556+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('823150c6-90f3-44ae-b2f4-b11101b67c9c', 'FIN.AR.BALANCE', NULL, 'Customer balances', 'TRANSACTION', 'FIN', 'Customer balances, read-only: a customer’s period balances in a company derive at read time from the posted journal — opening balance from every earlier year, debit and credit turnover per fiscal period, closing chained period by period — in company currency, or in the currency the items stand in, with no conversion performed. Closed periods remain reportable; period control governs posting, never reporting. Choosing a period lists the customer line items behind it, clearing standing shown. Nothing here posts or clears.', 'TIER_1_BUILT', '/finance/customer-balances', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.292281+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('fb5ed43f-ba36-4d99-af4f-9a26223a3e85', 'FIN.AR.AGEING', NULL, 'Customer ageing', 'TRANSACTION', 'FIN', 'Customer ageing analysis, read-only: what customers owe a company, aged as of a key date — the mirror of vendor ageing over the shared derivation. Only items standing on the receivables reconciliation accounts age. Standing reconstructs historically: an item stands when it posted on or before the key date and was not cleared on or before it. Due dates come from the canonical payment-term service — the customer invoice baseline plus its terms, recomputed (the stored due date when the terms no longer stand, the posting date otherwise) — into not-yet-due and overdue buckets at three increasing thresholds, special G/L items only when selected, amounts in company-code currency, per customer with item detail and a company total. Nothing here posts or clears.', 'TIER_1_BUILT', '/finance/customer-ageing', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.29487+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('2caf3938-ea25-4585-8a1d-09a2679ce3c6', 'INV.MATERIAL.PRICECHANGE', NULL, 'Change material price', 'TRANSACTION', 'INV', 'Change the valuation price of a material at a plant. The current period posts the stock-value difference now, to inventory and price difference, and updates the book value. A previous period posts only when that material period is open for backposting and the financial period is open; the current book price is not changed. A future price is stored and does not post until it is released. A batch is not part of this screen.', 'TIER_1_BUILT', '/inventory/price-change', 'B', NULL, true, 'MIGRATION_9109', '2026-11-10 08:54:11.403565+00', 'SEED', '2026-11-10 08:54:14.51222+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('1c95f67d-11da-4955-bb2b-f1b6fce13405', 'FIN.DOCUMENT.REVERSE', NULL, 'Reverse accounting document', 'TRANSACTION', 'FIN', 'Reverse a posted accounting document: the original — named by company code, document number and fiscal year — stands displayed with its header, every line, amounts, clearing and reversal standing before the act. An active tenant reversal reason, an explicit confirmation, a reversal document date and a reversal posting date are required; the posting period derives from the posting date through the company fiscal-year variant, and a closed period refuses. The reversal posts as its own AB document, mirroring every line with debit and credit swapped and exact document and local amounts preserved, while the original stands marked reversed and the pair stands on a both-ways-unique link. A document with cleared lines, or standing as a clearing document, refuses and points to Reset Cleared Items; a reversal document cannot itself be reversed.', 'TIER_1_BUILT', '/finance/document-reversal', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.29769+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('be7b5b19-b37e-4544-b6cf-deeec40c64f6', 'FIN.CLEARING.RESET', NULL, 'Reset cleared items', 'TRANSACTION', 'FIN', 'Reset cleared items: a clearing document — named by company code, document number and fiscal year exactly as it stands stamped on the lines — is displayed with everything it cleared, and on explicit confirmation with a mandatory reason the clearing stamp lifts from every item, so the items stand open again. No journal posts and no document changes; the reset stands on a retained record naming the clearing document, the former clearing date, the items reopened and the reason, and the items may be cleared anew. Reversing the clearing document is a separate later act, never part of a reset.', 'TIER_1_BUILT', '/finance/clearing-reset', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.300282+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('f8cd2acd-9d8f-4199-846c-9158b102ff06', 'FIN.AR.INVOICE.POST', NULL, 'Enter customer invoice', 'TRANSACTION', 'FIN', 'Direct customer invoice posting: revenue lines carry tax-exclusive net amounts with output tax calculated at the standing rates, the gross judged against net plus tax before posting, and one balanced journal debiting the customer’s reconciliation account at gross with the customer standing as partner — the receivable open item — crediting each revenue line and the tax account by standing determination. The due date computes from the payment terms; a duplicate reference refuses naming the standing invoice; cancellation posts as a linked mirror document. A posted invoice is never edited or deleted.', 'TIER_1_BUILT', '/finance/customer-invoice', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.302715+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('bdfd9c1d-1b43-4307-99d2-1f2f13c0a42f', 'FIN.AP.AGEING', NULL, 'Vendor ageing', 'TRANSACTION', 'FIN', 'Vendor ageing analysis, read-only: what a company owes its suppliers, aged as of a key date. Only items standing on the payables reconciliation accounts age — a customer receivable or a stray partner line never belongs here. Standing reconstructs historically: an item stands when it posted on or before the key date and was not cleared on or before it, so an item cleared after the key date still stands at its full line amount, partial payments stand as their own open items and net inside the supplier total, and clearing resets erase the stamps history would need. Due dates come from the canonical payment-term service — the origin invoice baseline plus its terms, recomputed (the stored due date when the terms no longer stand, the posting date when no invoice stands behind the item) — into not-yet-due and overdue buckets at three increasing thresholds. Special G/L items join only when selected, carrying their indicator. Company codes run singly or as a range, grouped per company in company currency, with vendor, document and line-item summarization, six sorts, item drill to the document display and CSV export. Nothing here posts or clears, and posting-period status never suppresses a historical item.', 'TIER_1_BUILT', '/finance/vendor-ageing', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.305634+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('2ee77fe2-5d71-45d9-be9b-5060ed2158d3', 'FIN.AP.BALANCE', NULL, 'Vendor balances', 'TRANSACTION', 'FIN', 'Vendor balances and due items, read-only: a supplier’s period balances in a company derive at read time from the posted journal — opening balance from every earlier year, debit and credit turnover per fiscal period, closing chained period by period — in company currency, or in the currency the items stand in, with no conversion performed. Closed periods remain reportable; period control governs posting, never reporting. Choosing a period lists the vendor line items behind it, clearing standing shown. Nothing here posts or clears.', 'TIER_1_BUILT', '/finance/vendor-balances', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.308125+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('83911389-6ecb-40e4-8012-d895d759cfd4', 'FIN.AP.CLEAR', NULL, 'Clear vendor open items', 'TRANSACTION', 'FIN', 'Manual clearing of a supplier’s open items: invoices, credit memos and payments stand in one grid over the uncleared partner lines; a selection whose signed sum stands at zero in one currency clears under one balanced journal through the posting engine, the selected lines and the clearing lines stamped in place with the clearing document and the clearing date. Clearing, posting and document dates are three distinct dates; the financial period judges on the posting date. A posted clearing is history, preserved and shown, never edited or deleted.', 'TIER_1_BUILT', '/finance/vendor-clearing', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.310373+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('69b9f5b6-b392-4b77-8a87-36dac553d594', 'FIN.AP.INVOICE.POST', NULL, 'Enter vendor invoice', 'TRANSACTION', 'FIN', 'Direct vendor invoice entry without a purchase order: expense lines carry tax-exclusive net amounts with their cost or profit centres, input tax calculates at the standing rate, and the gross is judged — lines net plus tax must equal it. One balanced KR journal credits the vendor’s reconciliation account at the gross with the vendor as partner, the due date computed from the payment terms. A posted invoice is never edited or deleted; correction stands as a linked cancellation or a credit memo.', 'TIER_1_BUILT', '/finance/vendor-invoice', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.313209+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('9bbf318e-e407-4f7f-9abb-210e20ea8d72', 'FIN.AP.CREDITMEMO.POST', NULL, 'Enter vendor credit memo', 'TRANSACTION', 'FIN', 'Vendor credit memo entry: expense credit lines carry tax-exclusive net amounts, input tax reverses at the standing rate, and the gross credit is judged. Where an original invoice stands named, cumulative credits may never exceed it. One balanced KG journal debits the vendor’s reconciliation account at the gross credit with the vendor as partner. A posted memo is never edited or deleted; correction stands as a linked cancellation.', 'TIER_1_BUILT', '/finance/vendor-credit-memo', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.317759+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('07dc5877-0b2c-44a9-aa4e-47e648711862', 'FIN.AR.CLEAR', NULL, 'Clear customer open items', 'TRANSACTION', 'FIN', 'Manual clearing of a customer’s open items: invoices, credit memos and payments stand in one grid over the uncleared partner lines; a selection whose signed sum stands at zero in one currency clears under one balanced DZ journal through the posting engine, the selected lines and the clearing lines stamped in place with the clearing document and the clearing date. Clearing, posting and document dates are three distinct dates; the financial period judges on the posting date. Partial and residual clearing stand deferred. A posted clearing is history, preserved and shown, never edited or deleted.', 'TIER_1_BUILT', '/finance/customer-clearing', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.319972+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('8873fd35-999c-4eed-a5ac-9d63ba202671', 'CFG.PLT.CLIENT.ONBOARD', NULL, 'Tenant onboarding wizard', 'CONFIG_ACTIVITY', 'PLT', 'Guided setup of a new tenant: structure, accounts, periods, ranges.', 'TIER_2_CONFIGURED', '/clients/new', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.683544+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('a94f0d58-c7e2-48a7-9689-97bbd26f304d', 'CFG.WORKBENCH', NULL, 'Configuration workbench', 'CONFIG_ACTIVITY', 'PLT', 'The define and assign tree that mirrors an implementation plan (R-06).', 'TIER_2_CONFIGURED', '/config', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.686967+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('869dab60-191a-45c5-9370-6aab3c2bde3f', 'FIN.GL.CLEAR', NULL, 'Clear G/L account', 'TRANSACTION', 'FIN', 'Manual clearing of a G/L account’s open items: the account must stand extended to the company and open-item managed, segment-first with the chart flag as fallback. Uncleared posted lines stand in one grid with document, assignment and reference filters; a selection whose signed sum stands at zero in one currency clears under one balanced clearing journal through the posting engine, the operator-selected document type validated against configured types. Every item is re-read under row locks at posting, an item taken by another clearing is refused naming its clearing document, and the selected and clearing lines are stamped in place with the clearing document and date. Tolerance, partial and residual clearing stand deferred; a difference is never silently discarded. A posted clearing is history, preserved and shown, reset only through the FBRA workflow.', 'TIER_1_BUILT', '/finance/gl-clearing', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.322407+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('0d9bcd18-3a7d-49d6-a54c-f829b83073ef', 'FIN.RPT.CONSOLIDATE', NULL, 'Consolidation workbench', 'TRANSACTION', 'FIN', 'Configuration workbench for consolidation, never an execution or posting transaction: consolidation areas carry a data basis bound to the standing journal provider (BW providers not carried), a consolidation chart, fiscal-year variant and DRAFT/ACTIVE status. Units bind standing company codes; groups nest acyclically; unit assignments are time-dependent and refuse overlaps. Group accounts and source mappings judge standing charts and accounts. Methods are configuration only, including intercompany elimination whose execution stands deferred. Task hierarchies reference methods, units and groups that must stand before save, and activation refuses incomplete areas. Every write takes a reason and one change document; execution and the consolidation monitor stand apart.', 'TIER_1_BUILT', '/config/consolidation', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.325191+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('b0053fd0-b2eb-4534-8bbe-1ddf26bf8c72', 'FIN.CONSOLIDATE', NULL, 'Consolidation monitor', 'TRANSACTION', 'FIN', 'Consolidation monitor and orchestration: select an active UCWB area, group, version, fiscal year and period, then execute configured tasks individually or by root task group in UCWB dependency order. Parent tasks are prerequisites for the same tenant, area, group/unit scope, version, year, period and execution mode, revalidated when each run is reserved. Test runs simulate; update runs invoke only standing processing adapters. Every attempt receives a unique run ID and immutable logs, while current task status stands separately. Journal data collection and validation execute in this round; currency translation, investment consolidation and intercompany elimination remain blocked until their engines stand, intercompany last. The monitor never maintains UCWB configuration and never opens or closes FI posting periods.', 'TIER_1_BUILT', '/finance/consolidation-monitor', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.32753+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('b602c4ef-ff6a-41fa-be24-953caf24fc2d', 'FIN.RPT.CONSOLIDATE.STMT', NULL, 'Consolidated statements', 'TRANSACTION', 'FIN', 'Consolidated balance sheet and income statement over the UCWB consolidation chart: SAP consolidation global parameters — active area, group, version, fiscal year and period — select the scope, an optional unit filters the group, and the previous fiscal year can stand as comparison. Rows are the group accounts (FS items), classified as assets, liabilities, equity, revenue or expenses from the account types of their mapped source accounts; an item whose mappings mix sections stands named unclassified. POSTED journal lines of the group units company codes aggregate through the UCWB mappings, year-to-date and for the period, signed debit-minus-credit in local currency, per unit with a group total. Lines no mapping covers are totalled and named, and an all-lines balance check stands on the statement. CX20 monitor standing for the scope is displayed; totals aggregate reported data pre-elimination until the translation and elimination engines stand. The report posts and stores nothing.', 'TIER_1_BUILT', '/finance/consolidated-statements', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.331026+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('cf1088e3-5000-49d3-b605-4d061f1151f7', 'FIN.RPT.CASHFLOW', NULL, 'Cash flow statement', 'TRANSACTION', 'FIN', 'Cash flow statement, read-only: operating, investing and financing cash flows over the posted journal of one or more company codes for a fiscal year and period range judged per company fiscal-year variant, by the indirect method (default) or the direct method, on the leading ledger, with an optional previous-year comparison. Cash is defined by the house-bank G/L accounts; every other account classifies from standing configuration in precedence order — customers/vendors reconciliation accounts, BSX inventory determination, asset-class determination, then account type — and anything unclassifiable stands totalled and named. The indirect statement reads balance movements opening to closing with the depreciation add-back; the direct statement reads the offsetting lines of cash-touching documents. Opening and closing cash, the net change and a reconciliation difference against the cash-account movement stand on the statement, the difference explained by the unclassified lines and never forced. A company with no house-bank G/L account is refused by name. Multi-company totals stand only within one local currency, otherwise per-company columns stand. The report posts and stores nothing.', 'TIER_1_BUILT', '/finance/cash-flow', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.332083+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('4820e879-b5a4-4454-93e2-4df71ce28168', 'FIN.AR.DUNNING.RUN', NULL, 'Dunning programme', 'TRANSACTION', 'FIN', 'The dunning programme for customers: a run identified by its date and a short identification proposes every overdue item of the named companies as of the dunning date, each item at the dunning level its completed history earns; an account carrying no dunning procedure stands excluded with its reason, never silently skipped. Finalization stands separate from the proposal: it revalidates every item, writes one notice per account, and only then do levels advance. A dunning run posts no journal, and a completed run is history, never overwritten.', 'TIER_1_BUILT', '/finance/dunning', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.336981+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('4c276b94-362f-4227-9685-0047fdf41601', 'FIN.AP.PAYMENTRUN.EXECUTE', NULL, 'Payment run', 'TRANSACTION', 'FIN', 'The automatic payment run: parameters — run date and identification, posting date, documents-entered-up-to cutoff, next payment date, company codes, payment methods and a supplier range — gather a proposal over the open supplier items that stand due, blocked or unmatched items standing as named exceptions rather than dropping. Execution revalidates under lock and posts one balanced journal per supplier, currency and house-bank account, clearing the paid journal lines in place with the payment document and date; the financial period judges on the posting date, never the run date. An executed run is history: it cannot be executed again, regenerated or deleted, and its payments stand as retained documents.', 'TIER_1_BUILT', '/finance/payment-run', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.339575+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('9f66ae5d-c322-4952-bd1d-cd379ffb0e36', 'FIN.JOURNAL.POST', NULL, 'Post a journal entry', 'TRANSACTION', 'FIN', 'Enter a G/L account document on one screen: company, document and posting dates, a configured document type, currency at its precision, reference and header text, and an editable line grid (account, debit/credit, positive amount, cost centre, profit centre, assignment, line text) with insert, copy and delete, live totals and a confirmation summary. The server judges every account against the company chart, cost and profit centres against their validity, and the period against its openness inside the posting transaction; a request key makes a duplicate submission return the original document. Drafts park through the parked-journal workflow; posted documents reverse only through the reversal workflow.', 'TIER_1_BUILT', '/finance/journal/new', 'A', NULL, true, 'SEED', '2026-11-10 08:54:14.693147+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('48cc832e-db55-4191-ad9a-561eac07fa19', 'PROC.INV.RECORD', NULL, 'Enter incoming invoice', 'TRANSACTION', 'PROC', 'Invoice verification: a supplier invoice verified against its purchase order and the goods receipts posted under it. Invoiceable quantity is what stands received and not yet invoiced, both computed from posted history; item amounts stand net of tax, and the gross amount must reconcile with the net total plus the tax the standing tax codes calculate at their rates, or posting refuses naming the difference. A price variance against the order price posts to the price-difference determination rather than refusing. The journal clears GR/IR at the expected amount and credits the supplier reconciliation account at the gross, the partner standing on the line; payment terms default from the supplier company data and compute the due date. A duplicate supplier reference refuses, naming the standing document, and a retried submission returns the standing document. A posted invoice is never edited: Cancel posts a linked cancellation document with a mirrored journal, judging its own posting date.', 'TIER_1_BUILT', '/purchasing/invoice-verification', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.342301+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('045d688d-12c0-4968-ab1d-0613a0ceb9c1', 'PROC.INV.PARK', NULL, 'Park supplier invoice', 'TRANSACTION', 'PROC', 'Park a supplier invoice against one purchase order. The park keeps the header and the lines for a later post. It does not post a journal, it does not write a supplier invoice, and it does not consume the purchase order or the goods receipt. A quantity above the invoiceable quantity is shown and is not a refusal. A missing receipt is shown and is not a refusal. The tax is the standing tax code, calculated and not entered. The supplier, the company and the currency are the order. Payment terms are the supplier company data. A check writes nothing, including the number. A credit memo, a subsequent debit, a subsequent credit, an approval, a status and a deletion are refused by name. Invoice verification posts. This capability does not grant that post.', 'TIER_1_BUILT', '/purchasing/parked-invoice', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.346387+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('b5aef1e4-66a7-4378-a076-355f59686736', 'PROC.INV.OVERVIEW', NULL, 'Invoice overview', 'TRANSACTION', 'PROC', 'List the logistics invoices that stand. A parked invoice is a parked row and has no accounting document. A posted invoice is a supplier invoice, and a cancelled invoice stays cancelled. The cancellation document stands posted and names the invoice it cancels. A credit memo is a category, not a reversal. The fiscal year is the year stored on the invoice. A company-currency amount is the journal line stored amount, or it is absent. A draft, a payment block, a layout, an export, an invoice without an order, and a company or purchasing authorisation object are refused by name. Viewing writes nothing. This capability does not post, release, or clear.', 'TIER_1_BUILT', '/purchasing/invoice-overview', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.349092+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('7c256a21-a4a0-4194-af9a-2f133dd9e69b', 'PROC.INV.BLOCK', NULL, 'Place invoice payment hold', 'TRANSACTION', 'PROC', 'Place a manual payment hold on one posted unpaid supplier invoice. The payable stays the supplier line of the invoice journal. The payment run reads the same hold and leaves that line out. A check writes nothing. A price block and a quantity block are refused by name, because invoice verification does not generate them and no tolerance stands. A parked invoice, a paid item, and an item in a payment proposal are refused. This capability does not post, clear, or release.', 'TIER_1_BUILT', '/purchasing/blocked-invoice', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.351571+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('89a9c5c3-795e-4faa-a102-c4dc683ab66d', 'PROC.INV.BLOCK.RELEASE', NULL, 'Release blocked invoices', 'TRANSACTION', 'PROC', 'Release a manual payment hold on a posted unpaid supplier invoice. The list shows the hold, its source, and whether the payable is open, in a proposal, or paid. A check writes nothing. A release clears that hold and appends an event naming who released it, when, and why. It does not post, reverse, clear, or change the invoice amount or the journal. A closed period does not refuse a release that posts nothing. A price block, a quantity block, a quality block, an approval, a batch, and a payment run are refused by name. One reason does not clear another, and the only reason that stands is manual. The payment run reads the same hold.', 'TIER_1_BUILT', '/purchasing/blocked-invoice', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.352705+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d7fd79e8-bfbb-466a-8dc1-6f0dbd922ebf', 'PROC.GRIR.MAINTAIN', NULL, 'Maintain GR/IR clearing', 'TRANSACTION', 'PROC', 'List the posted GR/IR difference on a purchase-order item. The amount is the receipt credit less the invoice expected debit, less a clearing that still stands. A price variance that invoice verification already posted to price difference is not a residual. A check writes nothing. A delivery cost, consignment, a service item, and an account assignment are refused by name. This capability does not post.', 'TIER_1_BUILT', '/purchasing/grir-clearing', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.354885+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('b80832a3-7d2f-418a-a7fd-470217176113', 'PROC.GRIR.MAINTAIN.POST', NULL, 'Post GR/IR clearing', 'TRANSACTION', 'PROC', 'Clear one posted GR/IR residual through the canonical journal. The offset is the configured price-difference account. A missing account is a refusal, not a guessed account. The posting does not create a material document and does not change stock. A further receipt or invoice that can still match the difference is not cleared automatically. A closed financial period and a closed material period refuse the posting. The same request returns the standing document. A stale proposal is refused.', 'TIER_1_BUILT', '/purchasing/grir-clearing', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.357511+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('232f0e46-f8b0-4f4e-9de1-f94bd3eb902c', 'PROC.GRIR.MAINTAIN.REVERSE', NULL, 'Reverse GR/IR clearing', 'TRANSACTION', 'PROC', 'Reverse a GR/IR clearing by a compensating journal. The original document stays. The residual is calculated again from the posted history. A closed period refuses the reversal date. This capability does not delete a journal and does not move stock.', 'TIER_1_BUILT', '/purchasing/grir-clearing', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.358717+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('669c7cf9-272d-461e-8968-bb7ea9551a6b', 'PROC.INFO.RECORD.MAINTAIN', NULL, 'Purchasing info record', 'TRANSACTION', 'PROC', 'A purchasing info record is a default for one supplier and one material: one standard category, one validity-dated net price, a planned delivery time and a minimum quantity. Check writes nothing, including the number. A change, a deactivation and a reactivation are the same record, not another transaction. A material-group record, subcontracting, consignment and pipeline are refused by name. The order stores the reference and keeps the price it used; this capability does not grant the purchase order, and it posts no goods movement and no journal.', 'TIER_1_BUILT', '/purchasing/info-record', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.360016+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('a3a1728e-442e-4d74-8d4a-62a7bdc175fd', 'PROC.SOURCE.LIST.MAINTAIN', NULL, 'Purchasing source list', 'TRANSACTION', 'PROC', 'A purchasing source list names who may supply one material at one plant. Entries are validity-dated. Fixed and blocked are marks. The requirement flag is explicit and defaults off. Check writes nothing, including the number. A change, a deactivation and a reactivation are the same entry, not another transaction. An agreement, a quota, a ranking and a price are refused by name. The order stores the source it used and is not rewritten later; this capability does not grant the purchase order, and it posts no goods movement and no journal.', 'TIER_1_BUILT', '/purchasing/source-list', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.363781+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('32f41fea-5376-4371-b9ea-6dee20d2c553', 'PROC.QUOTA.MAINTAIN', NULL, 'Purchasing quota arrangement', 'TRANSACTION', 'PROC', 'A purchasing quota arrangement weights who may supply one material at one plant. Dates are inclusive. An item is an external supplier. A quota is a positive integer and need not sum to 100. The base quantity is scale 3 and defaults to zero. Item numbers start at 001. The rating is (allocated + base) / quota. Check writes nothing, including the number. The screen allocates nothing. A change, a deactivation and a reactivation are the same arrangement. An internal plant, a lot size, a unit, a percentage, a ranking, a price and an allocated quantity are refused by name. Saving an order adds the order quantity to a vendor''s quota base when that vendor stands in the quota. A vendor who does not stand is warned, and the order is saved. This capability does not post a goods movement or a journal.', 'TIER_1_BUILT', '/purchasing/quota-arrangement', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.366137+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('64ccd880-f1e5-4385-bc03-1eac4610986c', 'PROC.RFQ.CREATE', NULL, 'Request for quotation', 'TRANSACTION', 'PROC', 'A request for quotation asks. A change rewrites one request''s copy. A header change is the event''s and is named as such. One event groups the requirement. Each supplier receives a separate request, and that request copies the lines. A collective number is a label, not the key. The currency is the company''s. Check writes nothing, including either number. The screen creates nothing else. A price, a status, a delivery channel, a quotation and an award are refused by name. A line may name a requisition item. That reference is copied and the requisition quantity is not consumed. This capability does not grant the purchase order, and it posts no goods movement and no journal.', 'TIER_1_BUILT', '/purchasing/rfq', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.368514+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('52f92b9c-baa4-467a-b30c-54202c6996d8', 'PROC.RFQ.QUOTATION', NULL, 'Quotation', 'TRANSACTION', 'PROC', 'A quotation prices one standing request. The supplier and the currency are read from that request and are not stored again. A zero price is an offer. The price per one unit is shown on a check and is not stored. Check writes nothing, including the number. The screen does not compare, and it does not award or buy. A status, a rejection, an award, a condition, a company code, a revision and a request key are refused by name. This capability does not grant the purchase order, and it posts no goods movement and no journal.', 'TIER_1_BUILT', '/purchasing/quotation', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.371626+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('b9f2eb0c-93d7-4e39-bad6-b17e66841b35', 'PROC.RFQ.QUOTATION.DISPLAY', NULL, 'Display quotation', 'TRANSACTION', 'PROC', 'Display a standing quotation. The quotation number is the key. A request number resolves that quotation and is not the key. The supplier and the currency are read from the request. The price per one unit is calculated and is not stored. A day after the deadline does not hide the quotation. Nothing is written. There is no status, no revision stack, no condition, no award and no comparison. This capability does not grant maintenance or the purchase order, and it posts no goods movement and no journal.', 'TIER_1_BUILT', '/purchasing/quotation-display', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.374091+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('e6f79212-9644-446d-8913-4caf552717b5', 'PROC.RFQ.COMPARISON', NULL, 'Compare quotations', 'TRANSACTION', 'PROC', 'Compare the quotations that stand for one event. The event number is the key. A collective number is a label: it resolves one event and is refused when it names more than one. The currency is the company''s, and it is not converted. The compared price is the net price per one unit of the unit that was asked, calculated and not stored. Equal prices share a rank. A missing offer is not ranked. A quantity mismatch is shown and is not a disqualification. A day after the deadline does not hide a standing quotation. Nothing is written, including a rank. A status, a revision, a condition, a discount, freight, a tax, an exchange rate, an award and an order are refused by name. This capability does not grant maintenance or the purchase order, and it posts no goods movement and no journal.', 'TIER_1_BUILT', '/purchasing/quotation-comparison', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.376623+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('af719725-b341-4e61-bda3-ee25edc2f450', 'PROC.PO.CREATE', NULL, 'Create purchase order', 'TRANSACTION', 'PROC', 'Create and change purchase orders: a header (supplier judged through its purchasing-organization data, purchasing organization and group, company code, currency defaulted from the supplier or company — never hard-coded) with items, schedule lines and cost-centre assignments. Display is a separate route. The item net value is the stated baseline, quantity times net price over price unit; condition-based pricing is a later round. An item may convert a requisition item, the ordered total across standing orders never exceeding the requisitioned quantity. Every item plant belongs to the header company; schedule lines reconcile to the order quantity. Saving an order posts nothing, so the FI and material period gates bind the follow-on documents, never this screen. Deletion is an item mark; the release strategy that will move the header release status is a later round, recorded as due before goods receipt. A batch is stored only when that batch already stands. This screen does not create a batch.', 'TIER_1_BUILT', '/purchasing/orders', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.378805+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('c9c04cb5-284e-4193-bcdf-74c77d0d2cc6', 'PROC.PO.DISPLAY', NULL, 'Display purchase order', 'TRANSACTION', 'PROC', 'Display a standing purchase order. The purchase order number is the key. The supplier name is the current master name. Received and invoiced quantities follow the purchase-order list. A reversal and a cancellation stay in the history. A check is not required, because opening the document writes nothing. There is no stored header status, no revision stack, no pricing condition, no exchange rate, and no attachment. This capability does not grant create, change, or release, and it posts no goods movement and no journal. Batch is shown when the item stores one. This screen has no batch input.', 'TIER_1_BUILT', '/purchasing/purchase-order-display', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.384637+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('aaabdc20-3e55-4c07-bca4-e54793a35f67', 'PROC.VENDOR.EVALUATE', NULL, 'Maintain vendor evaluation', 'TRANSACTION', 'PROC', 'Maintain a vendor evaluation for one supplier in one purchasing organisation and a date period. The as-of date is the period end. Price and delivery are calculated from posted invoices and receipts and are not stored. Quality and service are manual scores. A missing score is not zero. The overall score is derived when every criterion has a score. A check writes nothing. A closed financial period is not read. This capability posts no goods movement and no journal.', 'TIER_1_BUILT', '/purchasing/vendor-evaluation', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.386602+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('af18d38b-1c9b-419b-b0f0-636713e05eee', 'INV.STOCK.VIEW', NULL, 'Stock overview', 'TRANSACTION', 'INV', 'Stock overview for one required material, read-only: a three-level tree of plant, storage location and stock type, where every parent total is folded from the child rows it displays so a parent can never disagree with them. Zero-stock nodes are suppressed at every level unless the display flag asks for them; the expansion level chooses whether the tree opens to plants only or down to storage locations. The tree is quantitative — value belongs to the warehouse stock list, which each node reaches along with the material document list and the posting-date rollforward, all filtered to that node and the whole recorded ledger window. A named batch is shown under the stock type and filters the tree. It does not create a batch. In-transit stock is deferred by name (no transit movement type), and the one-character special stock indicator is refused in favour of a named stock type, which is what the third level shows.', 'TIER_1_BUILT', '/inventory/stock-overview', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.389067+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('232fcc9f-4141-4bf2-853a-9e71332f6eeb', 'INV.RETURN.POST', 'material_document_line', 'Return delivery to a vendor', 'TRANSACTION', 'INV', 'Return goods received against a purchase order, read against a posted goods receipt named by number and fiscal year: every item shows what was received, what has already gone back and what may still be returned, and only the return quantity is entered. The receipt is not cancelled; it stands, and the received position on the order falls by what went back. The return posts its own material document through the canonical engine and numbering service, carrying the original document, its year and its line so that a return and a cancellation stay distinguishable. The movement is configuration — RETURN_TO_VENDOR, direction ISSUE, counter RETURN_TO_VENDOR_REV — and a movement that adds stock cannot post as a return. Stock is judged on the exact material, plant, storage location, stock type and the receipt line''s batch after the locks are taken and the returnable quantity re-read. Accounting mirrors the receipt: inventory credited, GR/IR debited, price difference where order price and stock value disagree, reopening the clearing position the later credit memo closes, with no vendor liability touched and no credit memo created. The batch is the receipt line''s batch. It is not typed and it is not changed. A typed batch that is not that batch is refused. Serial numbers, split valuation, special stock and outbound delivery are refused by name.', 'TIER_1_BUILT', '/inventory/return-delivery', 'B', NULL, true, 'SCR145_MIGRATION', '2026-11-10 08:54:11.241943+00', 'SEED', '2026-11-10 08:54:14.393895+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('81add475-f4cd-4bcb-b8d2-420c6030c383', 'INV.STOCK.UOM', 'material_uom_conversion', 'Units of measure per material', 'TRANSACTION', 'INV', 'Maintain the alternative units a material accepts, read-only except for that one act: each row states one alternative unit with an integer numerator and denominator against the base unit, so a posting entered in it converts by exact rational arithmetic rounded to the base unit decimals and the ledger records the base quantity, while entry quantity and entry unit are stored as entered. A unit with no row is refused by name, naming the missing conversion and the capability that maintains it; a conversion from the base unit to itself is refused, and a unit the catalogue does not know is refused before it can become a conversion.', 'TIER_1_BUILT', '/inventory/uom-conversion', 'B', NULL, true, 'SCR144_MIGRATION', '2026-11-10 08:54:11.231999+00', 'SEED', '2026-11-10 08:54:14.395941+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('93d04b8b-4c5d-45b9-9e68-8bda11762115', 'INV.STOCK.WAREHOUSE', NULL, 'Warehouse stocks on hand', 'TRANSACTION', 'INV', 'List of warehouse stocks on hand, read-only: the current stock master by material, plant and storage location, pivoted on stock type into unrestricted-use, quality inspection, blocked and a fourth special-or-other column so the totals are never short. Each line is valued at the plant valuation price selected by the material price control, honouring the price unit; a material with no valuation record shows an unknown value and is warned by name rather than a zero, and a valuation in another currency is carried as is with no translation applied at report time. The scope of list is required (ALV grid or standard list); material, plant and storage location ranges are optional; zero-stock lines are suppressed unless asked for; the valuation price display defaults on. Each row drills into the material document list and the stocks-on-posting-date rollforward over the whole recorded ledger window. Valuation type is deferred by name. A named batch splits the row and filters the list. The one-character special stock indicator is refused in favour of a named stock type.', 'TIER_1_BUILT', '/inventory/warehouse-stocks', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.399355+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('ffd6a9d5-3753-458a-890d-04b9b2aa25c6', 'INV.STOCK.POSTINGDATE', NULL, 'Stocks on posting date', 'TRANSACTION', 'INV', 'Stocks as of a posting date, read-only: a rollforward of opening, receipts, issues and closing quantity and value per material, plant, storage location and stock type across a required reporting window, with the material and plant ranges also required so the evaluation is always bounded. The figures are read from the immutable ledger rather than derived by unwinding the current snapshot: opening is what was posted before the window, receipts and issues what posted inside it, closing their sum, and a reversed document contributes nothing. Where the window reaches the latest posting date, the closing quantity is compared with the stock master and any difference stands as a warning naming both figures — a control, never an adjustment. The stock type defaults to unrestricted and zero-stock lines are suppressed unless asked for. Each row drills into the material document list filtered to that row and window. Valuation type, Scope-of-List variants, stock ageing and exporting are deferred by name. A named batch splits the rollforward and filters it.', 'TIER_1_BUILT', '/inventory/stock-posting-date', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.401618+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('cf253bfb-f8e7-427c-8701-505265bbb25a', 'INV.GI.POST', NULL, 'Post goods issue', 'TRANSACTION', 'INV', 'A goods issue posted as a material document: 201 to a cost centre or 551 scrapping, valued at the material’s own price in the plant, with stock falling at the issuing location, the valuation falling by what was issued, and the journal crediting inventory and debiting consumption (carrying the cost centre on the line) or scrapping. A line may name a reservation and its item, and the withdrawal runs in the same transaction so the demand in the stock/requirements list falls with the stock. The material period and the accounting posting period both judge the date. 261 is refused by name (no order master); reversal is MBST’s, with 202 and 552 in the catalogue. A batch-managed issue uses the batch already entered and does not create a batch.', 'TIER_1_BUILT', '/inventory/goods-issue', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.403807+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('4b96777b-6591-4b4f-ae76-bcea9ae06540', 'INV.MATERIALDOC.RECEIVEPRINT', NULL, 'Material document output', 'TRANSACTION', 'INV', 'Output determination and dispatch for material documents in the NAST shape: a goods receipt slip (WE01) for a document that receipts only, a goods issue slip (WA01) for one that issues only, determined as the document posts and filled by a run for documents that predate the capability. The queue is read by status, output type, medium and dispatch time over document, year, plant and posting-date ranges; a dispatch renders the slip from the document as posted, counts the send and stamps the time; an EMAIL with no recipient fails and records why, and succeeds once a recipient stands. Named states carry SAP’s digits as aliases; FAX and EDI are refused by name, spool and transport are deferred by name.', 'TIER_1_BUILT', '/inventory/material-document-output', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.406373+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('b2a82eb9-f79a-4056-9c53-aec9b19e07e9', 'INV.DISPLAY', NULL, 'Display material document', 'TRANSACTION', 'INV', 'One material document exactly as posted, read-only: a required document number with the fiscal year as a cross-check and an optional item that narrows the grid, the header with its poster and entry time, every line with its movement type and direction, material and description, plant and storage location, stock type, the batch stored on the line, entry and base quantities, unit price, value and currency, purchase order and item, and the reversal pair. The company code is derived from the plants, never typed. A display applies no posting-period check, so a document whose period has closed still shows as it stood; F4 search help, the accounting-document drill and the reservation reference are deferred by name.', 'TIER_1_BUILT', '/inventory/material-documents', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.408851+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('62d19390-5028-4e76-9f1a-fed506770819', 'INV.MATERIALDOC.LIST', NULL, 'Material document list', 'TRANSACTION', 'INV', 'Material documents as a list, read-only over the ledger: ranges on material, plant, storage location, movement type and purchase order, a required posting-date range, optional document dates, a stock type and a user name, with a maximum hit count carrying the standing truncation marker. The posting-date range is required because a list over an unbounded ledger is a scan of history rather than a question. Movement types are the canon keys with their direction, never SAP numbers; storage locations, plants and materials are judged against their masters and refuse by name. Every line shows the document and year, item, movement type and direction, material and its description, entry and base quantities with units, unit price with price unit, value and currency, plant, storage location, stock type, the batch stored on the line, posting and document dates, header text, the journal document posted, the document status, the purchase order and item cited so a receipt is auditable against its order, and the creator, drilling into the material document display. A named batch filters those lines. History is never hidden: a reversed document is listed with that status and its reversal stands as a document of its own. Project and sales-order special stock, Scope-of-List variants, serial selection and exporting are deferred by name. A sales order, a delivery, a billing document, and a scheduling agreement are refused by name.', 'TIER_1_BUILT', '/inventory/material-document-list', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.41131+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('bde5a08b-23f5-4694-aee6-c49a2ac0f36a', 'INV.PHYINV.CREATE', NULL, 'Physical inventory', 'TRANSACTION', 'INV', 'Create a physical inventory document: the plant, an optional storage location, the planned count date and the materials to be counted. A count moves nothing — the ledger records what has moved, and a count records what has not moved yet — so creating one leaves stock, valuation and journals untouched. The company code and the fiscal year are derived from the plant and the count date; the count date must fall in an open material period. With the posting block set, every goods receipt, goods issue, transfer posting and production receipt of those materials in that plant is refused, naming the blocking document, until the count is done or the document is cancelled; cancellation is its own capability (MI02) because a block that cannot be lifted is a trap rather than a control. Count entry is MI04 (INV.PHYINV.COUNT), on its own screen: the document freezes the book quantity it will be counted against, and a count records what a person saw without posting anything. The difference list is MI20 (INV.PHYINV.DIFF.LIST), on its own screen: it reads the stored difference and posts nothing. Difference posting is its own screen. A named batch that already stands is counted with the material; the count does not create the batch. Special stock and cycle counting remain deferred (SCR-142).', 'TIER_1_BUILT', '/inventory/physical-inventory', 'A', NULL, true, 'SEED', '2026-11-10 08:54:14.413871+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('cbb31c0c-d913-4183-a500-31455df8c2ca', 'INV.PHYINV.COUNT', NULL, 'Enter physical inventory count', 'TRANSACTION', 'INV', 'Count entry against a physical inventory document created in MI01, read by document number and fiscal year. Each item names the material, its stock type and the book quantity the document froze when it was created, so a difference is measured against the quantity the count was raised for rather than against stock that has moved since. A counted quantity is entered in any unit the material converts from and normalized to the base unit at the material’s own ratio; a zero is recorded explicitly as its own fact, distinct from an item nobody has counted; both may not stand on one line. Saving one or many items is one transaction with per-item versions, so a screen that has gone stale is refused with the version that stands rather than overwriting a colleague, and one bad line takes the whole submission with it. The header follows all its items — CREATED, PARTIALLY_COUNTED, COUNTED — and a correction before the differences are posted keeps its history in the change log: quantity, unit, zero flag, date, counter and the reason. Clearing a count returns the item to uncounted without erasing what it said. A count posts nothing: no material document, no journal, no stock, and the difference it computes is held for the difference review and the difference posting.', 'TIER_1_BUILT', '/inventory/physical-inventory-count', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.417353+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('952d603d-20b6-48a3-b174-0332f0c78b7c', 'INV.PHYINV.DIFF.LIST', NULL, 'Physical inventory differences', 'TRANSACTION', 'INV', 'Read-only list of physical inventory differences for a required plant and fiscal year. Each row is a counted item: the book quantity the document froze, the counted base quantity, and the stored difference, labelled shortage, surplus, or no difference. An uncounted item is absent unless asked for, and is never shown as zero. A monetary difference is shown only where a plant valuation record stands — standard or moving-average price, divided by the price unit, rounded to the currency decimals — and is labelled as the price standing now, not as the amount a later posting will take. An unvalued material keeps its quantity difference and is named, never zeroed. A minimum value filters in one named currency and does not silently drop an unvalued row. A closed material period may be noted against the count date and never hides the row. Opening the list writes nothing. The list may link to difference posting and to recount; those links are navigation, and a request that names posting or recount on this list is still refused.', 'TIER_1_BUILT', '/inventory/physical-inventory-differences', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.419716+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('1c5cd853-3561-45d7-902f-9260e848f6ea', 'INV.PHYINV.DIFF.POST', NULL, 'Post inventory differences', 'TRANSACTION', 'INV', 'Post the differences a physical inventory count recorded. The person selects the items; each selected item posts its whole remaining difference or the batch does not post. The movement is the configured difference movement for the direction, not a typed number. The amount is the plant valuation at the currency decimals, not the estimate on the difference list. A movement that does not value writes quantity only and no journal. A missing valuation, a missing account, a closed material period and a closed financial period are refused, and nothing is left behind. The same request key with the same payload returns the standing document; a different payload on that key is refused. Reversal is the canonical material-document reversal and requires its own capability. A fraction of one item, a monetary threshold, serial, special stock, split valuation, the material ledger and recount are refused by name. The count item batch is posted. A batch is not created.', 'TIER_1_BUILT', '/inventory/physical-inventory-posting', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.422041+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('41773a4e-3cc3-47d4-b588-4e8f7b377d89', 'INV.PHYINV.RECOUNT', NULL, 'Recount physical inventory', 'TRANSACTION', 'INV', 'A recount is a new physical inventory document for the items the person selects. The original count stays and is never added. The new document freezes the stock standing now, for the selected stock type only. An active link makes the original ineligible for difference posting. A still-posted item is refused; this transaction does not reverse. The planned date is not a posting date. The recount quantity is entered on the new document through count entry. A recommending threshold and a typed batch are refused by name. The batch stored on the item is copied. Special stock is refused by name.', 'TIER_1_BUILT', '/inventory/physical-inventory-recount', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.424611+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('ea0d973a-6e4a-47a0-b99a-e5ca4988e5d2', 'INV.MIGO.POST', NULL, 'Goods movement', 'TRANSACTION', 'INV', 'One screen where an action (goods receipt, return delivery, cancellation, transfer posting, goods issue) and a reference document type (purchase order, reservation, material document, order) select the movement — SAP’s own shape, in one place rather than a page per movement. Every cell of the matrix resolves to exactly one answer: posted from this screen (A07 + R08, the 261 component issue against a released production order), delivered by another capability with a link to it, or refused by name with the capability that would deliver it. The 261 consumes components from stock, credits inventory and debits production consumption on a P&L account — not work in progress, because nothing settles an order yet; an over-issue is refused naming what the component still requires; the order stands on the material-document line and on the journal line, and the document drills to MB03 and its journal to FB03. Return delivery, goods receipt from an order, reservations as a receipt reference, GR blocked stock and a tolerance master are deferred or refused by name (SCR-139).', 'TIER_1_BUILT', '/inventory/migo', 'A', NULL, true, 'SEED', '2026-11-10 08:54:14.426734+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('f4d6f242-03e7-452c-8518-ee7638d34f27', 'CFG.PROD.ORDERPARAM.DEFINE', NULL, 'Order type-dependent parameters', 'CONFIG_ACTIVITY', 'PROD', 'Order type-dependent parameters. OPL8 is a search alias. The key is a standing plant and a standing production order type. The category is the production-order category only. A task list type is optional and must already stand. Naming it does not select a routing. Production version selection stores the indicator only. The documented values are 0, automatic selection, and 1, manual selection. Blank is the initial value, not a documented selection method. Saving a value does not select a version. Costing, settlement, release, status profile, routing selection, a BOM application, a selection ID, scheduling, and checking control are not stored. Creating the record does not create an order and does not change numbering. CO01 and conversion read the stored production version selection for the same plant and order type. Blank is not treated as 0 or 1. MRP does not read it.', 'TIER_2_CONFIGURED', '/config/order-type-parameters', 'B', NULL, true, 'MIGRATION_9179', '2026-11-10 08:54:11.83242+00', 'SEED', '2026-11-10 08:54:14.435531+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('faf6a28b-437d-4065-93fe-b9c48b650c39', 'PROD.BOM.CREATE', 'material_bom', 'Create material BOM', 'TRANSACTION', 'PROD', 'Create a plant-specific material BOM. CS01 is a search alias. Usage, status, and item category are tenant data. No usage 1 is delivered. A change number is refused. Validity is the from and to dates. Saving does not explode the BOM or rewrite a production order.', 'TIER_1_BUILT', '/production/boms', 'B', NULL, true, 'MIGRATION_9159', '2026-11-10 08:54:11.684104+00', 'SEED', '2026-11-10 08:54:14.4372+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('fa7914d4-4ddd-49ad-be65-74a745bac042', 'PROD.CONFIRM.ORDER', NULL, 'Enter order confirmation', 'TRANSACTION', 'PROD', 'Confirm a released production order at header level. CO15 is a search alias. One confirmation number is drawn. Each operation whose control key allows confirmation, and which is not already finally confirmed, receives that quantity as an effect. A separate time-ticket number is not created. An operation that requires an activity is not given a standard value. Automatic final confirmation is refused because no confirmation profile is stored. A check writes nothing. The order status stays created or released. Backflush and automatic goods receipt are not configured. CO11N, CO13, and CO14 are not this screen.', 'TIER_1_BUILT', '/production/order-confirmation', 'B', NULL, true, 'MIGRATION_9170', '2026-11-10 08:54:11.784519+00', 'SEED', '2026-11-10 08:54:14.457126+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('2a219e6b-52d4-4c90-9653-5316c1a479a6', 'PROD.ORDER.CREATE', NULL, 'Create production order', 'TRANSACTION', 'PROD', 'Create a production order. CO01 is a search alias. The screen selects a production version for the material, plant, finish date, and quantity, then stores the component snapshot from that bill of material. The selected version, BOM usage, and BOM alternative are stored on the order. The BOM item and source material are stored on each component. A typed component list or a typed BOM alternative is not accepted on this screen. Planned-order conversion may still pass a snapshot it has already resolved. A later BOM or version change does not rewrite a saved snapshot. The company code is derived from the plant and never stored. Creating an order posts nothing and moves no stock. Release is a separate act. Reservations, goods movements, journals, capacity, ATP, costing, settlement, engineering change, and collective orders are not created here.', 'TIER_1_BUILT', '/production/orders', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.460516+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('f6396c69-0e43-4514-980d-becf813de9ca', 'PROD.MRP.RUN', NULL, 'Total planning', 'TRANSACTION', 'PROD', 'Total planning for a plant. Net change reads the planning file. Net change in the horizon needs a horizon and does not clear a change that falls outside it. Regenerative planning needs its own capability and an explicit confirmation. A buy shortage becomes a purchase requisition through the requisition service. A make shortage becomes a planned order, which is not a production order. This run does not explode a bill of material. Dependent demand is the open reservation. An MRP area, a scheduling-agreement schedule line, a background run, parallel processing, delete-and-recreate, a factory calendar, a company code as a key, and a financial period are refused by name. A check writes nothing. A repeated request returns the same run. The run posts nothing.', 'TIER_1_BUILT', '/production/mrp-run', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.463056+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('5dedcdf3-a864-4fd8-a657-dd9cb7f448ee', 'PROD.PLANNEDORDER.DISPLAY', 'planned_order', 'Display planned order', 'TRANSACTION', 'PROD', 'Display a planned order. MD13 is a search alias. The number is the key. Quantity, unit, start, finish, and firming are shown as stored. An MRP area, an order type, a special procurement key, an opening date, a production version, a BOM, a routing, a scheduler, a storage location, a sales order, a WBS element, and a deletion flag are not stored. Conversion is not inferred. Display writes nothing and takes no change lock.', 'TIER_1_BUILT', '/production/planned-order-display', 'B', NULL, true, 'MIGRATION_9163', '2026-11-10 08:54:11.758616+00', 'SEED', '2026-11-10 08:54:14.469529+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('e28cb7f5-47b7-4ac4-b7d4-4b54e84a0eec', 'PROD.MRP.STOCKREQ', NULL, 'Stock/requirements list', 'TRANSACTION', 'PROD', 'Stock/requirements list, read-only and computed live: one material in one required plant, with stock on hand, the open purchase requisitions net of what orders already cover, the open purchase orders net of what has been delivered, and the safety stock as an opening requirement, folded into a single chronological list whose running projected balance is recomputed on every execution. MRP availability counts unrestricted-use and quality-inspection stock only; blocked stock is excluded and named in a warning. A receipt precedes a requirement on the same date. The past-due display can be switched off, and the hidden rows still move the balance. The list splits daily or into Monday-started weeks, and marks shortage, safety breach and past due. A planned order that has not been converted is a receipt. A created or released production order is a receipt for the open quantity. Sales orders and excess-stock alerts remain deferred; reservations are requirements; the MRP area, the one-character special stock indicator and a simulation version are refused in favour of the plant, a named stock type and the live list; requisition-to-order conversion is a posting action and is not wired to this report.', 'TIER_1_BUILT', '/production/stock-requirements', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.477754+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('f80af439-c452-468d-8175-5f68fa1e85d2', 'PROC.PO.ACCOUNTASSIGN', NULL, 'Purchase orders by account assignment', 'TRANSACTION', 'PROC', 'Purchase orders by account assignment, read-only: every assignment line of every selected order with the assigned object, its G/L account, its distribution percentage and the share of the item net value it carries, rounded at the line and grouped by assigned object so the cost-centre totals add back to the items. The scope of selection narrows to items still to be delivered, still to be invoiced or completed, using the same delivered and invoiced quantities the purchase order list derives. Asset, WBS and internal-order assignment categories are refused by name: this canon assigns purchase order items to cost centres only. Each row drills to the order and to its cost centre.', 'TIER_1_BUILT', '/purchasing/orders-by-account-assignment', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.480105+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('20c41cfe-fe55-4f22-83f5-d2d7af2feb64', 'PROC.PO.LIST', NULL, 'Purchase order list display', 'TRANSACTION', 'PROC', 'Purchase orders as a list, read-only: one engine behind four perspectives — by vendor (the primary), by material, by purchase order and by material group — each fixing the primary sort while every other selector stays available. Selection ranges on vendor, purchasing organisation, purchasing group, plant, material, material group and purchase order number, with document dates and a maximum hit count carrying the standing truncation marker; every range endpoint is judged against its master and refuses by name. The scope of selection is derived from posted history, never from a status column: delivered is the signed base quantity of the material-document lines citing the order item, where a receipt adds, a reversal subtracts and a reversed document contributes nothing; invoiced is the invoiced quantity of supplier-invoice items whose invoice stands posted. All items, still to be delivered, still to be invoiced and completed follow from those two quantities, and an item marked for deletion stands under all items only, never as outstanding work. Each row carries the vendor name, organisation, group, company, dates, material, plant, quantities, net price with its price unit, net value, earliest schedule delivery date, release status, the requisition it converts with that requisition requested quantity, delivered, invoiced and both open quantities, and drills to the purchase order display. The Scope-of-List presentation variants, the order-history line-item drill, release-strategy detail and exporting are deferred by name.', 'TIER_1_BUILT', '/purchasing/purchase-order-list', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.482376+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('da7a77d8-bd6e-4bb6-8aaa-1aa58e8db68e', 'PROC.PR.CREATE', NULL, 'Create purchase requisition', 'TRANSACTION', 'PROC', 'Create, change and display purchase requisitions: an item-level purchasing document with no header record, its number drawn from the PURCHREQ range. Each item names a material extended to its plant or a short text, a quantity and unit, a required delivery date, plant, purchasing group and an estimated price read with its price unit and currency; cost-centre items carry assignment rows whose percentages total a hundred, judged against the cost centre standing valid and a P&L account in the company chart. Saving a requisition posts nothing, so the FI and material posting periods are never judged here — they bind the follow-on documents. Deletion is an item mark, never physical deletion; release, conversion to orders and the asset, project and order assignment categories belong to later rounds.', 'TIER_1_BUILT', '/purchasing/requisitions', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.487769+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('a11b8211-e574-4259-97fa-1cf479c3dc11', 'PROC.REQ.LIST', NULL, 'Purchase requisitions: list display', 'TRANSACTION', 'PROC', 'Purchase requisitions as a list, read-only over the standing requisition items: ranges on purchasing group, plant, material and purchasing organisation, an exact requisitioner, requisition-date from and to, account-assignment category, and a Display closed toggle that stands off by default. The purchasing organisation is never stored on the item — it is derived through the plant assignment, so an organisation filter matches when any of the plant assignments falls in the range and a row shows every organisation its plant maps to; a plant mapped to none still stands, with an empty organisation. Conversion is derived from the live purchase-order items citing the requisition item: ordered quantity excludes lines marked for deletion, status is OPEN at zero, PARTIAL above zero and below the requisition quantity, CONVERTED at or above it, and the open quantity never shows negative demand. Closed means converted or marked for deletion. Every supplied range endpoint is judged against its master and refuses by name rather than answering an empty list that reads as no demand; maximum hits with the standing truncation marker. Each row drills down to the requisition display. The tracking-number filter, display variants beyond this grid, release-status display and exporting are deferred by name.', 'TIER_1_BUILT', '/purchasing/requisition-list', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.494623+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('23ff0a31-def8-4af3-997f-1c045d15f0a3', 'PROC.SUPPLIER.PURCHASING.MAINTAIN', NULL, 'Supplier purchasing defaults', 'TRANSACTION', 'PROC', 'Organisation-scoped buying defaults, not purchase order execution.', 'TIER_1_BUILT', '/foundation/partners?view=SUPPLIER_PURCHASING', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.497132+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('c572b418-648f-4b00-8e41-ab64e721b587', 'FIN.SUPPLIER.COMPANY.MAINTAIN', NULL, 'Supplier company accounting', 'TRANSACTION', 'FIN', 'Company-scoped reconciliation and payment terms; no invoice or payment posting.', 'TIER_1_BUILT', '/foundation/partners?view=SUPPLIER_COMPANY', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.498549+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('959d64e4-5b16-4738-9ee1-539a1b8bb17b', 'FND.PARTNER.CREATE', NULL, 'Create business partner', 'TRANSACTION', 'FND', 'General identity and stable supplier/customer roles; organisation segments are pending.', 'TIER_1_BUILT', '/foundation/partners?new=1', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.499843+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('b60bb38f-6890-4b68-86d2-5f7e4d3c2371', 'FND.PARTNER.DISPLAY', NULL, 'Business partner list', 'TRANSACTION', 'FND', 'Search general partner data and review change evidence.', 'TIER_1_BUILT', '/foundation/partners', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.505148+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('37f830c4-f210-4f78-b8cd-4d17a93c419b', 'FND.PARTNER.MAINTAIN', NULL, 'Maintain general business partners', 'TRANSACTION', 'FND', 'Role-protected maintenance of general partner data only.', 'TIER_1_BUILT', '/foundation/partners', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.506089+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d868c22f-74e7-409a-995e-642ab725d879', 'CFG.FIN.PAYTERMS.DEFINE', NULL, 'Payment terms', 'CONFIG_ACTIVITY', 'FIN', 'Due-date offsets and exact cash-discount deadlines with audit history.', 'TIER_2_CONFIGURED', '/config/payment-terms', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.507387+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('b708fed4-5e08-428d-a510-fe25015bab47', 'CFG.FIN.CCA.MAINTAIN', NULL, 'Credit control area setup', 'CONFIG_ACTIVITY', 'FIN', 'Create a tenant-scoped credit control area and make its initial assignment to one active, unassigned Company Code. Currency is derived from the Company Code; an existing area’s financial settings and an existing Company Code assignment are never changed by this workflow. Every creation and assignment is audited in the same transaction. This authority is exact-grant-only; broad wildcard role patterns do not grant it.', 'TIER_2_CONFIGURED', '/config/credit-control-areas', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.509688+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('82db73c8-fc24-489a-8e06-f02d51ab3862', 'CFG.FIN.PAYMENTMETHOD.DEFINE', NULL, 'Payment method definitions', 'CONFIG_ACTIVITY', 'FIN', 'Country-specific definitions and their change history; no payment execution or partner assignment.', 'TIER_2_CONFIGURED', '/config/payment-methods', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.510812+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('59853a75-f9c2-4341-ba53-f10147c8232a', 'INV.GR.POST', NULL, 'Post goods receipt', 'TRANSACTION', 'INV', 'Post goods receipts against purchase orders and reverse them: the business action and the reference are separate choices, and the movement type follows from them through the tenant movement catalogue — it is never typed as a code. An order a release strategy claimed must stand fully released. The screen loads the order items with ordered, already received and remaining quantities — the remaining quantity computed from posted movement history, judged against the material-plant overdelivery tolerance. Posting writes the material document, the stock balance, the valuation totals and one balanced journal in a single transaction: a moving-average material values at the order price, a standard-price material at standard with the difference carried separately, and account determination missing refuses, naming the configuration. The material period and the financial period judge on their own rules; a deletion-flagged material is refused on a posting. A posted material document is never edited or deleted — the Reversal action corrects it with a new document, and a retried submission returns the standing document instead of posting twice. A blank batch posts the batch stored on the order when one already stands. A typed batch posts that batch. This posting does not create a batch.', 'TIER_1_BUILT', '/inventory/goods-receipt', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.514309+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('11d1bd9c-fdfc-4d99-96bd-a2c0648d1279', 'INV.RESERVATION.CREATE', NULL, 'Create reservation', 'TRANSACTION', 'INV', 'Reserve material for a future withdrawal against a cost centre (201); the open item is a requirement in the stock/requirements list until it is withdrawn in full or completed.', 'TIER_1_BUILT', '/inventory/reservations', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.516285+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('7d65fd38-ae53-422e-81b1-1249c4bcd457', 'INV.REVERSE', NULL, 'Reverse material document', 'TRANSACTION', 'INV', 'Reverse any material document by its counter movement type, in whole or line by line. The batch stored on the line is shown and is not typed. Stock is taken back from that batch, not from another batch of the same material. Valuation, the journal and the open order quantity all return, and a document is cancelled once.', 'TIER_1_BUILT', '/inventory/reversal', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.51859+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('5247be52-8e4c-42ba-a89e-29057e770751', 'INV.TRANSFER.POST', NULL, 'Post stock transfer', 'TRANSACTION', 'INV', 'Transfer stock: storage location to storage location (311), plant to plant (301) and quality inspection to unrestricted (321), each a two-line material document with its counter movement type for reversal. A named batch moves with the transfer and does not create a batch. The other batch stays.', 'TIER_1_BUILT', '/inventory/transfer-posting', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.520979+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('3abdac73-df3e-480e-956c-67e5c87a7c9c', 'INV.MATERIAL.CREATE', NULL, 'Create material', 'TRANSACTION', 'INV', 'Basic, purchasing, MRP and valuation views. Other views are still pending.', 'TIER_1_BUILT', '/inventory/materials?new=1', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.523758+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('324e9f1f-90bf-4810-8af7-73e9cc52d4bb', 'INV.MATERIAL.FLAGDELETION', NULL, 'Flag material for deletion', 'TRANSACTION', 'INV', 'Flag a material for deletion at client level or for one plant, or cancel the flag: a confirmed act with a mandatory reason and a security-relevant change document per scope. The flag marks its scope as intended for deletion — it is not a posting lock, stops no document, and deletes nothing; the stock standing at the scope is named before confirming, and a client-level flag refuses new plant extensions until cancelled. Archiving and physical deletion are a separate, unbuilt process.', 'TIER_1_BUILT', '/inventory/materials', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.52647+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('63ed943f-9b8b-49b1-9530-0dfdca7e5c94', 'INV.MATERIAL.DISPLAY', NULL, 'Material master list', 'TRANSACTION', 'INV', 'Find a material and maintain its organisational views.', 'TIER_1_BUILT', '/inventory/materials', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.529102+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('937e105d-9537-419f-bcfd-12ab5ca7a7a7', 'PROD.MRP.SETTINGS', NULL, 'Material planning settings', 'TRANSACTION', 'PROD', 'Planning parameters and net-change file, not yet an executable planning run.', 'TIER_1_BUILT', '/inventory/materials?view=MRP', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.532998+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('576b042d-30c7-4fe9-b34d-f61f6ca4dc37', 'CFG.ORG.COMPANYCODE.DEFINE', NULL, 'Company code define', 'CONFIG_ACTIVITY', 'FND', 'The legal entity that keeps its own books, with its chart of accounts, fiscal year variant and posting period variant assigned.', 'TIER_2_CONFIGURED', '/config/company-codes', 'A', NULL, true, 'SEED', '2026-11-10 08:54:14.534127+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('4be7f0bb-baec-4dd7-99c4-c1e177625803', 'CFG.ORG.COMPANYCODE.ASSIGN_COA', NULL, 'Assign chart of accounts to company code', 'CONFIG_ACTIVITY', 'FND', 'Give a Company Code the chart of accounts it keeps its books in, on its own screen under its own capability, separated from Company Code definition. Only active, unblocked charts are offered. This is an initial assignment only: a Company Code that already holds a chart keeps it, a different chart cannot replace it here, and repeating the standing chart changes nothing. A reason is mandatory on the write and stands on the one change document recorded against the Company Code with the chart flagged security-relevant.', 'TIER_2_CONFIGURED', '/config/company-codes/assign-chart-of-accounts', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.536684+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d7621317-c08d-430c-913c-86f8a36ee42f', 'CFG.FIN.COA.DEFINE', NULL, 'Chart of Accounts definition', 'CONFIG_ACTIVITY', 'FIN', 'Maintain tenant-local Charts of Accounts, language, account-number length, cost-element integration policy, the block flag, deactivate/reactivate lifecycle, and the separate Group CoA registry that feeds the Group CoA F4.', 'TIER_2_CONFIGURED', '/config/chart-of-accounts', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.537876+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('a8301eab-f860-4164-bc0d-fb6ba5ec437e', 'CFG.FIN.COA.COPY', NULL, 'Copy Chart of Accounts', 'CONFIG_ACTIVITY', 'FIN', 'Copy every G/L account of one active, unblocked chart of accounts into another inside the same tenant, in one transaction. Refused when the target chart is narrower than the source unless leading zeros are padded, when an Account Group the source uses is missing or deactivated in the target registry, when a copied number falls outside the range its group owns there, when a group account number is not defined in the target Group Chart of Accounts, and when an account already exists in the target unless overwrite is asked for — an account carrying postings, open items or a balance refuses the whole copy. The target account group field status matrix governs the copied values, a reason is always mandatory, and the audit trail is one summary document for the copy. Cross-tenant copies need a platform-admin service token and are not offered.', 'TIER_2_CONFIGURED', '/config/chart-of-accounts/copy', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.540583+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d410430b-09f8-4d4a-a0a9-0ffb4cc1dce9', 'CFG.FIN.FYV.DEFINE', NULL, 'Fiscal year variant definition', 'CONFIG_ACTIVITY', 'FIN', 'Define a fiscal year variant and maintain the period list behind it. The key is two upper-case characters and immutable once defined, the description is mandatory, and a variant either follows the calendar year — in which case its periods are derived from its own counts — or shifts the year boundary, in which case the period ends are maintained, per year when the variant is year dependent. A variant holds between one and sixteen ordinary periods and up to four periods for year-end adjustment; the ordinary ones come first. Only the end of a period is stored, as month, day and year shift, and the posting engine derives every start from the previous end, with period one following the last period of the previous fiscal year. A variant in use is retired rather than deleted, and retirement is refused while a Company Code or Controlling Area still points at it. Every write records one change document.', 'TIER_2_CONFIGURED', '/config/fiscal-year-variants', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.54275+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('01147ebf-8810-4049-b853-6bd6a53d12da', 'CFG.FIN.FYV.ASSIGN', NULL, 'Assign fiscal year variant to Company Code', 'CONFIG_ACTIVITY', 'FIN', 'Choose the fiscal year variant a Company Code posts in. The variant must be defined and active, and only active variants are offered. A Company Code linked to a Controlling Area shares that area''s variant with the area''s other Company Codes, so an assignment that would break the sharing is refused naming the area and both variants. A Company Code that has already posted may still change calendar, but only with a reason, and the answer names how many documents were posted and which fiscal years they span: those documents keep the periods they were posted in, so from the change onward one variant means a different set of dates. Repeating the variant a Company Code already holds changes nothing. There is no unassignment — a Company Code that has a variant keeps one until another is assigned — and every write records one change document against the Company Code with the variant flagged security-relevant.', 'TIER_2_CONFIGURED', '/config/fiscal-year-variants/assign-company-codes', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.544683+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('b5895b8c-8530-46fb-bd57-93dc15ae0eca', 'CFG.FIN.GLACCOUNT.TRANSFER', NULL, 'G/L account master transfer', 'CONFIG_ACTIVITY', 'FIN', 'Transfer the company-code segments of G/L accounts from a source to a target company code on the same chart of accounts: account currency, tax category, open-item management, sort key and posting block copy under a test-run default, an optional overwrite policy, and a per-account CREATED / UPDATED / SKIPPED / ERROR protocol persisted per run. Chart-level records are never overwritten for a company difference; the utility posts nothing and no period lock blocks it.', 'TIER_2_CONFIGURED', '/config/gl-accounts/transfer', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.552109+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('8f796a6b-7cdc-4438-a7ed-a749c1b1bb49', 'CFG.FIN.DOCTYPE.DEFINE', NULL, 'Define document types', 'CONFIG_ACTIVITY', 'FIN', 'Define the document types every accounting document carries: what it may post to, the number range interval its number comes from, and how it reverses. A type is keyed by exactly two letters or digits and cannot be renamed: correcting it means defining the new type and, where the old one should not stand, deactivating or deleting it. The interval must be one defined for the type''s number range object, because a type pointing at an interval nobody defined would post documents nobody can number. The account types allowed are Assets, Customers, Vendors, Materials and G/L accounts — at least one — and decide which kinds of account a document of the type may touch. The reverse document type, where one is named, must stand in the same tenant; the reversal mode says whether a reversal posts on the same date, may choose another, or is not allowed. A type may be deactivated at any time — it stops being offered to posting while posted documents keep reading it — and may be deleted only while no journal entry in the tenant carries it, since an entry names its type and a type history names stays readable. Every write records one change document with the account types and the interval flagged security-relevant, since together they decide what may be posted and where its number comes from.', 'TIER_2_CONFIGURED', '/config/document-types', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.554413+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('9afbbb86-c5dc-4be1-8da6-f250e5256b84', 'CFG.FIN.IC.DEFINE', NULL, 'Configure intercompany clearing accounts', 'CONFIG_ACTIVITY', 'FIN', 'Configure the intercompany company pairs and the clearing accounts that bridge them. A pair names an ordered sending and receiving company of the tenant — both must stand configured, active and different — and may override each side’s clearing account; a side without an override falls back to the OBYA intercompany clearing account the company master already carries, which must exist in that company’s chart and stand extended to it. An override must be a balance-sheet account of that side’s chart. A default transaction currency may be named for the pair; without one each posting uses the sending company’s currency. A pair that has served a posting stands as history: it cannot be deleted, because the posted document pairs cite it, and a changed arrangement is expressed by defining a new pair. Every save and deletion records one change document.', 'TIER_2_CONFIGURED', '/config/intercompany-clearing', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.557135+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('44052f64-4101-4483-a7f1-14bdc789f672', 'FIN.IC.POST', NULL, 'Post an intercompany journal', 'TRANSACTION', 'FIN', 'Post one intercompany transaction as two accounting documents in one atomic step: the sending company carries the primary lines plus a balancing clearing line on its OBYA account, and the receiving company carries the mirrored lines plus its own clearing line. Both documents post through the canonical engine, so numbering, period validation on each company’s own fiscal calendar, document flow and audit stand as for any journal. Every line on both sides stamps the other company as its trading partner so a consolidation elimination can read the pair from the ledger. The transaction currency translates to each company’s local currency at the posting date; a missing rate refuses naming the company. The two documents are linked in an intercompany pairing record, and the OBYA balances are ordinary open-item balances cleared through the G/L clearing screen when settlement occurs. A retried submission replays the standing pair rather than posting twice.', 'TIER_1_BUILT', '/finance/intercompany', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.559406+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('72b51978-6420-4920-8484-d787c6f7a2f0', 'CFG.FIN.TOLERANCE.DEFINE', NULL, 'Define employee tolerance groups', 'CONFIG_ACTIVITY', 'FIN', 'Define the employee tolerance groups that carry the posting ceilings for groups of users: the maximum amount per document and per line item, the maximum cash discount percentage, and the amount and percentage a payment difference may book on its own, split revenue and expense. A group is keyed by company code and group key, and both parts may be blank as deliberate values: a blank company code is the tenant-wide scope standing under every company code, and a blank group key is the default group of its scope, the baseline for users with no explicit assignment; a named company code must stand in the tenant. Neither key part can be renamed — correcting identity means defining the new group. A limit of zero imposes no ceiling, and the line item ceiling is judged against the document ceiling only when both stand non-zero. Groups cannot be deleted yet: removal becomes possible when user assignment exists to be checked, and until then a mistaken group is corrected by defining the right one. Every write records one change document with all seven limits flagged security-relevant, since together they decide what a user may post. Journal posting does not read these limits yet; this activity defines the configuration it will read.', 'TIER_2_CONFIGURED', '/config/tolerance-groups', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.561689+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('5dea163f-fcbb-40d0-9834-4256fda970ea', 'PEOPLE.EMPLOYEE.CREATE', 'employee', 'Employee master', 'TRANSACTION', 'PEOPLE', 'The employee: a personnel number the tenant supplies and a name. What is known about the person stands in dated records of the configured types, so a change is a new dated record rather than an overwrite, and no record is deleted. Nothing here calculates or posts pay: payroll is posting-side only and waits on the result a pay-component and deduction configuration would produce (D-013, R-11).', 'TIER_1_BUILT', '/people/employees', 'B', NULL, true, 'MIGRATION_9193', '2026-11-10 08:54:11.916755+00', 'SEED', '2026-11-10 08:54:14.564763+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('e27412c0-6f9f-4546-8b0b-eb31950ed057', 'CFG.FIN.RETAINED.DEFINE', NULL, 'Define retained earnings account', 'CONFIG_ACTIVITY', 'FIN', 'Define retained earnings account: per chart of accounts, the retained earnings account each one-character indicator (X the standing convention) closes profit and loss balances to. P&L accounts name their indicator in the G/L account master, and saving one refuses, naming this definition, until the indicator stands defined; balance carryforward then closes each P&L account per indicator to its retained earnings account and refuses naming every account whose indicator lacks a determination. The determinations live on the standing account determination table, the indicator in the general-modifier slot of the retained earnings event, so this screen and the account determination screen read one source. The named account must stand in the same chart as an EQUITY balance-sheet account. Deletion refuses while a P&L account carries the indicator. Every write needs a reason and records one change document. The standard package seeds indicator X to its retained earnings account, so a fresh tenant passes from day one.', 'TIER_2_CONFIGURED', '/config/retained-earnings', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.579657+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d0fafcd0-113f-4b19-b2df-d55aafdea368', 'CFG.FIN.ACCTDET.DEFINE', NULL, 'Define account determination', 'CONFIG_ACTIVITY', 'FIN', 'Define account determination: the G/L account an automatic posting derives for each posting event, per chart of accounts, valuation class and general modifier. The posting events are the product''s own — inventory posting, GR/IR clearing, offsetting entry for inventory, price differences — and the reference transaction keys are search aliases only, never stored. Each event expects an account kind, balance sheet or profit and loss, and states whether it splits by valuation class or general modifier; a row may name neither modifier (any class, no split), and modifiers an event does not use are refused. The valuation class is the material master''s own, so a row names the class a material actually carries. The G/L account must stand in the named chart and be of the kind the event expects, each failure refused by its own name, and it is the one changeable field: the key — chart, event, class, modifier — cannot be renamed. A determination may be deleted with a reason; the posting that would have derived the account will then fail for want of the row, which the screen states where Delete sits. Every write records one change document with the G/L account flagged security-relevant, since money will move by it. Logistics postings do not read these rows yet; this activity defines the configuration they will read.', 'TIER_2_CONFIGURED', '/config/account-determination', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.582244+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('045e9a5e-139a-4676-8c28-fbef40987c9e', 'CFG.COST.COSTCENTER.DEFINE', NULL, 'Define cost centres', 'CONFIG_ACTIVITY', 'COST', 'Define cost centres: the master data cost accounting collects overhead on, period by period. A cost centre exists inside a controlling area, keyed (controlling area, cost centre, valid from); several non-overlapping validity periods may stand per centre, each carrying its own facts, and valid to may be re-set while it overlaps no sibling period. The company code must stand assigned to that controlling area; the currency comes from the area and is never stored twice; the category is a product word — production, administration, service, sales, support — the reference single letters being search aliases only. Deletion is refused while journal documents dated inside the period carry the centre, the refusal stating the count; afterwards the posting lock is the standing alternative, stopping new postings while history stays readable. Hierarchy placement arrives with the hierarchy activity. Every write records one change document with the company code and lock state flagged security-relevant. Postings carry centre codes as text and do not validate them against these rows yet; this activity defines the master they will read.', 'TIER_2_CONFIGURED', '/config/cost-centers', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.58758+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('fd2dabbb-859b-4bb1-96b0-c36141a1fdfe', 'CFG.COST.COSTCENTERHIER.DEFINE', NULL, 'Define cost centre hierarchy', 'CONFIG_ACTIVITY', 'COST', 'Define cost centre hierarchy: two structures, as the reference carries both. The standard hierarchy is one tree per controlling area into which cost centre periods are placed — at most one node per period, parent links judged acyclic and the tree guarded at ten levels, exactly one root, nodes deletable only while no child node and no placed period stands under them. Alternative groups stand beside the tree: a centre may sit in any number of them, and their leaves may name single centres, ranges, or exclusions, resolved in display order against the centre keys standing in the area — membership is the resolution, not a stored fact, and a leaf may name a centre that does not stand yet. Placement is per validity period, moving shown as unplace-then-place; deleting a group removes its leaves with it; unplacing or deleting never touches the cost centre master. Group-in-group subsets are not built. Every write records one change document with placements and leaf signs flagged security-relevant. Rollups and reports do not read these structures yet; this activity defines the trees they will read.', 'TIER_2_CONFIGURED', '/config/cost-center-hierarchy', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.590059+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d8130664-f269-44bb-b798-45cf573cb86f', 'CFG.COST.ACTIVITYTYPE.DEFINE', NULL, 'Define activity types', 'CONFIG_ACTIVITY', 'COST', 'Define activity types: the measurable output a cost centre performs, period by period inside a controlling area. The key is (controlling area, activity type, valid from); several non-overlapping validity periods may stand per type, each carrying its own facts, and valid to may be re-set while it overlaps no sibling period. The activity unit is judged against the global unit of measure table on existence; the two behaviour fields are stored as the reference digits — category 1 to 4 (manual entry and manual allocation; indirect determination and indirect allocation; manual entry and indirect allocation; manual entry, no allocation) and price indicator 1 to 3 (automatic on activity; automatic on capacity; manual entry) — with their meanings displayed as words beside the digits. The type may name the cost centre categories it is valid for, stored as the canonical subset, blank meaning all categories. Deletion is hard and, today, unconditional: nothing prices or allocates against these types yet, and rates will give deletion its usage count when they land; the posting lock is the standing alternative that keeps a type standing while stopping new pricing. Every write records one change document with the unit, category, price indicator and lock state flagged security-relevant. This activity defines the master the activity rates will read.', 'TIER_2_CONFIGURED', '/config/activity-types', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.59575+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('540ad2a3-0ee9-4edc-95ce-5743fc446cd9', 'FIN.JOURNAL.PARK', NULL, 'Park a journal entry', 'TRANSACTION', 'FIN', 'Park a G/L document as a preliminary entry: it may stand incomplete and unbalanced in staging, moving no account, until a judged save-as-complete balances it and posting converts it through the accounting engine — the parked record then stands retained, naming the posted document. Edits are version-checked; deletion is a reasoned status, never a row delete.', 'TIER_1_BUILT', '/finance/journal/park', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.697392+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('83a27b5b-3bc0-48f8-a36a-8b3d7a50c79c', 'CFG.COST.ACTIVITYRATE.CONFIRM', NULL, 'Plan activity prices', 'CONFIG_ACTIVITY', 'COST', 'Plan activity prices: the prices of activity types, planned per cost centre, planning version, fiscal year and fiscal period. One save per (controlling area, version, year, cost centre, activity type) upserts every period cell of the matrix as its own row under one change document, the fixed and variable price components flagged security-relevant. The planning version is a free key of up to three letters or digits — any number of versions stand side by side, and a version stands when it is first planned against; there is no version administration. Fiscal periods are those of the controlling area fiscal year variant for the year, special periods sharing the last regular period window. Validity is judged per period against the fiscal period window, never per year: a standing cost centre period and a standing activity type period must both cover part of the window, neither may be locked for posting, and the type must be valid for the centre period category. The type price indicator governs entry — manual indicators keep the entered fixed and variable components per price unit in the controlling area currency, automatic indicators refuse entered components because the price belongs to a calculation that does not exist yet, while the planned quantity stands either way. These rows are usage of both masters: an activity type period or a cost centre period refuses deletion while rates stand against it, the count named. Nothing calculates or allocates against these rows yet.', 'TIER_2_CONFIGURED', '/config/activity-rates', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.598158+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('b76e0ec3-56a3-4ab0-9cff-1f0173f139a4', 'CFG.COST.PROFITCENTER.DEFINE', NULL, 'Define profit centres', 'CONFIG_ACTIVITY', 'COST', 'Define profit centres: the units profitability is reported on, period by period inside a controlling area. The key is (controlling area, profit centre, valid from); several non-overlapping validity periods may stand per centre, each carrying its own facts, and valid to may be re-set while it overlaps no sibling period. The short name of at most 20 characters is required and the long text of at most 40 optional, both on the row. The person responsible is free text; the responsible user, when entered, must be an active user of the tenant. The segment is kept at its reference width and entered freely until a segment master stands to judge it. Hierarchy placement is deferred to the profit centre hierarchy activity, exactly as cost centre placement was: this screen gains its read-only placement afterwards. Deletion is refused while journal documents dated inside the period carry the centre, the count named; the posting lock is the standing alternative. Every write records one change document with the responsible user, segment and lock state flagged security-relevant. Journal lines carry the centre code as text and resolve it by validity dates; this activity defines the master they will read.', 'TIER_2_CONFIGURED', '/config/profit-centers', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.600692+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('7279988a-f97e-4980-bd29-266c0e1991de', 'CFG.COST.PROFITCENTERHIER.DEFINE', NULL, 'Define profit centre hierarchy', 'CONFIG_ACTIVITY', 'COST', 'Define profit centre hierarchy: the reporting structure of profit centres inside a controlling area, in two shapes. The standard hierarchy is one tree per controlling area with an explicitly created single root; nodes of up to 24 letters or digits nest to at most ten levels, parent links cannot cycle, and a profit centre validity period is placed on exactly one node — the unique placement is the rule, so a move is unplace-then-place and the audit trail shows both ends — while periods of the same centre may sit on different nodes across their validity. Alternative groups stand beside the tree for reporting and planning subsets: their leaves name single centres or code ranges, included or excluded, and membership is resolved against the master as it stands, so a centre created tomorrow inside a standing range is a member without an edit. Deleting a node is refused while child nodes or placed periods stand, the counts named; deleting a group removes its leaves only; the profit centre master is never touched by a structural act. Every write records one change document with placements and leaf signs flagged security-relevant. The KE51 screen shows each period its node from these assignments. Subsets and rollups do not read these trees yet.', 'TIER_2_CONFIGURED', '/config/profit-center-hierarchy', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.602937+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('083c89d0-9b02-463c-9068-c5848686a7ab', 'CFG.INV.MATERIALTYPE.DEFINE', NULL, 'Define material types', 'CONFIG_ACTIVITY', 'INV', 'Define material types: the vocabulary materials are created against, kept at the reference parity. The key is at most four uppercase letters or digits and the description at most 25 characters, required. The default price control is stored as its reference letter — S standard price, V moving average price — and shown as words, for materials to inherit until their own price control is set. Both material number ranges are keys of exactly two characters judged against the standing number-range engine: a range standing active for object MATERIAL under that key, the internal key against an internal range and the external against an external one. Every type names one account category reference, judged against the reference master maintained on the same screen; which valuation classes a reference permits is decided when classes are maintained. External and internal purchase orders take Not allowed, Allowed with warning or Allowed; the type may support configurable materials. Quantity and value updating stand per plant on their own rows, a change refused while materials of the type stand at the plant; the material screens read those rows. Deletion is hard and refused while materials carry the type, the count named; deactivation is the standing alternative. Every write records one change document, the price control, number ranges, account reference and updating flags security-relevant. This activity defines the types the material master reads.', 'TIER_2_CONFIGURED', '/config/material-types', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.6081+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('373dfd84-5fea-4ad4-a575-1d9214d677fa', 'CFG.INV.VALCLASS.DEFINE', NULL, 'Define valuation classes', 'CONFIG_ACTIVITY', 'INV', 'Define valuation classes and the account category references that permit them. OMSK is a search alias only. The reference key is one to four letters or digits and keeps its leading zeros. The class key is the material master own key, one to twenty letters, digits or underscores, and is never converted to a number, so 0001 stays 0001. A class may be assigned to more than one reference. A material type already names one reference; changing that reference does not rewrite a material valuation class, and the change is refused when standing materials would no longer be allowed their class. A material may carry a class only when the class is active and assigned to the type reference. A delivered class also names the material types it was supplied for, so the raw class stays with raw materials while those types share one reference. An empty type list permits every type on the assigned references. A class a material or an account determination already names cannot be deactivated or deleted; the counts are named, and the description may still change. A posted document is not rewritten. Inventory postings judge the class again and do not substitute an account. A save must send the version it opened; a stale version is refused. A G/L account is not stored on the class. A closed posting period does not block this screen. A transport is refused by name: this product has no target landscape. The change document is the recorded change set.', 'TIER_2_CONFIGURED', '/config/valuation-classes', 'B', NULL, true, 'MIGRATION_9106', '2026-11-10 08:54:11.391538+00', 'SEED', '2026-11-10 08:54:14.610409+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('c8ef502f-5df5-44fe-a2f7-a1eccf1a8f49', 'CFG.INV.MOVETYPE.CONFIG', NULL, 'Configure movement types', 'CONFIG_ACTIVITY', 'INV', 'Configure movement types: the catalogue goods movements already read, at the standing row. The key is one to twenty uppercase letters, digits or underscores and is never renamed; a three-digit alias is not stored beside it. Direction, reference, reversal, stock types, plant and location rules, valuation and the account-determination event and modifier are the policies. The modifier is not a G/L account, and a company code, a draft, a version, a policy identifier, a field-selection profile, a two-step movement, batch, serial and special stock are refused by name. A reversal must already stand, and it cannot name a different counter. Goods receipt will not guess between two receipt movements for a purchase order, and a second difference movement for the same direction is refused because physical inventory posting will not guess either. A movement a material document or a reservation already cites keeps its posting rules; the description may still change, and deletion is refused while that history stands, the counts named. The change document is the history. A posted document is not rewritten. This screen posts no stock and no journal, and a closed posting period does not block it. A posting service uses a movement only when that service already names it.', 'TIER_2_CONFIGURED', '/config/movement-types', 'B', NULL, true, 'MIGRATION_9103', '2026-11-10 08:54:11.37938+00', 'SEED', '2026-11-10 08:54:14.611978+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('138e88f5-1d15-4871-9204-65ea4b7545d3', 'CFG.PROC.RELEASE.DEFINE', NULL, 'Define release strategies', 'CONFIG_ACTIVITY', 'PROC', 'Define release strategies: the approval structure for purchasing documents. A release group judges one document category — purchase requisitions or purchase orders — and owns the release codes approvers act under. A strategy binds its group to one classification class of the matching type and judges a document against criteria on the class characteristics, confined to the delivered document attributes (total value, plant, purchasing group, company code, and on orders the supplier and purchasing organization), with values judged against each characteristic format and allowed values. Strategies carry a priority — the lowest matching wins — and sequence at most eight of their group codes. A strategy activates only beneath an active class, blocks rather than deletes once it has lived, and a code sequenced by a strategy cannot leave its group. The determination judge stands exported for the release-acts round; no document status moves on this screen. Every write carries a mandatory reason and one change document.', 'TIER_2_CONFIGURED', '/config/release-strategies', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.613753+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('0de3b45d-1790-4c39-b844-029390c6f448', 'CFG.PROC.CLASS.DEFINE', NULL, 'Define classes', 'CONFIG_ACTIVITY', 'PROC', 'Define classes: characteristics grouped under a class type, at the reference parity. Class types stand as a delivered catalogue in house words — material, batch, equipment, variant, and the purchase requisition and purchase order release classes. A class is keyed by its type and a name of at most eighteen uppercase letters, digits and underscores, both immutable; its description stands at forty characters in the tenant language. Characteristics are assigned at ordered positions, each at most once per class, a blocked characteristic refused with the remedy named; a required flag may mark a characteristic the classification must carry. A class is born in draft, activates through its act, and blocks rather than deletes once it has lived — deletion stands only for a draft without assignments. Every write carries a mandatory reason and one change document. This activity defines the classes the release-strategy round consumes.', 'TIER_2_CONFIGURED', '/config/classes', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.616489+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('57f65fa4-2260-4db6-a5e3-4fbeb14c7561', 'CFG.PROC.CHARACTERISTIC.DEFINE', NULL, 'Define characteristics', 'CONFIG_ACTIVITY', 'PROC', 'Define characteristics: the tenant vocabulary classification judges by, at the reference parity. The name is a stable key of at most thirty uppercase letters, digits and underscores, never renamed; the description stands at thirty characters in the tenant language. The format is CHAR, NUM, DATE, TIME or CURR with length and decimal places judged per format; intervals stand only on NUM, DATE and TIME; a unit judges against the unit master and a CURR characteristic names its currency. Allowed values are unique per characteristic under the case policy it declares, and values outside the list stand only where additional values are allowed. A characteristic is born in draft, activates through its act, and blocks rather than deletes once it has lived — deletion stands only for a draft that never carried values. The lifecycle is a Cairn workflow, not a reference status. Every write carries a mandatory reason and one change document with the format security-relevant. This activity defines the characteristics the class and release-strategy rounds will consume.', 'TIER_2_CONFIGURED', '/config/characteristics', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.621395+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('9362629a-3fa4-4183-bc9f-755b790331d5', 'CFG.INV.MATPERIOD.DEFINE', NULL, 'Define material period control', 'CONFIG_ACTIVITY', 'INV', 'Define material period control: the material posting gate per company code, at the reference parity. One control record stands per company code carrying the current and previous material year and period, the previous-year reference, and the two backposting indicators kept separate — posting to the previous period may be allowed, and backposting after a period change may be disallowed, the shift itself then clearing the allowance. A record is initialized once, to a year and period judged against the company fiscal year variant, whose special periods are never material periods; an established record is never reinitialized or edited in place, and it is never deleted. Afterwards the period advances only through the guarded shift of exactly one period, which makes the old current period the previous one and writes the previous-year reference at a year boundary. Financial posting periods are controlled separately and neither gate implies the other. Every act — initialization, indicator maintenance, the shift — records one change document with a mandatory reason. This activity defines the periods material postings will be judged against.', 'TIER_2_CONFIGURED', '/config/material-period-control', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.623795+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('4f241d0c-642a-45b0-8433-1248822ee0ae', 'CFG.INV.INDUSTRYSECTOR.DEFINE', NULL, 'Define industry sectors', 'CONFIG_ACTIVITY', 'INV', 'Define industry sectors: the classification a material is created under, at the reference parity. The key is exactly one uppercase letter or digit and is never renamed; the name of at most 40 characters is required, kept in the tenant one language. The standard sectors are delivered to every tenant — plant engineering and construction, chemical industry, mechanical engineering, pharmaceuticals and retail — and tenants may add their own. Creating a material requires a standing active sector, and naming an inactive or unknown sector is refused with the master named. Deletion is hard and refused while materials carry the sector, the count named; deactivation is the standing alternative for a sector in use. Every write records one change document with the active flag security-relevant. This activity defines the sectors the material master reads.', 'TIER_2_CONFIGURED', '/config/industry-sectors', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.62878+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('016c4dd1-3d85-400e-8847-0368f8a704b8', 'CFG.ORG.INDUSTRY.DEFINE', NULL, 'Maintain Industries', 'CONFIG_ACTIVITY', 'ORG', 'Maintain Industries: the classification a business partner carries, at the reference parity (OB44 as a search alias only). The code is one to four uppercase letters or digits and is never renamed; descriptions of at most 20 characters stand per configured system language — today English alone stands configured — and a new industry requires the default-language description. Five industries stand delivered to every tenant (MEC1 Mechanical Eng., CHEM Chemical, PHAR Pharmaceutical, RETL Retail, CONS Construction). The business partner carries the industry under a restricting reference, so deletion is hard and refused while partners carry the code, the count named; deactivation stands beside it. A reason stands on every write, one change document per write. This activity defines the industries the partner master reads; the picker on the partner screen itself follows. Distinct from the industry sector a material is created under.', 'TIER_2_CONFIGURED', '/config/industries', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.631543+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('a574bf98-91e5-4506-bddb-799471052c08', 'CFG.INV.MATERIALRANGE.DEFINE', NULL, 'Define material number ranges', 'CONFIG_ACTIVITY', 'INV', 'Define material number ranges: named groups of material intervals at the reference parity. A group is one internal and one external interval of the material number object paired under a description of at most 20 characters; the pair of two-character range keys is the group identity and never changes under it, while the description is edited freely. Both intervals must stand active on the number range screens with the matching assignment before a group is defined over them. Material types carry the same two keys, so a type belongs to the group its keys pair into — the material types screen shows the group text beside the keys and offers the group as a picker filling both. Deleting a group is refused while material types carry its pair, the count named. When a material is created, a blank material number draws the next number from its type internal interval through the standing number engine, and a supplied number is judged against the type external interval where one is configured; existing material numbers never move when assignments change. Intervals, buffering and the current number itself are maintained on the number range screens. This activity defines the groups material creation numbers by.', 'TIER_2_CONFIGURED', '/config/material-number-ranges', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.633666+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('ece6cff7-71db-43d4-81d5-2cfff4876892', 'CFG.INV.MATERIALGROUP.DEFINE', NULL, 'Define material groups', 'CONFIG_ACTIVITY', 'INV', 'Define material groups: the classification materials carry for procurement, reporting and search, and nothing more. The key is at most nine uppercase letters or digits and is never renamed; the short description of at most 20 characters is required and the long description of at most 60 optional, both kept on the row in the tenant one language. No number-range, valuation or period behaviour attaches to a group, and no validity periods stand against it. Materials name one group when they are created and are judged against this master; reports read the group as it stands. Deletion is hard and refused while materials carry the group, the count named; deactivation is the standing alternative for a group in use. Every write records one change document with the active flag security-relevant. This activity defines the groups the material master reads.', 'TIER_2_CONFIGURED', '/config/material-groups', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.635584+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('334a2dff-1b4d-4699-a07d-4f2353bd82bf', 'CFG.FIN.HOUSEBANK.DEFINE', NULL, 'Define house banks', 'CONFIG_ACTIVITY', 'FIN', 'Define the tenant''s own banks, one house bank per company code, and the accounts held at each. A house bank is named by a key of up to five letters or digits within its company code and names a bank from the global bank master by country and key; the master''s name, city and SWIFT code are displayed from there and never typed here. The bank reference may be corrected, but a house bank''s key cannot be changed: renaming it means defining the new house bank and, where the old one should not stand, deleting it. Under it, each bank account has an ID of up to five characters, the local account number of up to eighteen, an optional IBAN of up to thirty-four — a Kuwait IBAN is thirty — a currency from the currency master, and the G/L account its postings clear through. That G/L account must be an asset balance-sheet account of the chart assigned to the company code, each failure named on its own. A house bank may be deleted only once its accounts are deleted; an account, referenced by nothing yet, may be deleted outright. Every write records one change document with the bank reference and the G/L mapping flagged security-relevant, since together they decide where a tenant''s money is said to be.', 'TIER_2_CONFIGURED', '/config/house-banks', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.637625+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('a547d60a-dd2e-42ca-9ca6-b3feee8d8149', 'CFG.FIN.BANK.DEFINE', NULL, 'Define banks (bank master)', 'TRANSACTION', 'FIN', 'The bank master: every bank a house bank may name, held once for all tenants. A bank is keyed by its country — chosen from the country master — and the bank key within it, the national bank identifier of up to fifteen letters or digits. The name is required; the city and the SWIFT code are optional, the SWIFT held to the BIC shape of eight or eleven characters. A bank''s key cannot be changed: correcting it means defining the new entry and, where the old one should not stand, deleting it. The name, city and SWIFT code may be changed, and a change repeating what stands writes nothing. A bank may be deleted only while no house bank in any tenant names it, because house banks read its name, city and SWIFT code as facts they do not own. Banks are global reference data, not one tenant''s configuration: maintaining them completes no configuration activity, and their audit is the actor recorded on the row rather than a tenant change document.', 'TIER_2_CONFIGURED', '/config/banks', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.640284+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('0542b87a-a422-426d-8206-5f4b3385efdd', 'CFG.FIN.TAXCODE.DEFINE', NULL, 'Define tax codes for sales and purchases', 'CONFIG_ACTIVITY', 'FIN', 'Define the tax codes a journal line names, per country, with the rate each carries and the condition type and account key a posting rule reads. The code is up to four letters or digits within its country — the width a journal line itself holds — and the country is chosen from the country master. The rate is a percentage between nothing and a hundred at two fractional digits. A code''s key — country and code — cannot be changed: renaming it means defining the new code and, where the old one should not stand, deleting it. The description, rate, condition type and account key may be changed with a reason, and a change repeating what stands writes nothing. A code may be deleted only while no journal line in the tenant carries it — lines store the code without its country, so the count covers every country — because a code history names stays readable at a new rate rather than vanishing. Every write records one change document with the rate flagged security-relevant, since the rate decides what a sale or a purchase costs after tax.', 'TIER_2_CONFIGURED', '/config/tax-codes', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.642355+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('307fad67-2ff7-4eaf-b342-73ccfb46086e', 'CFG.FIN.EXRATE.MAINTAIN', NULL, 'Maintain exchange rates', 'CONFIG_ACTIVITY', 'FIN', 'Maintain the rate each currency pair converts at, by exchange rate type — Average, Buying or Selling — and the date the rate takes effect. A rate is quoted for a translation ratio on each side, and the effective rate is the quoted rate times the to-ratio over the from-ratio; both ratios default to one. Currencies are chosen from the currency master and must be active and different. A rate''s key — type, pair and valid-from date — cannot be changed: correcting it means creating the new rate and, where the old one should not stand, deleting it. The quoted rate and its ratios may be changed with a reason, and a change repeating what stands writes nothing. A rate may be deleted, with a reason, because documents already posted keep the rate they were posted with, so deletion governs future lookups and rewrites no history. Every write records one change document with the rate flagged security-relevant, since the rate decides what a foreign-currency amount becomes in the books.', 'TIER_2_CONFIGURED', '/config/exchange-rates', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.644685+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('5954353a-0d8b-4340-a787-1f925e5e9b20', 'CFG.FIN.PPV.ASSIGN', NULL, 'Assign posting period variant to Company Code', 'CONFIG_ACTIVITY', 'FIN', 'Assign the posting period variant a Company Code posts against, or clear the assignment. Any variant defined in Posting period variant definition may be chosen at any time, and repeating the variant already held changes nothing. A variant may be cleared only while the Company Code has no journal entries, because the entries already posted were posted against the open periods that variant holds; after that it may move to another variant but may not be left unassigned. A reason is mandatory on every write, and every write records one change document against the Company Code with the variant flagged security-relevant, since the variant decides which periods are open for everything posted next.', 'TIER_2_CONFIGURED', '/config/posting-period-variants/assign-company-codes', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.646781+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('c86d721d-469e-4f69-b050-4817616349d6', 'CFG.FIN.PPV.DEFINE', NULL, 'Posting period variant definition', 'CONFIG_ACTIVITY', 'FIN', 'Define the posting period variant a Company Code posts against. The key is exactly four upper-case letters or digits and immutable once defined; the description is mandatory and holds at most thirty characters. A new variant is created with one interval per account type — general ledger, vendor, customer, asset and material — each open for the whole fiscal year, with next-year postings allowed and special periods permitted where the standard package permits them, so a variant is usable the moment a Company Code is assigned to it. The intervals themselves are opened and closed per Company Code in Posting periods, not here. A variant may be deleted only while no Company Code posts against it, and the deletion takes the variant''s own intervals with it, because an interval cannot outlive the variant it belongs to; the refusal names every Company Code holding it and the activity that reassigns them. Defining a variant requires a fiscal year variant to have been assigned to a Company Code first, since there is otherwise no fiscal year for it to open. Every write records one change document, with the key and the interval set flagged security-relevant.', 'TIER_2_CONFIGURED', '/config/posting-period-variants', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.649216+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('33b825c0-7d47-4890-99ea-0550b2ded17f', 'FIN.CLOSE.PERIOD', NULL, 'Posting periods', 'TRANSACTION', 'FIN', 'Which periods are open, per account type. Closing a period is recorded in the change log.', 'TIER_1_BUILT', '/config/posting-periods', 'A', NULL, true, 'SEED', '2026-11-10 08:54:14.651244+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('e1a95146-9944-485a-bcc8-343e26d0aa73', 'CFG.ORG.PLANT.DEFINE', NULL, 'Plant definition', 'CONFIG_ACTIVITY', 'FND', 'Production and storage sites; Company Code assignment and Storage Location definitions are separate activities.', 'TIER_2_CONFIGURED', '/config/plants', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.653561+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d51815a6-cdcd-4abf-8813-e51ac1ceef6e', 'CFG.ORG.STORAGELOC.DEFINE', NULL, 'Storage Location definitions', 'CONFIG_ACTIVITY', 'FND', 'Create, change and deactivate Storage Locations within an active tenant Plant; negative-stock allowance is stored configuration only.', 'TIER_2_CONFIGURED', '/config/storage-locations', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.656752+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('b8f92493-301f-4919-a185-7db3315a9786', 'CFG.ORG.SALESORG.DEFINE', NULL, 'Sales Organization definition', 'CONFIG_ACTIVITY', 'SALES', 'Create, change and soft-deactivate tenant Sales Organizations with retained history; Company Code assignment is separate in SCR-021. Exact on-prem GUI field parity with the reference product remains under review.', 'TIER_2_CONFIGURED', '/config/sales-orgs', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.659245+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('3e3e6f84-016c-4417-8cbc-ae56ccda1f4f', 'CFG.ORG.SALESORG.ASSIGN_COMPANY', NULL, 'Assign Sales Organization to Company Code', 'CONFIG_ACTIVITY', 'SALES', 'Assign one active tenant Sales Organization to one active Company Code; reassignment is audited and unassignment is not included.', 'TIER_2_CONFIGURED', '/config/sales-orgs/assign-company', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.660416+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('0d944e3d-9e74-419a-959f-6d2c29b3f2ec', 'CFG.ORG.SALESORG.ASSIGN_DISTCHANNEL', NULL, 'Assign Distribution Channel to Sales Organization', 'CONFIG_ACTIVITY', 'SALES', 'Maintain tenant-local Sales Organization and Distribution Channel pairs; duplicate assignment is an idempotent no-op and removal is blocked while any Sales Area uses the pair.', 'TIER_3_MAPPED', '/config/sales-orgs/assign-distribution-channel', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.662352+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('71dbdf59-14a5-4375-a591-d5128f1955d5', 'CFG.ORG.DISTCHANNEL.DEFINE', NULL, 'Distribution Channel definitions', 'CONFIG_ACTIVITY', 'SALES', 'Maintain tenant-local Distribution Channels; Sales Organization assignments and Sales Area combinations are separate.', 'TIER_2_CONFIGURED', '/config/distribution-channels', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.665111+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('8ba56b94-3f67-4dd0-b961-9a29ca67408a', 'CFG.ORG.DIVISION.DEFINE', NULL, 'Division definitions', 'CONFIG_ACTIVITY', 'SALES', 'Maintain tenant-local Divisions; Sales Organization assignments and Sales Area combinations are separate.', 'TIER_2_CONFIGURED', '/config/divisions', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.66745+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d81b25aa-47d8-4c61-96d3-610db12dcc58', 'CFG.ORG.SALESORG.ASSIGN_DIVISION', NULL, 'Assign Division to Sales Organization', 'CONFIG_ACTIVITY', 'SALES', 'Maintain tenant-local many-to-many Sales Organization/Division pairs; duplicate assignment is a no-op and removal is audited but blocked while any Sales Area uses the pair across all channels.', 'TIER_3_MAPPED', '/config/sales-orgs/assign-division', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.670143+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('5d3e105a-624f-4331-a786-420fb4bcc76c', 'CFG.ORG.SALESAREA.DEFINE', NULL, 'Sales Area', 'CONFIG_ACTIVITY', 'SALES', 'Maintain tenant-local Sales Area combinations; Distribution Channel and Division must be assigned to the selected Sales Organization through OVXK and OVXA.', 'TIER_3_MAPPED', '/config/sales-areas', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.672801+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('f1dd9ee5-5caf-4d53-8079-5b73d282abff', 'CFG.PROC.PURORG.DEFINE', NULL, 'Purchasing Organisation definitions', 'CONFIG_ACTIVITY', 'PROC', 'Define the tenant-local code and name, retain change history and deactivate; Company Code and Plant assignments remain separate, and supplier-purchasing use requires one Company Code.', 'TIER_2_CONFIGURED', '/config/purchasing-orgs', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.675361+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('44dcd778-b803-45c8-b906-3ed2e5ce4bf8', 'CFG.PROC.PURORG.ASSIGN_COMPANY', NULL, 'Assign Purchasing Organisation to Company Code', 'CONFIG_ACTIVITY', 'PROC', 'Make the initial assignment to exactly one active Company Code in the same tenant; replacement and unassignment are not included.', 'TIER_2_CONFIGURED', '/config/purchasing-orgs/assign-company', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.67893+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('46d696b3-40eb-4846-9a6f-816a65deb34f', 'CFG.PLT.CLIENT.DEFINE', NULL, 'Tenant administration', 'CONFIG_ACTIVITY', 'PLT', 'Create and manage tenants.', 'TIER_2_CONFIGURED', '/clients', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.682198+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d5461721-c162-4e13-b34c-24c1fd656157', 'FIN.JOURNAL.LIST', NULL, 'G/L line item report', 'TRANSACTION', 'FIN', 'Read posted G/L line items straight from the canonical journal: account ranges, company, fiscal-year and date filters, open and cleared judged from the clearing document on open-item-managed accounts only, subtotals per currency, a server-enforced hit cap with a truncation signal, and drill-through into the document display. Strictly read-only; closed periods stay displayable. The SCR-108/109 reporting suite adds the assignment column, true pagination with totals, CSV export, document-date and reference columns, and a return link to the originating balance report.', 'TIER_1_BUILT', '/finance/journal/items', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.700402+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('7112f4d9-a460-4005-b16a-bb59fd11f746', 'FIN.GL.BALANCE', NULL, 'G/L account balances by period', 'TRANSACTION', 'FIN', 'Opening balance, period debit and credit turnover, net change and cumulative closing for one account, derived from the posted journal at read time on the SCR-069 precedent: opening is every earlier year summed, never period 1 turnover; special periods stand apart when configured; currencies are never combined, and each period drills into the line-item report by stored posting period. Strictly read-only. The SCR-108/109 reporting suite adds a range balance report over company and account ranges with company/account-group subtotals, split debit and credit balances, an optional output currency converted through the standing ratio-aware rates (a missing rate warns instead of converting wrongly), and drill-down carrying period context.', 'TIER_1_BUILT', '/finance/journal/balances', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.704267+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('08f81ee3-c8bc-427d-83d1-816bdeb93730', 'FIN.DOC.FLOW', NULL, 'Accounting document display and flow', 'TRANSACTION', 'FIN', 'One posted document by its complete key — number, company and fiscal year, the year never derived — with the full header, every line and assignment, totals judged per stored currency, flow to the reversal chain, clearing documents and origin, previous/next navigation, and the retained change history. Parked documents answer as their own lifecycle. Strictly read-only; reversal is displayed, never performed here.', 'TIER_1_BUILT', '/finance/journal/document', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.707269+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('34d973f8-c06f-4391-a294-8828a4e13c8e', 'FIN.ASSET.CREATE', NULL, 'Create asset master', 'TRANSACTION', 'FIN', 'Create fixed asset master data under its complete key: tenant-configured asset classes govern numbering (internal range or validated external), quantity and depreciation defaults; similar assets become distinct main numbers atomically; sub-numbers hang from a standing main. Assignments stand as dated intervals and depreciation parameters per configured area. Master data only — no acquisition posts.', 'TIER_1_BUILT', '/finance/assets/new', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.71022+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('c1d86948-0040-4dcf-bc99-92f89dc15a92', 'FIN.ASSET.ACQUIRE', NULL, 'Acquire asset against offsetting account', 'TRANSACTION', 'FIN', 'Post an asset acquisition to the asset class reconciliation account against an entered offsetting G/L account, without a vendor. Guided: entry, validation, simulation, confirmation. The engine document is the financial authority and a value transaction rides it; reversal is asset-aware so the value record cannot be orphaned. First acquisition capitalizes at the asset value date.', 'TIER_1_BUILT', '/finance/assets/acquire', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.713379+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('3baeb2b4-3ed8-44ee-bc65-156d24e71fab', 'FIN.ASSET.RETIRE', NULL, 'Retire asset by scrapping', 'TRANSACTION', 'FIN', 'Retire an asset by scrapping without proceeds: complete or partial (percentage of, or an acquisition-value amount against, the remaining retireable value). The retired acquisition value is credited to the class reconciliation account, accumulated depreciation reversed for its proportional share, and the remaining book value written off to the class loss account, in one engine document riding a retirement value record. Complete retirement retires the asset; reversal is asset-aware and restores eligibility.', 'TIER_1_BUILT', '/finance/assets/retire', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.716299+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('95a3852b-eac5-4b8d-91e5-6bd722cde7b2', 'FIN.ASSET.DEPRECIATE', NULL, 'Depreciation run', 'TRANSACTION', 'FIN', 'Calculate and post planned depreciation per asset and depreciation area for a company, fiscal year and period: test runs log without touching a balance; live runs post one balanced engine document (depreciation expense against accumulated depreciation) and record posted depreciation per asset and period, which repeat runs adjust and retirement reversals read. Planned, repeat and restart run types; unplanned depreciation awaits its extraordinary-transaction round.', 'TIER_1_BUILT', '/finance/assets/depreciate', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.719106+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('dfc0e76d-4fa4-430d-8e22-93d26567a6cd', 'FIN.RPT.TRIALBALANCE', NULL, 'Trial balance / financial statement', 'TRANSACTION', 'FIN', 'Read-only F.01 statement over the configured financial statement version, whose hierarchy, account ranges and presentation signs resolve dynamically — nothing statutory is hardcoded. Balances derive from the posted journal in one snapshot: opening from every earlier year, debit and credit turnover from the selected period range (special periods only when included), balance at the cutoff as opening plus turnover through it, comparative figures by the identical rules with explicit zero-denominator variance handling. Accounts with balances but no FSV assignment are named in warnings and listed, never silently dropped; overlapping assignments count once and warn. Output currency converts through the standing ratio-aware rates, flagging a missing rate instead of converting wrongly.', 'TIER_1_BUILT', '/finance/trial-balance', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.722075+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d26684d6-b7c9-4202-99ea-1d98361bb1bf', 'FIN.RPT.BALANCESHEET', NULL, 'Balance sheet / profit and loss statement', 'TRANSACTION', 'FIN', 'Read-only balance sheet and profit and loss statement over the configured financial statement version, deriving every figure from the posted journal in one snapshot — no persisted totals. Three balance calculation types: accumulated closing (opening plus movements through the cutoff), period movement strictly inside the selected range, and combined presentation taking closing balances for balance-sheet accounts and period movement for profit and loss accounts, carrying the net profit-and-loss movement as the explicit current-year result beside the retained-earnings balance. A summary report level folds deeper FSV nodes into their displayed ancestor without changing any figure. Comparative ranges validate independently and follow the identical rules, with explicit zero-denominator variance handling; output currency converts through the standing ratio-aware rates, flagging a missing rate. Accounts with balances but no FSV assignment are named, never dropped; drill-down reaches account balances and journal line items.', 'TIER_1_BUILT', '/finance/balance-sheet', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.724788+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('86bb8bbe-1979-4b18-8642-69bb6b7c8511', 'FIN.RPT.COSTCENTER.ACTUAL', NULL, 'Cost centre actual/plan report', 'TRANSACTION', 'COST', 'Read-only cost centre actual/plan/variance report over journal cost lines: actuals are the posted journal lines carrying a cost centre, aggregated by cost element in controlling-area currency for the selected period range beside periods 1..cutoff. Plan values come from the plan table by version (default 000) signed by account type; a missing plan stays missing, never zero, and variance percentage stays null on missing or zero plan. Status follows the signed variance. Centres roll up the standard hierarchy with placement judged at fiscal-year end, groups resolve through ranged leaves, centres without validity in the year are excluded and named, and planned activity quantities and fixed/variable prices read the standing activity rates while actual quantities stay empty. Drill-down reaches journal line items; the report never posts.', 'TIER_1_BUILT', '/controlling/cost-center-report', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.728687+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('6341a3c6-1915-462f-aa1a-9916bdb54b48', 'FIN.RPT.PROFITCENTER', NULL, 'Profit centre actual line items', 'TRANSACTION', 'COST', 'Read-only profit centre actual line items over the posted journal: every line carrying a profit centre exactly as recorded at posting, filtered by controlling area, profit centre range or configured group, fiscal year, period range, leading ledger, G/L account range and document range. Lines show company, document, dates, type, account, debit/credit, signed document and local amounts, assignment, reference, text and the recorded originating objects; totals stand by profit centre, account and currency with document and local totals kept separate. A server-side maximum-hits limit windows the lines and truncation is always indicated; closed periods never suppress history; each document drills to the accounting document display with the GET selection preserving context. Partner profit centre, account groups and plan line items are not carried.', 'TIER_1_BUILT', '/controlling/profit-center-report', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.734448+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('3f4f27c2-794f-4299-89f6-5598ce0c56d0', 'FIN.RPT.SUBLEDGER.TIE', NULL, 'G/L to subledger tie-out', 'TRANSACTION', 'FIN', 'Read-only tie-out matching the G/L balance of each reconciliation account against its subledger total, in the shape of FS10N against FBL1N/FBL5N: per company, fiscal year and cumulative periods, every CUSTOMERS or VENDORS reconciliation account shows the total over all posted lines beside the total over lines carrying a business partner, the difference named tied or exception and never netted away. Partner rows break the subledger total down, partnerless lines stand as counted exception detail, and partners posting away from their segment-assigned reconciliation account are named. Account rows drill to the journal line-item report. Asset and material reconciliation types and non-cumulative movement comparison are not carried.', 'TIER_1_BUILT', '/finance/subledger-tie-out', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.736929+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('6426421d-288f-405c-84db-222f1c02b7cb', 'FIN.RPT.PROFITLOSS', NULL, 'Profit and loss statement', 'TRANSACTION', 'FIN', 'Read-only profit and loss statement over the configured financial statement version: only profit-and-loss accounts are presented, balance-sheet-only subtrees drop away and node totals re-roll from the kept accounts, so no balance-sheet figure leaks into a profit-and-loss total. Every account and node carries the movement strictly inside the selected range beside the cumulative year-to-date movement through the cutoff, independent comparatives with explicit zero-denominator variance handling, and the explicit current-year result. Summary levels fold presentation only; unassigned profit-and-loss accounts are named, never dropped; drill-down reaches account balances and journal line items.', 'TIER_1_BUILT', '/finance/profit-loss', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.740529+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('24a16168-787b-4768-aa78-5e9c25f3e08c', 'FIN.CREDIT.RELEASE', NULL, 'Release credit-blocked documents', 'TRANSACTION', 'FIN', 'The credit determination queue for blocked sales documents: each determination is the single authoritative credit status for its document, recorded from the credit-check evaluation with its reason and check-time figures, and superseded — never edited — by every recheck, release, rejection and reblock in an append-only event trail. Release re-evaluates against the current standing and only releases on a passing fresh check; a still-failing document requires the separate override privilege with mandatory justification and approval reference, and is never silently bypassed. Rejecting a release request leaves the document blocked and untouched; reblocking always runs a fresh determination first. A release creates no delivery, invoice or accounting entry.', 'TIER_1_BUILT', '/finance/credit-release', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.742735+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('ece77067-d98b-444b-9c40-29c0f0b2a352', 'FIN.CREDIT.MONITOR', NULL, 'Credit exposure monitor', 'TRANSACTION', 'FIN', 'Read-only credit overview per customer and credit control area, computed at execution time in one consistent snapshot: configured limit, open receivables exposure, available credit (negative when exceeded), utilization with zero and missing limits explicit, risk, holds and expired limits. Customers carrying exposure without a credit record are flagged, never hidden; order, delivery and billing components show as unavailable until the sales canon stands, never as silent zeros. Filters judge areas, companies, customer ranges, risk and representative groups; a reporting currency converts through the standing ratio-aware exchange rates, flagging rows whose rate is missing. Nothing here changes master data, posts, blocks or unblocks.', 'TIER_1_BUILT', '/finance/credit-monitor', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.745478+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('3ab989f5-26e7-4bfb-8a97-880f3433ef0f', 'FIN.CREDIT.MAINTAIN', NULL, 'Customer credit management', 'TRANSACTION', 'FIN', 'Credit management per customer and credit control area on the canonical partner and area masters: limit in the area currency at its precision, risk category, representative group, customer credit group, limit validity and manual holds behind configured block reasons — every reference judged against standing configuration, every save stating its reason and landing one append-only audit row per changed field, protected by an optimistic-locking version. Exposure derives at read time from open receivables across the companies of the area, so available credit and utilization are always current, and the credit-check evaluation never bypasses: a missing record, a hold, an expired or zero limit, or an exceeded limit blocks, and the area warning threshold warns.', 'TIER_1_BUILT', '/finance/credit', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.749526+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('042d2f1f-a5c0-4dff-87d9-c1c3854a56c4', 'FIN.CLOSE.CARRYFORWARD', NULL, 'G/L balance carryforward', 'TRANSACTION', 'FIN', 'Balance carryforward from a source year into the target year for the leading ledger and selected company codes, test-run by default. Balance-sheet openings derive from the posted journal — no duplicate balance table — and are recorded per account, currency and profit centre; profit-and-loss accounts close through a real judged transfer document at the source year-end against the retained earnings account from account determination, never by deleting history. Repeat runs recompute the still-untransferred balance and post only the delta, so late prior-year adjustments flow through safely; a concurrent update run over the same scope is refused while test runs never block. The run protocol preserves every execution with its parameters, totals, exceptions and transfer documents — and never closes the prior year or locks a period.', 'TIER_1_BUILT', '/finance/carryforward', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.75185+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('f3553f8b-644e-4438-840b-ec69f6c464e9', 'FIN.CLOSE.COCKPIT', NULL, 'Period-end close cockpit', 'TRANSACTION', 'FIN', 'Period-end closing cycles as task lists: reusable templates become period-specific task instances over a company, fiscal year and posting period, with dependency edges (circles refused), owners, critical-path flags and due dates. Tasks execute only through the registered handler catalogue — period status report, due accrual reversals, foreign-currency valuation, manual confirmation — behind predecessor gating and an atomic execution claim, so one instance never runs twice at once; background executions stand scheduled until the scheduled runner settles them. A task completes only when its handler succeeds and required evidence and sign-off stand; failures keep their logs and retry; overrides and reopens require reasons and preserve history in the append-only event trail. Finalizing a list is refused while any task stands open — and never closes or locks the financial period.', 'TIER_1_BUILT', '/finance/close-cockpit', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.755747+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('5942c767-e855-4003-9f1c-9151934ac356', 'FIN.ACCRUAL.POST', NULL, 'Accrual/deferral documents', 'TRANSACTION', 'FIN', 'Enter an accrual or deferral document on the judged G/L entry: reversal date and a standing reversal reason are required at entry and are stored as metadata on the canonical document in the same transaction. When the reversal date falls due, the reversal processing lists the document and posts its mirror through the canonical document-reversal workflow — exactly one reversal ever, reconciled from the standing link on any retry. Posted documents are immutable; drafts park through the parked-journal workflow.', 'TIER_1_BUILT', '/finance/accruals', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.761821+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('ff1a2498-d79c-4b37-b237-681458f0ca16', 'FIN.GRIR.RECLASS', NULL, 'GR/IR clearing account analysis', 'TRANSACTION', 'FIN', 'GR/IR clearing account analysis per purchase order item as of a key date: goods-receipt history signed by movement direction and valued at the order price, invoice history signed by category with cancellations excluded, and the open quantity and value classified as reconciled, goods received not invoiced, invoiced not received, quantity difference or value difference. Analysis never posts; a live run with accrual creation posts the open value per item against the GR/IR clearing account from account determination, once per item and fiscal year, with an optional reversal on the named date, and the protocol persists for export.', 'TIER_1_BUILT', '/finance/grir-reclass', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.76589+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('91ac39c5-3918-450f-9d8c-a49209d30337', 'FIN.FX.VALUATE', NULL, 'Foreign currency valuation', 'TRANSACTION', 'FIN', 'Foreign currency valuation at a key date: foreign-currency open items and balance-sheet balances are revalued at the latest standing rate of the chosen rate type (a missing rate is a named error, never a substituted rate), adjustments are classified gain or loss under one signed rule and resolved through FX gain/loss account determination, and a live run posts one balanced document through the posting engine with the full protocol persisted, duplicates refused per item, area and key date, and an optional reversal on the named date. Test runs persist only the protocol.', 'TIER_1_BUILT', '/finance/fx/valuation', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.768364+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('0a2fb2cf-1855-45f2-a659-060732406e88', 'FIN.TAX.REPORT', NULL, 'Advance return for tax on sales/purchases', 'TRANSACTION', 'FIN', 'Advance return for tax on sales and purchases over a posting-date window: posted tax lines by tax code and account key, input tax against output tax, the tax base derived from the standing rate and labelled derived, and the net payable or receivable. Test runs change no source document; an update run records the return, stamps the reported lines so they are not reported twice (a corrected return re-includes them), and may post the net clearing transfer through the posting engine. Statutory electronic file formats are not configured in the product and are deferred by name.', 'TIER_1_BUILT', '/finance/tax/report', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.77089+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('d96d54bd-d144-4128-b358-78450730531e', 'FIN.ASSET.REPORT', NULL, 'Asset history sheet', 'TRANSACTION', 'FIN', 'Read-only asset history sheet for a fiscal year and depreciation area: beginning balances from value-dated movements before the year, current-year acquisitions and retirements, posted depreciation only (test runs never count), accumulated depreciation removed on retirements, and net book values — reconciled per asset with subtotals per class and currency. Runs from a judged selection and exports CSV; running it writes nothing.', 'TIER_1_BUILT', '/finance/assets/history', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.774007+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('7e28c3da-3895-4c0f-8955-d5a02364e184', 'FIN.ASSET.CHANGE', NULL, 'Change asset master', 'TRANSACTION', 'FIN', 'Change asset master data under optimistic version control: identity, company and class never move; assignment changes append intervals so history is preserved; depreciation-key and life changes apply prospectively and are audited; deactivation is a reasoned status, never a retirement. Every change lands on the change-document audit.', 'TIER_1_BUILT', '/finance/assets', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.776584+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('67e1f348-0df0-40ab-b3c5-8aaa8e3ebb5a', 'FIN.JOURNAL.DISPLAY', NULL, 'Display an accounting document', 'TRANSACTION', 'FIN', 'Line items, account assignments and the document flow.', 'TIER_1_BUILT', '/finance/journal', 'A', NULL, true, 'SEED', '2026-11-10 08:54:14.779009+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('ee40ca8c-e3ba-46f7-b72a-68df0e6d5235', 'CFG.PLT.NUMBERRANGE.DEFINE', NULL, 'Number range maintenance', 'CONFIG_ACTIVITY', 'PLT', 'Number range objects and their intervals, at the reference parity. Objects answer to SAP-width names (RF_BELEG, MATERIALNR and their fellows); the registry keeps each object description, number length, consumption warning and year relevance, while object names belong to the application and are never created or deleted on a screen. Intervals stand per object, scope and year with their bounds protected once numbers are issued, overlap refused, and blocking as the standing disable. Internal intervals assign the next number atomically inside the posting transaction, gap-free; external intervals hold numbers the user supplies; a buffered interval reserves a block of its configured quantity in its own committed step, so a document that rolls back leaves its number consumed and the gap visible. The current number may be set only through its own guarded act, warning when the target would re-issue numbers already given out. MMNR groups for material types stand on this engine as their own activity.', 'TIER_2_CONFIGURED', '/config/number-range-objects', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.782595+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('df8a7154-4296-4927-a1ba-4490de94d85d', 'CFG.INV.BATCHCONVERT.DEFINE', NULL, 'Batch level and status conversion', 'CONFIG_ACTIVITY', 'INV', 'Batch level and status conversion check. OMCT is a search alias only. It is not OMCE and not OMCS. The current level and status are shown. A proposed target is checked for duplicate batch identities, a missing plant, stock, material documents, the other batch class type, a restricted-use indicator, and a plant status selection. A dry run writes nothing. A confirmed check records the finding and does not change the level, the status, a batch, stock, or a document. Two batches are not merged. Movements 341 and 342 are not posted. Live conversion is not available. A closed posting period does not block the check. Opening this screen writes nothing.', 'TIER_2_CONFIGURED', '/config/batch-conversion', 'B', NULL, true, 'MIGRATION_9143', '2026-11-10 08:54:11.555901+00', 'SEED', '2026-11-10 08:54:14.793148+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('9716f41d-d92b-4ee7-9af7-0ff0af06c21e', 'CFG.INV.BATCHCLASSIFY.DEFINE', NULL, 'Batch classification for goods movements', 'CONFIG_ACTIVITY', 'INV', 'Batch classification for goods movements. OMCV is a search alias only. The control is KZCLA on the standing movement type. Blank is no branching. 1 is background for all batches. 2 is foreground for mandatory characteristics, all batches. 3 is always foreground, all batches. 4 is foreground for new batches only. A non-blank code cannot classify while class type 023 is inactive, so the goods movement is refused before stock or a journal. Characteristic copying, WIP-batch adoption, and extended CFC are not stored and are not functional. A posted movement is not rewritten. This screen does not create a movement type and does not change its posting rules. A transport and a plant are refused. Opening this screen writes nothing.', 'TIER_2_CONFIGURED', '/config/batch-classification', 'B', NULL, true, 'MIGRATION_9132', '2026-11-10 08:54:11.496658+00', 'SEED', '2026-11-10 08:54:14.80063+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('bdcd8438-d3d3-4359-9143-2edd1f4e289e', 'CFG.INV.BATCHALLOCATE.DEFINE', NULL, 'Allocate IM search procedure', 'CONFIG_ACTIVITY', 'INV', 'Allocate an Inventory Management search procedure. OMCG is a search alias only. The key is the movement type and the special stock. Blank special stock is own stock, not a plant and not a wildcard. Special-stock indicators do not stand, so only own stock can be allocated. The procedure must already stand on OMCY for usage H and application ME. A transfer-side procedure is optional and must also stand. The check indicator is X or blank. X records the request and does not check a batch, because selection criteria do not stand. A plant, a transport, and a production or sales allocation are refused. Opening this screen writes nothing.', 'TIER_2_CONFIGURED', '/config/batch-search-allocations', 'B', NULL, true, 'MIGRATION_9139', '2026-11-10 08:54:11.53305+00', 'SEED', '2026-11-10 08:54:14.809114+00') on conflict do nothing;
INSERT INTO public.term_registry VALUES ('0c040d42-d180-4197-b17b-28e6448ace83', 'INV.BATCH.COCKPIT', NULL, 'Batch information cockpit', 'TRANSACTION', 'INV', 'Batch information cockpit. BMBC is a search alias only. It reads a batch that already stands, including one with no material document. Stock is summed from the stock master and is not multiplied by document lines. Restricted use is not a stock category. Direct material-document lines name a purchase order, a production order, and the supplier on that purchase order. Top-down and bottom-up genealogy are not stored. A class, a characteristic value, an inspection lot, a sales order, a delivery, a billing document, and a scheduling agreement are refused by name. Opening this screen writes nothing. A closed posting period does not block it.', 'TIER_1_BUILT', '/inventory/batch-cockpit', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.834276+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('da5b53ee-7451-43b1-88b7-efc8db584b17', 'PLT.REGISTRY.SEARCH', NULL, 'Term registry search', 'CONCEPT', 'PLT', 'Find any screen, table, configuration activity or concept by our code or by a familiar alias.', 'TIER_1_BUILT', '/registry', 'B', NULL, true, 'SEED', '2026-11-10 08:54:14.836796+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_registry VALUES ('f25bcec7-e257-46be-bd53-68c50ca913c8', NULL, 'journal_entry_line', 'Accounting document line', 'TABLE', 'FIN', 'Universal journal line: every account assignment on one row.', 'REFERENCE', '/registry', NULL, NULL, true, 'SEED', '2026-11-10 08:54:14.838092+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_alias VALUES ('35b4b74c-c9f7-49c2-90db-2ea12ccbec3a', '796a4abc-774d-4855-b754-77c176711bdf', 'REFERENCE_ERP', 'FS00', 'SEARCH_ONLY', 'SCR028_MIGRATION', '2026-11-10 08:54:10.447949+00', NULL, NULL) on conflict do nothing;
