INSERT INTO public.term_alias VALUES ('3147354d-2c95-450e-8080-02278b5364cc', '0790bcec-8d30-4d50-9c22-97cfb4133255', 'REFERENCE_ERP', 'MB5L', 'SEARCH_ONLY', 'SCR144_MIGRATION', '2026-11-10 08:54:11.231999+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_alias VALUES ('8c212047-ba7f-47d3-92ab-1069f3ca6baf', '232fcc9f-4141-4bf2-853a-9e71332f6eeb', 'REFERENCE_ERP', 'MBRL', 'SEARCH_ONLY', 'SCR145_MIGRATION', '2026-11-10 08:54:11.241943+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_alias VALUES ('29a9b89a-71de-43b4-8084-854dec9f9319', 'c8ef502f-5df5-44fe-a2f7-a1eccf1a8f49', 'REFERENCE_ERP', 'OMJJ', 'SEARCH_ONLY', 'MIGRATION_9103', '2026-11-10 08:54:11.37938+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_alias VALUES ('6f0476f0-2362-498f-8b07-f3b677234e89', 'f7722805-3526-4796-ad72-e35b3d17c5f3', 'REFERENCE_ERP', 'OX17', 'SEARCH_ONLY', 'MIGRATION_9104', '2026-11-10 08:54:11.382391+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_alias VALUES ('eea044fc-801c-4d01-ad95-2fdb507a239d', '17760c2c-e9c6-44ff-9173-13ffca29b70b', 'REFERENCE_ERP', 'SM12', 'SEARCH_ONLY', 'MIGRATION_9105', '2026-11-10 08:54:11.386216+00', NULL, NULL) on conflict do nothing;
INSERT INTO public.term_alias VALUES ('420c0317-4c4a-41a1-b88f-403259d7c706', '373dfd84-5fea-4ad4-a575-1d9214d677fa', 'REFERENCE_ERP', 'OMSK', 'SEARCH_ONLY', 'MIGRATION_9106', '2026-11-10 08:54:11.391538+00', NULL, NULL) on conflict do nothing;
